INSERT INTO public.events (id, title, official_url, registration_url, registration_is_direct, start_at, end_at, venue, address, city, event_type, hosted_by, speakers, description, about, source_urls, last_verified_at)
VALUES
  ('enterprise-ai-mind-the-gap-a-talk-on-intelligence-applications-at-scale-by-ai-pr@aiweek.boston', 'Enterprise AI: Mind the gap! A talk on intelligence applications at scale by AI practitioners!', 'https://aiweek.boston/schedule/enterprise-ai-mind-the-gap-a-talk-on-intelligence-applications-at-scale-by-ai-pr', 'https://aiweek.boston/schedule/enterprise-ai-mind-the-gap-a-talk-on-intelligence-applications-at-scale-by-ai-pr', FALSE, '2026-08-24T18:00:00-04:00'::timestamptz, '2026-08-24T19:00:00-04:00'::timestamptz, 'Findability Sciences Office at Workbar Burlington', '100 Summit Dr, Ste 917, Burlington, MA 01880', 'Burlington', 'Talk', 'Findability Sciences', '[{"name":"Sagar Mahurkar","bio":"Vice President at Findability Sciences, leading accounts, technology, and investor relationships across the US, Japan, and India. He holds five US patents, is a TEDx speaker and IEEE Best Paper Award winner, and has shipped enterprise AI and AR applications to tens of millions of users."}]'::jsonb, 'Enterprise AI: Mind the gap! A talk on intelligence applications at scale by AI practitioners!', 'There is a gap between data and decisions in most enterprises. To bridge this gap, you need to set up a factory that produces intelligence at scale. The factory runs on a framework recognized by IDC, Gartner, and Google. ICUPP: Infrastructure, Collection, Unification, Processing, and Presentation of Data.

A talk by Sagar Mahurkar, followed by networking, food, and beverages. Sagar is a TEDx Speaker, IEEE award-winning researcher, and holds 5 patents. He brings together the experience of Findability Sciences, a Fortune America''s Most Innovative Company, across 250+ AI deployments.

During the event, you''ll get to meet senior executives from Findability Sciences and mingle with AI practitioners.', ARRAY['https://aiweek.boston/schedule/enterprise-ai-mind-the-gap-a-talk-on-intelligence-applications-at-scale-by-ai-pr']::text[], now()),
  ('boston-ai-week-meets-the-world@aiweek.boston', 'Boston AI Week Meets the World', 'https://aiweek.boston/schedule/boston-ai-week-meets-the-world', 'https://aiweek.boston/schedule/boston-ai-week-meets-the-world', FALSE, '2026-09-16T11:00:00-04:00'::timestamptz, '2026-09-16T13:00:00-04:00'::timestamptz, 'Private — location shared with invited guests', NULL, NULL, 'Summit', 'Boston AI Week', '[]'::jsonb, 'Boston AI Week Meets the World', 'Time: to be announced. Location: private — shared directly with invited guests.

Boston AI Week Meets the World opens the 2026 festival. Representatives from 18 countries travel to Boston to spend the morning with the Boston AI Week Board of Directors, exploring how a globally recognized festival of AI is built — and how that model can travel home with them.

Together we will discuss how artificial intelligence can advance freedom, prosperity, and peace, and how American values, ingenuity, and openness can be carried to communities around the world.

This is a private, invitation-only session. You are welcome to RSVP to be considered, but space is extremely limited and we apologize that we will not be able to accommodate every request.', ARRAY['https://aiweek.boston/schedule/boston-ai-week-meets-the-world']::text[], now()),
  ('hey-hub-come-here-bostons-voice-ai-meetup@aiweek.boston', 'Hey Hub Come Here- Boston''s Voice AI Meetup', 'https://aiweek.boston/schedule/hey-hub-come-here-bostons-voice-ai-meetup', 'https://luma.com/gqxuajjg', TRUE, '2026-09-16T17:00:00-04:00'::timestamptz, '2026-09-16T19:30:00-04:00'::timestamptz, 'Build617', '38 Chauncey Street, Boston, MA (Downtown Crossing)', 'Boston', 'Meetup', 'Boston Voice AI Meetup', '[{"name":"Tom Elliott","bio":"Organizer of the Boston Voice AI Meetup."},{"name":"Nick Leonard","bio":"Co-Founder and CEO of VoiceRun."}]'::jsonb, 'Hey Hub Come Here- Boston''s Voice AI Meetup', 'The inaugural Boston Voice AI Meetup is happening at Build617!

Join founders, product leaders, and developers interested voice AI. Are you a:

vendor selling voice AI technologies to other businesses?

product leader deploying voice agents for customer interaction?

developer exploring use cases and technologies?

founder considering voice as UX for your startup?

You''ll enjoy a mix of networking, learning, sharing, humor, and light snacks/drinks.

SEPTEMBER TOPIC:

"When Should Software Talk Back? Exploring conversational voice agents embedded in software UX."

2026 is the year that conversational voice agents escaped the 1-800 support line. And it''s more than developers whispering into their goosenecks- real users are conversing with business software in the office, the car, the job site, and the soccer sideline.

How should product leaders think about this new interaction pattern? When is it useful, and when is it fluff?

And what technologies and tactics afford the best conversational UX?

You''ll hear from a mix of voice AI vendors, developers, and product leaders about when, why, and how they let their product converse.

Bring your questions and use cases as well- this is a participatory learning experience.

Venue: Build617', ARRAY['https://aiweek.boston/schedule/hey-hub-come-here-bostons-voice-ai-meetup']::text[], now()),
  ('ai-insights-summit-2026-a-free-3-day-virtual-ai-event-with-45-experts@aiweek.boston', 'AI Insights Summit 2026: A Free 3-Day Virtual AI Event with 45+ Experts', 'https://aiweek.boston/schedule/ai-insights-summit-2026-a-free-3-day-virtual-ai-event-with-45-experts', 'https://aiinsightssummit.com/?fpr=anec_ventures', TRUE, '2026-09-17T09:45:00-04:00'::timestamptz, '2026-09-19T16:30:00-04:00'::timestamptz, NULL, NULL, NULL, 'Conference', 'RenegAIDE Collective', '[{"name":"Alicia Lyttle","bio":"Summit host; AI strategist, TEDx speaker, bestselling author, and one of JPMorgan Chase''s 100 Women to KNOW in America."},{"name":"Dr. Tesha D Colston","bio":"Master of Ceremonies for the summit."},{"name":"Alicia Anderson","bio":null},{"name":"De''Chelle Beckham","bio":null},{"name":"Kerri Bonner","bio":null},{"name":"Alicia Bowens","bio":null},{"name":"Carlos Boyd","bio":null},{"name":"Kiara Cansler","bio":null},{"name":"Dr. LaKrishia Cook","bio":null},{"name":"Cheryl Dezelle","bio":null},{"name":"Sherron Ellis","bio":null},{"name":"Allyson Gideon","bio":null},{"name":"Trace Godoy","bio":null},{"name":"Charnell Gulley","bio":null},{"name":"LJ Hannah","bio":null},{"name":"Sonya Hightower-Routt","bio":null},{"name":"Patricia Hylton","bio":null},{"name":"Katie Ireland","bio":null},{"name":"Pharah Jean-Philippe","bio":null},{"name":"Yvette L. Jones","bio":null},{"name":"Louis Joseph","bio":null},{"name":"Mariquita Joy","bio":null},{"name":"Karriem Kanston","bio":null},{"name":"Marta Knittel","bio":null},{"name":"Daphne R. Robinson","bio":null},{"name":"John P. Turner","bio":null},{"name":"Labrisha A. Mason","bio":null},{"name":"Sierra McCray","bio":null},{"name":"Chriselide Mendez","bio":null},{"name":"Tokunbo Okanla","bio":null},{"name":"Alicia Partee","bio":null},{"name":"Dr. Elizabeth Conerly Smith","bio":null},{"name":"Shonia Ranczie","bio":null},{"name":"Tiffany Richburg","bio":null},{"name":"Vondell Richmond","bio":null},{"name":"Alana Rollock","bio":null},{"name":"Jonathan Schafer","bio":null},{"name":"Marla Shinault-Davis","bio":null},{"name":"LaDonna Slade","bio":null},{"name":"Marcita Spencer","bio":null},{"name":"Cheryll Stewart","bio":null},{"name":"Antoinette Triplett","bio":null},{"name":"Tiffane Warren","bio":null},{"name":"Zoe Williams","bio":null},{"name":"Kimberly Williams","bio":null},{"name":"Michael D. Wynn","bio":null},{"name":"Lashonya N. Young","bio":null},{"name":"Wallena Randall","bio":null}]'::jsonb, 'AI Insights Summit 2026: A Free 3-Day Virtual AI Event with 45+ Experts', 'Another week, another wave of AI headlines, and most business owners, educators, nonprofit leaders, and working professionals still cannot say what any of it means for their Monday morning. The tools keep multiplying, the hype keeps rising, and the honest question stays unanswered: where does AI actually fit in my work, and what should I do about it?

The AI Insights Summit answers that question in three days. It is a free, 100% virtual event running September 17 to 19, 2026, bringing together 45+ experts from business, education, healthcare, law, human resources, and technology to show how AI is being used today, where the opportunities are emerging, what leaders need to understand, and what may be coming next.

RenegAIDE Collective invites the Boston AI Week community to join us. Founder Dr. Beth Griffith holds the AI Certified Authority credential from AI InnoVision, the summit''s presenter, and vouches for the format: less hype, more insight.

What makes this summit different:

• 18-minute power sessions. Each expert gets roughly 18 minutes to deliver their strongest ideas, frameworks, case studies, or live demonstrations.

• Zero speaker pitches. This is a learning-first event; speakers are not selling programs or services from the stage.

• Expert gifts. Many speakers share resources after their session so you can keep learning and implementing.

Hosted by Alicia Lyttle, AI strategist, TEDx speaker, bestselling author, and one of JPMorgan Chase''s 100 Women to KNOW in America, with Dr. Tesha D Colston as Master of Ceremonies.

A taste of the lineup:

• Business Grants + AI: Find the Money to Hire and Train Your Team (Karriem Kanston)

• AI Ready Workforce: Building the Human Foundations That Will Support AI Implementation (Kerri Bonner)

• Your AI Executive Team: How I Built a 9-Member AI-Powered Team to Help Me Run Multiple Businesses Without a Full Staff (De''Chelle Beckham)

• Guardrails Before Guidance: Responsible AI Use in Nursing Without Losing Clinical Judgment (Charnell Gulley)

• From Prompt to Partner: Using AI to Think Through Real Classroom Challenges (Allyson Gideon)

• Beyond the Chatbot: What an AI Agent Can Do for Your Legal Practice (Daphne R. Robinson, JD MPH)

What you walk away with:

• Practical, actionable AI strategies across five tracks: Operate (implementation, productivity, automation, and Digital Helpers, also called AI agents), Grow (marketing, customer experience, and revenue opportunities), Teach & Care (education, workforce development, and healthcare), Govern (AI governance, compliance, and responsible AI), and Create (generative AI and creative applications).

• A clear picture of where AI fits in your business, classroom, practice, or organization.

• Resources from the speakers so you can put the insights to work right away.

Who should attend: business owners and entrepreneurs, corporate leaders, professionals, educators and trainers, healthcare professionals, consultants and coaches, creators and marketers, AI beginners, and AI professionals. No coding or technical background required.

Schedule: Thursday, September 17 through Saturday, September 19, 2026. Sessions run from approximately 9:45 AM to 4:30 PM ET each day. Attend live from anywhere and choose the sessions most relevant to you. Recordings are available through an optional VIP upgrade.

Registration is free.', ARRAY['https://aiweek.boston/schedule/ai-insights-summit-2026-a-free-3-day-virtual-ai-event-with-45-experts']::text[], now()),
  ('ai-in-medical-education-administration-whats-changing-and-how-to-prepare@aiweek.boston', 'AI in Medical Education Administration: What’s Changing and How to Prepare', 'https://aiweek.boston/schedule/ai-in-medical-education-administration-whats-changing-and-how-to-prepare', 'https://aiweek.boston/schedule/ai-in-medical-education-administration-whats-changing-and-how-to-prepare', FALSE, '2026-09-17T16:00:00-04:00'::timestamptz, '2026-09-17T17:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Panel', 'The Hope Group', '[]'::jsonb, 'AI in Medical Education Administration: What’s Changing and How to Prepare', 'AI in Medical Education Administration: What’s Changing and How to Prepare

Artificial intelligence is rapidly changing the way medical education administrators work. From drafting policies and communications to managing data, supporting accreditation, preparing presentations, and improving day-to-day workflows, AI tools are creating new opportunities while also raising important questions about accuracy, privacy, ethics, and appropriate use.

This panel will bring together perspectives from medical education and administration to explore what these changes mean for GME professionals today. Panelists will discuss how AI is already being used, where it can have the greatest practical impact, common concerns and barriers to adoption, and why human judgment remains essential.

The discussion will also provide an introduction to the AI in Medical Education Administration course, a six-week live virtual program designed specifically for GME leaders, program administrators, coordinators, and medical education staff. Participants will learn how to use AI to improve routine administrative work, support data and documentation needs, strengthen communication and meetings, create presentations and educational materials, assist with recruitment and branding, and develop ethical and compliant AI workflows.

Attendees will leave with a clearer understanding of how AI is reshaping medical education administration, practical examples of what is possible today, and a roadmap for building the skills needed to use these tools responsibly and effectively.', ARRAY['https://aiweek.boston/schedule/ai-in-medical-education-administration-whats-changing-and-how-to-prepare']::text[], now()),
  ('science-of-scaling-hubspot-case-hbs-2026@aiweek.boston', 'The Science of Scaling: Inside the HubSpot Case', 'https://aiweek.boston/schedule/science-of-scaling-hubspot-case-hbs-2026', 'https://scienceofscaling.co/mark-roberge-harvard-hubspot-case-study', TRUE, '2026-09-17T17:00:00-04:00'::timestamptz, '2026-09-17T19:10:00-04:00'::timestamptz, 'Harvard Business School', 'Harvard Business School, Boston, MA', 'Boston', 'Workshop', 'Stage 2 Capital and Harvard Business School', '[{"name":"Mark Roberge","bio":"Co-Founder & Managing Partner of Stage 2 Capital; was the fourth employee and founding CRO at HubSpot, where he scaled the go-to-market organization from zero revenue to IPO, and has been a member of the teaching faculty at Harvard Business School for over a decade."}]'::jsonb, 'The Science of Scaling: Inside the HubSpot Case', 'Application only — attendance is by acceptance, not RSVP. Apply on the host''s site; there is no RSVP for this event on Boston AI Week.

Join Mark Roberge, The Science of Scaling, and Stage 2 Capital for an exclusive founder experience hosted at Harvard Business School. This intimate session brings together a curated group of founders, sales leaders, and GTM operators to explore one of the most influential cases in startup growth: "HubSpot: Inbound Marketing and Web 2.0."

Through Harvard''s signature case discussion format, attendees will examine the strategic decisions that shaped HubSpot''s early growth — product-market fit, customer segmentation, pricing, and scaling a go-to-market organization. Following the session, the conversation continues over a founder reception.

Speaker: Mark Roberge, Co-Founder & Managing Partner, Stage 2 Capital. Mark was the fourth employee and founding CRO at HubSpot, where he scaled the go-to-market organization from zero revenue to IPO, and has been a member of the teaching faculty at Harvard Business School for over a decade.

Required pre-work: before applying, read the abstract of the Harvard Business School case study — application questions reference the abstract. You do not need to purchase the full case to apply; accepted attendees receive instructions for accessing it before the event.', ARRAY['https://aiweek.boston/schedule/science-of-scaling-hubspot-case-hbs-2026']::text[], now()),
  ('ai-native-dev-boston-inside-the-dark-factory@aiweek.boston', 'AI Native Dev Boston: Inside the Dark Factory', 'https://aiweek.boston/schedule/ai-native-dev-boston-inside-the-dark-factory', 'https://luma.com/ainative-u9dd', TRUE, '2026-09-17T18:00:00-04:00'::timestamptz, '2026-09-17T20:30:00-04:00'::timestamptz, 'Snyk Boston office', '100 Summer Street, 100 Summer St, Boston', 'Boston', 'Meetup', 'AI Native Dev', '[{"name":"Sahil Deshmukh","bio":"Member of Technical Staff at Tessl; previously built data infrastructure at MongoDB."},{"name":"Brendan Hann","bio":"Senior Product Marketing Manager at Snyk, focused on the developer experience and core analysis engines; lead for Snyk''s Boston community chapter."},{"name":"Ryan McMorrow","bio":"Staff Product Manager at Snyk, driving product vision and strategy for remediation and application security."},{"name":"Max Binshtok","bio":"Forward-Deployed Engineer at Qodo, working with engineering teams on AI-assisted development, code quality, and trustworthy adoption of coding agents."}]'::jsonb, 'AI Native Dev Boston: Inside the Dark Factory', 'AI is reshaping how software gets built, and the fastest way to keep up is a room full of people working it out in practice. For this Boston edition, the AI Native Dev community has teamed up with the AISecEng Community to bring together the people building with coding agents and the people making sure that''s done safely. Expect an evening of talks on both sides of that coin, from architecting a self-optimizing development pipeline to putting agents to work fixing security bugs. Whether you''re already shipping with coding agents or just starting to fold them into your workflow, you''ll leave with ideas you can put to work and new people to compare notes with.

Agenda

6:00pm Venue opens

6:30pm Talk 1: Building Your Dark Factory: Engineering the Future of AI-Powered Development by Sahil Deshmukh

7:00pm Talk 2: Remediation Agents Demystified: Your AI Teammate for Fixing Security Bugs by Brendan Hann & Ryan McMorrow

7:30pm Talk 3: The Verification Layer for the Dark Factory: How Coding Agents Earn Trust by Max Binshtok

8:00pm Networking

8:30pm THE END

Building Your Dark Factory: Engineering the Future of AI-Powered Development

Harness engineering is emerging as a new core competency for agentic engineers. Discover how Tessl is architecting a self-optimizing development pipeline, and what it means for engineering teams everywhere.

Remediation Agents Demystified: Your AI Teammate for Fixing Security Bugs

Mythos made it clear - finding vulnerabilities is easy. Fixing them? That''s where the real work begins. Enter agentic remediation—the next evolution of AI in software development. Join us for a fun talk where we''ll unpack everything you need to know about remediating with agents, including a demo of the Snyk Remediation Agent as a real-world example.

The Verification Layer for the Dark Factory: How Coding Agents Earn Trust

Agentic development pipelines can plan, generate, test, and open pull requests faster than human teams can inspect every line. In this session, we''ll break down a practical verification layer for agentic development: codebase context before execution, independent code review, and inspectable evidence at the pull-request boundary.', ARRAY['https://aiweek.boston/schedule/ai-native-dev-boston-inside-the-dark-factory']::text[], now()),
  ('film-philosophy-what-if-ai-won@aiweek.boston', 'Film & Philosophy: What If AI Won?', 'https://aiweek.boston/schedule/film-philosophy-what-if-ai-won', 'https://luma.com/nthwqu6m', TRUE, '2026-09-17T18:30:00-04:00'::timestamptz, '2026-09-17T20:30:00-04:00'::timestamptz, 'Democracy Brewing', '35 Temple Pl, Boston, MA 02111', 'Boston', 'Meetup', 'Recess Revival', '[]'::jsonb, 'Film & Philosophy: What If AI Won?', 'When convenience blends with dependency, what if AI didn’t defeat humanity—what if we simply handed it the keys?

Join us during Boston AI Week for Film & Philosophy: What If AI Won?—an interactive social experience exploring AI, human agency, business, ethics, and governance through film-inspired questions.

This isn’t a lecture, panel, or traditional networking event.

You’ll join rotating pods of people for guided conversations designed to help you skip the small talk and get into the questions that actually matter:

- When does convenience become dependence?

- What decisions should humans never outsource?

- If irresponsible AI gives a company an advantage, who chooses to slow down?

- When AI causes harm, who should be accountable?

No AI expertise required! Come as a founder, builder, consultant, creative, policymaker, student, skeptic, enthusiast—or simply someone curious about where all of this is going.

What to expect:

- Short film-inspired discussion prompts

- Facilitated conversations in small, rotating groups

- A mix of personal, business, and societal questions

- Time to order food and drinks from Democracy Brewing at our event''s private bar

- Optional social time after the guided experience

Coming alone? Most people will—and your first group will be waiting for you. You won’t have to work the room, introduce yourself to everyone, or figure out where to sit!

Doors open: 6:00 PM

Guided experience: 6:30–8:45 PM

Stay and socialize: Until 9:30 PM

Please arrive by 6:20 PM so we can place everyone into their first conversation pod.

Food and drinks are available for purchase directly from Democracy Brewing.

For guests 21+. Space is limited to keep the conversations intimate.

Film & Philosophy is an independent Recess Revival experience and is not affiliated with Disney or Marvel.', ARRAY['https://aiweek.boston/schedule/film-philosophy-what-if-ai-won']::text[], now()),
  ('ai-powered-go-to-market-engine-2026@aiweek.boston', 'Building the AI-Powered Go-To-Market Engine', 'https://aiweek.boston/schedule/ai-powered-go-to-market-engine-2026', 'https://luma.com/mass-cp7l', TRUE, '2026-09-18T08:30:00-04:00'::timestamptz, '2026-09-18T11:30:00-04:00'::timestamptz, '99 High Street', '99 High St, Boston, MA 02110', 'Boston', 'Panel', 'Mass Technology Leadership Council (MassTLC)', '[{"name":"Mike Grandinetti","bio":"Executive Fellow at Harvard Business School."},{"name":"Jennifer Griffin Smith","bio":"Chief Marketing Officer at Acquia."},{"name":"Bill Bentley","bio":"Chief Revenue Officer at Emminence Gray."},{"name":"Peter Atanasoff","bio":"Managing Director & VP at Scratch Marketing."},{"name":"David Chang","bio":"Co-Founder of Via AI."}]'::jsonb, 'Building the AI-Powered Go-To-Market Engine', 'As AI advances and buyer behavior evolves, the traditional go-to-market model is being replaced by connected revenue engines that span the entire customer lifecycle, from pipeline generation to expansion and retention.

Top-performing marketing and revenue teams are moving beyond manual workflows and using AI to turn pipeline generation into a system, not a grind. The focus is shifting from isolated campaigns and departmental handoffs to integrated motions that connect marketing, sales, customer success, and operations around shared growth outcomes.

MassTLC convenes leaders to explore how organizations are rethinking pipeline generation, customer engagement, and revenue growth. You will see practical AI-powered workflows, learn how modern teams are aligning the revenue engine, and leave with frameworks you can apply immediately.

Topics:

• How AI is transforming pipeline generation into a scalable, repeatable growth system

• The evolution from marketing-led demand generation to revenue engine orchestration

• How changing buyer behavior is reshaping customer engagement and conversion

• Practical AI workflows that improve productivity, targeting, and pipeline performance

• The skills, operating models, and leadership strategies required for the next generation of growth', ARRAY['https://aiweek.boston/schedule/ai-powered-go-to-market-engine-2026']::text[], now()),
  ('tech-exit-playbook-liquidity-events-2026@aiweek.boston', 'The Tech Exit Playbook: Navigating Liquidity Events in Tech', 'https://aiweek.boston/schedule/tech-exit-playbook-liquidity-events-2026', 'https://luma.com/867255g9', TRUE, '2026-09-22T08:15:00-04:00'::timestamptz, '2026-09-22T13:30:00-04:00'::timestamptz, 'Foley Hoag LLP', '155 Seaport Blvd, Boston, MA 02210', 'Boston', 'Conference', 'Mass Technology Leadership Council (MassTLC)', '[{"name":"Chris Andrews","bio":"Managing Director at PSG."},{"name":"Amanda Hall","bio":"General Counsel at DoiT."},{"name":"Diane Basile","bio":"Chief Financial Officer at Salary.com."},{"name":"Mary Henry","bio":"Chief Executive Officer at Fairwinds Ops."},{"name":"Chris Sands","bio":"Chief Financial Officer at InvoiceCloud."},{"name":"Matt Vittiglio","bio":"Associate General Counsel at Rocket Software."},{"name":"Levina Wong","bio":"General Counsel at Nexthink."},{"name":"Stacie Arrestad","bio":"Partner and Co-Chair of the Capital Markets Practice at Foley Hoag."},{"name":"Corey Brown","bio":"Partner and Co-Chair of the M&A Practice Group at Foley Hoag."},{"name":"Hank Galligan","bio":"National Tech Industry Group Leader at BDO USA."},{"name":"Rich Egan","bio":"Transaction Advisory Services Director at BDO."},{"name":"Holly Richardson","bio":"Core Tax Principal at BDO USA."},{"name":"Matt Lacy","bio":"Managing Director, Investment Banking at Wells Fargo."},{"name":"Danielle Lussier","bio":"Executive Director, Technology Banking at Wells Fargo."},{"name":"Vasilis Varsakopoulos","bio":"Private Capital Advisory at Wells Fargo."}]'::jsonb, 'The Tech Exit Playbook: Navigating Liquidity Events in Tech', 'Navigating a liquidity event in the technology sector requires disciplined preparation, strategic insight, and experienced guidance. As buyers grow more sophisticated and diligence requirements intensify, technology executives must be transaction-ready across financial, legal, operational, and strategic dimensions to achieve optimal outcomes. This executive-focused program brings together CFOs, General Counsels, investment bankers, private equity investors, and advisors to share practical perspectives on preparing for and executing a successful transaction.

Through panels, presentations, and fireside chats, the program covers the full lifecycle of a liquidity event — from early readiness and financial preparedness to legal considerations, deal positioning, value maximization, and post-close value creation. Attendees will gain actionable insights into what buyers and sponsors look for in today''s market, how to prepare management teams for diligence and negotiations, and how to position their companies for a successful transaction and future growth.

Ticketing: free for MTLC members; $100 for future members. All registrations require approval. Refunds are available up to 7 days before the event, less the 3.2% payment platform fee.', ARRAY['https://aiweek.boston/schedule/tech-exit-playbook-liquidity-events-2026']::text[], now()),
  ('the-cost-of-intelligence-a-breakfast-briefing-on-ai-spend@aiweek.boston', 'The Cost of Intelligence: A Breakfast Briefing on AI Spend', 'https://aiweek.boston/schedule/the-cost-of-intelligence-a-breakfast-briefing-on-ai-spend', 'https://luma.com/0l18a79t', TRUE, '2026-09-22T09:00:00-04:00'::timestamptz, '2026-09-22T11:00:00-04:00'::timestamptz, 'Microsoft New England Research and Development Center', '1 Memorial Drive Cambridge, MA 02142', 'Cambridge', 'Talk', 'Bay State IT', '[]'::jsonb, 'The Cost of Intelligence: A Breakfast Briefing on AI Spend', 'A Breakfast Briefing on the Cost of AI

Most AI cost problems look like this: The API bill blows through the monthly budget in the first week. Your Claude or ChatGPT plan hits its usage cap by Wednesday. A task that ran fine last month now takes three tries and twice the tokens. But spending more isn''t the only fix.

Join Bay State IT for coffee, bagels, and an informative talk on the real economics of AI. We will walk through the cost-of-intelligence benchmarks that now exist, compare the major models on what they deliver per dollar, and show why more context is not always better, why a large model with medium reasoning often beats a small model at maximum reasoning, and where ultra-cheap models can fit into your workflow. You will leave with practical ways to get more out of the plan you already have.

This talk is for anyone who pays for AI. That includes companies with enterprise Claude or ChatGPT seats or API usage to manage, but it also includes anyone on a standard plan who keeps running into the usage cap. The same habits decide how far your budget goes, either way.

Agenda:

9:00 AM: Check-in, breakfast, and networking

9:30 AM: Presentation: The Cost of Intelligence

10:15 AM: Q&A

10:30 AM: Open networking and coffee

Space is limited!', ARRAY['https://aiweek.boston/schedule/the-cost-of-intelligence-a-breakfast-briefing-on-ai-spend']::text[], now()),
  ('ai-assistant-training@aiweek.boston', 'AI Assistant Training', 'https://aiweek.boston/schedule/ai-assistant-training', 'https://www.kendallai.org/ai-assistant-webinar/', TRUE, '2026-09-22T11:00:00-04:00'::timestamptz, '2026-09-22T13:00:00-04:00'::timestamptz, NULL, NULL, 'Virtual', 'Workshop', 'The Kendall Project', '[{"name":"Kevin Gulley","bio":"Co-Founder and Managing Partner of The Kendall Project; a technology entrepreneur and product development leader who has spent his career building and scaling software companies across data, AI, fintech, digital media, and gaming."},{"name":"Brendan McSheffrey","bio":"Managing Partner of The Kendall Project and a serial entrepreneur with decades of experience bringing emerging technologies to market across SaaS, healthcare, defense, financial services, IoT, and privacy technologies."}]'::jsonb, 'AI Assistant Training', 'Build an AI Assistant Made for Your Organization

Generic AI can answer questions, but it doesn''t know your organization''s language, goals, processes, or rules. That''s why so many AI assistants produce inconsistent or generic responses.

In this free, live workshop, you''ll learn how to build an enterprise AI assistant that understands your business context and delivers more accurate, reliable results. We''ll walk through the complete process, from defining objectives and trusted knowledge sources to writing effective instructions and assembling a working assistant.

You''ll learn:

• What makes an enterprise AI assistant different from a general chatbot

• Why context, knowledge, and clear instructions matter

• How Retrieval Augmented Generation (RAG) improves accuracy

• The Kendall Activation Prompt framework for creating consistent AI assistants

• How to organize and manage knowledge so your assistant stays accurate over time

This is a hands-on session, not a lecture. You''ll build your own AI assistant during the workshop using your organization''s language, objectives, and business context.

Whether you''re just getting started with AI assistants or looking to improve one you''ve already built, you''ll leave with a practical framework and a working assistant you can continue using and refining after the session.

Tuesday, September 22, 2026

11:00 AM to 1:00 PM Eastern

Live virtual workshop', ARRAY['https://aiweek.boston/schedule/ai-assistant-training']::text[], now()),
  ('stop-running-pilots-start-running-ai-and-unlocking-value@aiweek.boston', 'Stop Running Pilots. Start Running AI and Unlocking Value.', 'https://aiweek.boston/schedule/stop-running-pilots-start-running-ai-and-unlocking-value', 'https://ai.launchconsulting.com/ai-ebc-microsoft-burlington-ma', TRUE, '2026-09-22T12:01:00-04:00'::timestamptz, '2026-09-22T17:00:00-04:00'::timestamptz, 'Microsoft New England', '1 Memorial Drive Cambridge, MA 02142', 'Cambridge', 'Panel', 'Launch Consulting', '[{"name":"Nicholas Polachek","bio":null},{"name":"Jess Lampe","bio":null},{"name":"Evan Wray","bio":null}]'::jsonb, 'Stop Running Pilots. Start Running AI and Unlocking Value.', 'Inside the Session

Preliminary Agenda

12:00 PM – 1:00 PM | Networking Lunch

Executive lunch and peer networking with Microsoft & Launch leaders.

1:00 PM – 2:50 PM | Breakout Sessions

Choose from a number of insightful breakout sessions below

3:00 PM – 3:30 PM | Executive Discussion & Closing Remarks

Interactive discussion with peers on AI priorities, challenges, and opportunities, followed by closing insights and next steps.

3:30 PM – 5:00 PM | Happy Hour

Cocktails and continued networking with Microsoft and Launch leaders to close out the day.

Breakout sessions: Business Case for the CFO

AI Governance Without Gridlock

Azure Foundry: From Pilot to Production

Microsoft Fabric: The Data Foundation for AI

AI SDLC: From Idea to Enterprise Impact

*sessions are subject to change

What You''ll Walk Away With

A complimentary follow-up workshop, on us!

Clarity on where AI is actually delivering ROI

A practical path to move from pilot to production

Perspective from peers facing the same challenges

A clear framework to prioritize the right AI investments

Insight into the gaps holding your organization back

Concrete next steps you can take immediately', ARRAY['https://aiweek.boston/schedule/stop-running-pilots-start-running-ai-and-unlocking-value']::text[], now()),
  ('subconscious-launch-night-the-easy-button-for-open-models@aiweek.boston', 'Subconscious Launch Night: The Easy Button for Open Models', 'https://aiweek.boston/schedule/subconscious-launch-night-the-easy-button-for-open-models', 'https://luma.com/u0415mk2', TRUE, '2026-09-22T17:00:00-04:00'::timestamptz, '2026-09-22T20:00:00-04:00'::timestamptz, 'Downtown Boston', NULL, 'Boston', 'Panel', 'Subconscious', '[{"name":"Jack O''Brien","bio":"Co-Founder & CEO of Subconscious."},{"name":"Andrew Lau","bio":"Co-Founder & CEO of Jellyfish."},{"name":"Hongyin Luo","bio":"Co-Founder & CTO of Subconscious."}]'::jsonb, 'Subconscious Launch Night: The Easy Button for Open Models', 'Open models are now great at coding. Open models hosted on Subconscious infrastructure get a stepwise improvement in speed, accuracy, and efficiency. Come see for yourself and get started!

After working exclusively with large enterprises to optimize their GPU clusters, we wanted to find a way for our technology to benefit more developers. Come join the Subconscious team as we celebrate the launch of our new inference API. Now, engineers sign up and get started in just a few minutes.

Expect to connect with other great leaders and engineers in the Boston area, see new benchmarks and demos from the Subconscious team, and celebrate the Mass AI Coalition.

Schedule: 5-5:30: Welcome food and drinks

5:30-6: Chat with Jellyfish CEO Andrew Lau and Subconscious CEO Jack O''Brien on using Open Models to code.

6-6:45: Subconscious keynote and demos from Jack O''Brien (CEO) and Hongyin Luo (CTO)

6:45-8: Celebrate!

We designed our inference system for coding agents and agentic products, so they excel at tasks that use more than 200k tokens. Compared to other inference runtimes (vLLM, SGLang) or managed inference services (Together AI, Fireworks), Subconscious:

Consumes 80% fewer tokens thanks to context compression.

Generates tokens 3.5x faster deep down reasoning traces.

Improves reasoning accuracy by up to 10% on complex tasks.

Can run for 5m+ tokens without an explicit compaction step.

Seem too good to be true? The way we serve agents today is wildly inefficient. Come see for yourself!

Thanks To Synergy for providing the space!', ARRAY['https://aiweek.boston/schedule/subconscious-launch-night-the-easy-button-for-open-models']::text[], now()),
  ('from-idea-to-working-software-vibe-code-like-a-product-manager@aiweek.boston', 'From Idea to Working Software: Vibe Code Like a Product Manager', 'https://aiweek.boston/schedule/from-idea-to-working-software-vibe-code-like-a-product-manager', 'https://massaicoalition.com/retrain/register?session=c8ec1ee0-91b5-429b-b930-0945448c3170', TRUE, '2026-09-22T17:00:00-04:00'::timestamptz, '2026-09-22T18:00:00-04:00'::timestamptz, 'Workbar Back Bay', '399 Boylston St 6th Floor, Boston, MA 02116', 'Boston', 'Workshop', 'Hiype.io', '[{"name":"Alexandra Edelstein","bio":null}]'::jsonb, 'From Idea to Working Software: Vibe Code Like a Product Manager', 'A hands-on workshop where participants bring a real idea and learn how to turn it into working software. Designed for professionals, operators, and aspiring builders across industries, this course focuses on the product thinking skills that make AI-assisted software development successful.

Participants will learn how to identify a high-value problem to solve, scope an achievable first product, and break large ideas into iterative development milestones. The course emphasizes defining clear requirements, prioritizing validated features, and building incrementally.

Through guided exercises and live build sessions, participants will create a working prototype tied to a real business or operational need along with a clear product roadmap. By the end of the workshop, participants will be able to approach software ideas more strategically, better translate business problems into actionable product plans, and collaborate more effectively with AI coding tools to turn concepts into practical applications.', ARRAY['https://aiweek.boston/schedule/from-idea-to-working-software-vibe-code-like-a-product-manager']::text[], now()),
  ('building-ai-that-scales-avoiding-the-multicloud-trap-red-sox-game@aiweek.boston', 'Building AI that Scales: Avoiding the Multicloud Trap & Red Sox Game', 'https://aiweek.boston/schedule/building-ai-that-scales-avoiding-the-multicloud-trap-red-sox-game', 'https://info.wasabi.com/boston-ai-week-fenway', TRUE, '2026-09-22T17:00:00-04:00'::timestamptz, '2026-09-22T21:30:00-04:00'::timestamptz, 'Fenway Park', '4 Jersey St, Boston, MA', 'Boston', 'Meetup', 'Wasabi Technologies', '[]'::jsonb, 'Building AI that Scales: Avoiding the Multicloud Trap & Red Sox Game', 'As AI budgets explode, so do infrastructure costs. Organizations are already exceeding cloud storage budgets by nearly 50 percent, and vendor lock-in is eating into ROI faster than expected.

Join us for a night at Fenway Park from a private suite, with food and drinks included, as we bring together AI and IT leaders for an honest conversation about how the smartest teams are structuring their storage strategy to stay flexible, control costs, and hit their ROI targets. We''ll break down the real cost of being locked into a single vendor and show you why open multicloud isn''t a nice-to-have, it''s a financial imperative.

Then, sit back and enjoy the Red Sox vs. Guardians, great food and drinks, and the chance to connect with your peers.

Seats are limited, so we hope you''ll join us for what promises to be a memorable night at the ballpark!', ARRAY['https://aiweek.boston/schedule/building-ai-that-scales-avoiding-the-multicloud-trap-red-sox-game']::text[], now()),
  ('ai-in-ma-and-financing-workbar-needham-2026@aiweek.boston', 'AI and the Changing World of M&A', 'https://aiweek.boston/schedule/ai-in-ma-and-financing-workbar-needham-2026', 'https://bit.ly/4yk2ugq', TRUE, '2026-09-22T17:15:00-04:00'::timestamptz, '2026-09-22T18:00:00-04:00'::timestamptz, 'Workbar Needham', '117 Kendrick Street, Suite 300, Needham, MA 02494', 'Needham', 'Panel', 'Gennari Aronson, LLP, Charles River Chamber of Commerce & Workbar Needham', '[{"name":"Mike Grandinetti","bio":"Executive Fellow at Harvard Business School."},{"name":"Kara Peterson","bio":"Co-Founder & CEO of Descrybe; Co-Host of the Building AI Boston podcast."},{"name":"Bobby Steinkrauss","bio":"Managing Director at Needham & Company."},{"name":"Patti Fletcher","bio":"AI Strategist & author."}]'::jsonb, 'AI and the Changing World of M&A', 'Artificial intelligence is already reshaping the M&A world. Buyers are using new tools to source deals, determine valuation, conduct due diligence, assess projections, and draft transaction documents. Sellers are using AI to compare letters of intent, populate data rooms, and track post-closing transition arrangements and post-merger integration. Recent reports estimate that almost half of all dealmakers now are using AI tools daily to enhance decision-making speed and accuracy across the entire deal process. Join us as we talk about the AI tools, trends, and terms that are transforming the M&A process.

Hosted by Gennari Aronson, LLP, Charles River Chamber of Commerce & Workbar Needham.

Getting there: Free on-site parking. Directly off Route 128 / I-95.', ARRAY['https://aiweek.boston/schedule/ai-in-ma-and-financing-workbar-needham-2026']::text[], now()),
  ('ai-entrepreneurial-finance-workbar-needham-2026@aiweek.boston', 'AI: Trends and Developments in Entrepreneurial Finance', 'https://aiweek.boston/schedule/ai-entrepreneurial-finance-workbar-needham-2026', 'https://bit.ly/46drLg3', TRUE, '2026-09-22T18:15:00-04:00'::timestamptz, '2026-09-22T19:00:00-04:00'::timestamptz, 'Workbar Needham', '117 Kendrick Street, Suite 300, Needham, MA 02494', 'Needham', 'Panel', 'Gennari Aronson, LLP, Charles River Chamber of Commerce & Workbar Needham', '[{"name":"Daniel Acheampong","bio":null},{"name":"Brendan McSheffrey","bio":null},{"name":"Allison Byers","bio":"CEO of Scroobious; author of Fundraising for the Rest of Us."}]'::jsonb, 'AI: Trends and Developments in Entrepreneurial Finance', 'In these volatile times, many entrepreneurs are struggling to raise money from friends & neighbors, angel groups, VCs, and traditional early-stage investors. Innovative companies are trying to grab the attention of investors and influencers. Mission and impact focused entrepreneurs trying to balance profit with social or environmental goals are having an even harder time. Do all business plans have to include the words "artificial intelligence" to attract attention, advisors, and funding? Yes and No! Join us for a discussion of how financing strategies for growth companies are being shaped and transformed by innovation and AI.

Hosted by Gennari Aronson, LLP, Charles River Chamber of Commerce & Workbar Needham.

Getting there: Free on-site parking. Directly off Route 128 / I-95.', ARRAY['https://aiweek.boston/schedule/ai-entrepreneurial-finance-workbar-needham-2026']::text[], now()),
  ('networking-connection-workbar-needham-2026@aiweek.boston', 'Networking & Connection at Workbar Needham', 'https://aiweek.boston/schedule/networking-connection-workbar-needham-2026', 'https://aiweek.boston/schedule/networking-connection-workbar-needham-2026', FALSE, '2026-09-22T19:00:00-04:00'::timestamptz, '2026-09-22T19:30:00-04:00'::timestamptz, 'Workbar Needham', '117 Kendrick Street, Suite 300, Needham, MA 02494', 'Needham', 'Community', 'Gennari Aronson, LLP, Charles River Chamber of Commerce & Workbar Needham', '[]'::jsonb, 'Networking & Connection at Workbar Needham', 'Stay after the evening''s two panels for open networking and connection. Meet the panelists, dealmakers, founders, investors, and advisors from the 128 corridor over refreshments.

Hosted by Gennari Aronson, LLP, Charles River Chamber of Commerce & Workbar Needham.

Getting there: Free on-site parking. Directly off Route 128 / I-95.', ARRAY['https://aiweek.boston/schedule/networking-connection-workbar-needham-2026']::text[], now()),
  ('ai-week-keynote-how-ai-startups-will-reshape-bostons-future@aiweek.boston', 'AI Week Keynote: How AI Startups Will Reshape Boston''s Future', 'https://aiweek.boston/schedule/ai-week-keynote-how-ai-startups-will-reshape-bostons-future', 'https://aiweek.boston/schedule/ai-week-keynote-how-ai-startups-will-reshape-bostons-future', FALSE, '2026-09-23T11:00:00-04:00'::timestamptz, '2026-09-23T12:00:00-04:00'::timestamptz, '10 Post Office Square', '10 Post Office Square, Boston, MA 02109', 'Boston', 'Keynote', 'Boston AI Week', '[{"name":"Douglas (Doug) Levin","bio":"Founder and CEO of Black Duck Software; Executive Fellow at Harvard Business School and Stanford Law School Directors'' College."}]'::jsonb, 'AI Week Keynote: How AI Startups Will Reshape Boston''s Future', 'What will enable Boston to stay competitive as an AI startup hub? What defines success for AI founders and startups today? What forces could reignite Boston''s position as a leading center for AI innovation?

Together, we will explore these strategic, cultural, and economic factors shaping Boston''s position in the evolving landscape of AI entrepreneurship.

Join Doug Levin, founder and CEO of Black Duck Software, as he explores what makes AI-native startups distinct, how founders should approach building today, and the biggest opportunities ahead for Boston''s tech ecosystem.

The session will also include a live demonstration of a compelling AI agent designed to help build your startup, from shaping the initial concept and business model to accelerating execution.

Speaker: Douglas Levin — Executive Fellow, Harvard Business School and Stanford Law School Directors'' College', ARRAY['https://aiweek.boston/schedule/ai-week-keynote-how-ai-startups-will-reshape-bostons-future']::text[], now()),
  ('the-ai-defense-stack-showcase-day@aiweek.boston', 'The AI Defense Stack Showcase Day', 'https://aiweek.boston/schedule/the-ai-defense-stack-showcase-day', 'https://www.linkedin.com/events/7492177734136262656/', TRUE, '2026-09-23T12:00:00-04:00'::timestamptz, '2026-09-23T14:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Demo Night', 'Risk Takers', '[{"name":"Eva Benn","bio":null},{"name":"Phillip Miller","bio":null},{"name":"Merlin Namuth","bio":null},{"name":"Benjamin Corll","bio":null},{"name":"Priya Mouli","bio":null}]'::jsonb, 'The AI Defense Stack Showcase Day', 'A free live online showcase for CISOs and experienced cybersecurity practitioners. Five cybersecurity companies will each present a seven-minute AI-era defense approach, followed by seven minutes of practical discussion and audience questions. The panel features Eva Benn, Phillip Miller, Merlin Namuth, Benjamin Corll, and Priya Mouli. More than 250 people have already signed up. Hosted by Risk Takers.', ARRAY['https://aiweek.boston/schedule/the-ai-defense-stack-showcase-day']::text[], now()),
  ('ai-for-all-britebound-2026@aiweek.boston', 'AI for All: AI, Human Skills, and Career Pathways', 'https://aiweek.boston/schedule/ai-for-all-britebound-2026', 'https://forms.gle/hoPKnaEY3xiGXcPL8', TRUE, '2026-09-23T15:30:00-04:00'::timestamptz, '2026-09-23T17:30:00-04:00'::timestamptz, 'Britebound', '33 Arch St., 21st Floor, Boston, MA', 'Boston', 'Panel', 'Gennari Aronson, LLP and Britebound', '[{"name":"Rob Magliaro","bio":"Senior AI Fellow at Britebound; moderator of the panel."},{"name":"Natalie Kuldell","bio":"Founder & Executive Director of BioBuilder."},{"name":"Kara Peterson","bio":"Co-Host of Building AI Boston; Co-Founder & CEO of Descrybe."}]'::jsonb, 'AI for All: AI, Human Skills, and Career Pathways', 'The panel will bring together leaders from across education, workforce development, and the nonprofit sector to explore what the rise of AI means for the next generation. How can we give more young people meaningful, hands-on opportunities to use AI? How can we help them develop the creativity, curiosity, collaboration, critical thinking, and judgment needed to use these tools thoughtfully? And how can organizations and education systems adopt AI in ways that expand opportunity and ensure it works for everyone?

Panelists:

Rob Magliaro, Senior AI Fellow, Britebound (Moderator)

Natalie Kuldell, Founder & Executive Director, BioBuilder

Kara Peterson, Co-Host, Building AI Boston; Co-Founder & CEO, Descrybe

We hope you can join us for all or part of the afternoon!', ARRAY['https://aiweek.boston/schedule/ai-for-all-britebound-2026']::text[], now()),
  ('boston-ai-executive-exchange-executive-dinner-and-roundtable@aiweek.boston', 'Boston AI Executive Exchange - Executive Dinner and Roundtable', 'https://aiweek.boston/schedule/boston-ai-executive-exchange-executive-dinner-and-roundtable', 'https://www.legacyclub.boston/event-details/boston-ai-executive-exchange-executive-dinner-and-roundtable', TRUE, '2026-09-23T17:30:00-04:00'::timestamptz, '2026-09-23T20:00:00-04:00'::timestamptz, 'The Legacy Club', '180 Canal St, 5th floor, Boston, MA 02114', 'Boston', 'Panel', 'The TeamShield Group', '[{"name":"John Holmes","bio":"Managing Director at Accenture."},{"name":"Warren Bamford","bio":"Advisor at Ed Davis Company (FBI + Ed Davis Company)."},{"name":"Devesh Srivastava","bio":"Ph.D., Global Leader in AI at Cisco."}]'::jsonb, 'Boston AI Executive Exchange - Executive Dinner and Roundtable', 'Hosted by The TeamShield Group in partnership with the Legacy Club of Boston, and proudly sponsored at the Platinum level by Cisco, this private, invite-only gathering brings together senior public sector and education leaders for thoughtful discussions on the future of artificial intelligence. The conversation will focus on practical implementation, secure infrastructure, governance, and the opportunities and challenges AI presents across government and education.

Due to the nature of the event and the venue, attendance is limited.

Format: Private executive roundtable under the Chatham House Rule

Attendees: State and Municipal CIOs, Higher Education Technology Leaders, K–12 CTOs, and invited public sector executives', ARRAY['https://aiweek.boston/schedule/boston-ai-executive-exchange-executive-dinner-and-roundtable']::text[], now()),
  ('healthcare-ai-activationTM-from-problem-to-partner-startup-showcase-matching-ses@aiweek.boston', 'Healthcare AI Activation™ From Problem to Partner: Startup Showcase + Matching Sessions', 'https://aiweek.boston/schedule/healthcare-ai-activationTM-from-problem-to-partner-startup-showcase-matching-ses', 'https://luma.com/htfiz6vs', TRUE, '2026-09-24T08:30:00-04:00'::timestamptz, '2026-09-24T11:00:00-04:00'::timestamptz, 'Microsoft New England Research and Development Center (NERD) building', '1 Memorial DrCambridge, MA 02142', 'Cambridge', 'Workshop', 'NuVert', '[]'::jsonb, 'Healthcare AI Activation™ From Problem to Partner: Startup Showcase + Matching Sessions', 'Pre-Event Special Feature: From Problem to Partner

Before the formal Day 1 program begins, NuVert will host a curated Startup Showcase + Matching Session designed to connect healthcare leaders with emerging solutions, founders, and ideas from both the Boston innovation ecosystem and the global AI community.

Rather than a traditional expo, the morning is built around short, curiosity-driven startup spotlights, organic networking, and direct conversations that help participants move quickly from “What problem are you solving?” to “Is there a reason we should work together?”

The experience will feature local startups including Train4AI, Scriptify, Kidney Connective, a Flare portfolio company, and additional selected innovators, alongside global perspectives from leaders such as Mark Turrell and the Harvard Health Systems Innovation Lab.

Healthcare founders will also have the opportunity to learn from more established entrepreneurs and ecosystem leaders. An outside sponsor table will feature Dr. Nasim Afsar’s Intelligent Health book purchase and signing.

The guiding principle for the morning is simple: Relationships first. Solutions second.', ARRAY['https://aiweek.boston/schedule/healthcare-ai-activationTM-from-problem-to-partner-startup-showcase-matching-ses']::text[], now()),
  ('christensen-institute-innovation-summit-2026@aiweek.boston', 'Christensen Institute Innovation Summit — From Insight to Foresight: Designing What Comes Next', 'https://aiweek.boston/schedule/christensen-institute-innovation-summit-2026', 'https://www.christenseninstitute.org/programs/summit/', TRUE, '2026-09-24T09:00:00-04:00'::timestamptz, '2026-09-24T17:00:00-04:00'::timestamptz, 'David Rubenstein Treehouse, Harvard University', '135 Western Ave, Allston, MA 02134', 'Boston', 'Conference', 'Clayton Christensen Institute', '[]'::jsonb, 'Christensen Institute Innovation Summit — From Insight to Foresight: Designing What Comes Next', 'Join the inaugural Christensen Institute Innovation Summit: a closed-door, curated assembly designed to use Clayton Christensen''s evolving frameworks not just to understand disruption, but to anticipate it.

On September 24, 2026, the Institute will convene 150–200 cross-sector leaders for a one-day assembly that moves from applying rigorous innovation theory to something harder and rarer: using it to see what''s coming before it''s obvious. The day is structured in three stages — Insight, System, Foresight — each building toward a sharper answer to the question every serious leader is quietly asking: where does my industry break next, and am I positioned ahead of it?

What to expect:

- Practical tools drawn from Disruptive Innovation Theory, Jobs to Be Done, and value network analysis, applied to strategic decisions.

- Structured cross-sector conversations with leaders navigating the same forces from different vantage points.

- A forward-looking plenary that uses theory (not trend-watching) to forecast where markets and systems are about to shift.

- A tangible summit artifact: a framework and signal test attendees keep and use long after the day ends.

- An evening to start: a pre-event VIP dinner bringing together a select group of attendees the night before.

Who attends: innovation strategists and transformation executives; founders building at the edge of established markets; system shapers in education, healthcare, and global prosperity; long-horizon investors and capital allocators; and the next generation of leaders shaping what disruption looks like.

Seating is deliberately capped. This is a curated room, assembled for depth over scale. Times listed are approximate pending the host''s published agenda.', ARRAY['https://aiweek.boston/schedule/christensen-institute-innovation-summit-2026']::text[], now()),
  ('devconf-us-2026@aiweek.boston', 'DevConf US 2026', 'https://aiweek.boston/schedule/devconf-us-2026', 'https://www.devconf.info/us/', TRUE, '2026-09-24T09:00:00-04:00'::timestamptz, '2026-09-25T17:00:00-04:00'::timestamptz, 'Boston University Wheelock College of Education & Human Development – Brookline Campus', '43 Hawes Street, Brookline, MA 02446', 'Boston', 'Conference', 'Red Hat', '[]'::jsonb, 'DevConf US 2026', 'DevConf.US is a free, Red Hat–sponsored community conference for contributors to free and open source technologies, returning to Boston University for 2026. Two days of talks, lightning talks, and workshops spanning AI and machine learning, cloud infrastructure, application development, DevOps, security, and user experience. Open to everyone — students, new graduates, and professionals — with attendee coaching available for first-time conference attendees. Admission is free, but registration is required. Venue: 43 Hawes Street, the BU Wheelock College of Education & Human Development building on the Brookline campus, steps from the Green Line (Hawes Street on the C branch or Longwood on the D branch).', ARRAY['https://aiweek.boston/schedule/devconf-us-2026']::text[], now()),
  ('how-our-ai-navigator-has-supported-success-in-developing-healthier-happier-peopl@aiweek.boston', 'AI-Enhanced Engagement Improves Organizational Outcomes', 'https://aiweek.boston/schedule/how-our-ai-navigator-has-supported-success-in-developing-healthier-happier-peopl', 'https://www.eventbrite.com/e/boston-ai-week-ai-enhanced-engagement-improves-organizational-outcomes-tickets-1999785850311?aff=oddtdtcreator', TRUE, '2026-09-24T10:30:00-04:00'::timestamptz, '2026-09-24T11:30:00-04:00'::timestamptz, 'Hogsmeade Room, CIC Cambridge', '245 Main Street, Cambridge', 'Virtual', 'Demo Night', 'Core Coaching & Consulting, LLC.', '[{"name":"Howard E. Goode","bio":"Co-inventor of the Six Powers Compass Navigator (NAV) and the Organizational Health Profile (OHP)."},{"name":"Alfonso Torrijos","bio":"Co-inventor of the Six Powers Compass Navigator (NAV) and the Organizational Health Profile (OHP)."},{"name":"Sharon Seivert","bio":"Co-inventor of the Six Powers Compass Navigator (NAV) and the Organizational Health Profile (OHP)."}]'::jsonb, 'AI-Enhanced Engagement Improves Organizational Outcomes', 'We will demonstrate our Six Powers Compass Navigator (the NAV) and the Organizational Health Profile (OHP), and share case study data that shows how we create healthier organizations where leaders and workers thrive.

To attend the event in person, you must register on Eventbrite. To attend the event online via Zoom, you must register on Zoom.

Space is limited. Both in-person attendees and Remote attendees must register in advance.', ARRAY['https://aiweek.boston/schedule/how-our-ai-navigator-has-supported-success-in-developing-healthier-happier-peopl']::text[], now()),
  ('boat-rides-boston-harbor-captain-chris-2026-09-24@aiweek.boston', 'Boat Rides of Boston Harbor with Captain Chris', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-24', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-24', FALSE, '2026-09-24T12:00:00-04:00'::timestamptz, '2026-09-24T13:00:00-04:00'::timestamptz, 'Fan Pier', 'Fan Pier, Boston, MA', 'Boston', 'Meetup', 'Boston AI Week', '[]'::jsonb, 'Boat Rides of Boston Harbor with Captain Chris', 'Join Captain Chris for a boat ride on Boston Harbor, offered every day of Boston AI Week''s core week (September 24 – October 2). Very limited availability. RSVP to be considered, we''ll work with Captain Chris on approvals. Due to expected demand, not all RSVPs will be honored, but we''ll do our best.

Time: TBA. This is a request, not a confirmed spot — organizers will follow up if your RSVP is approved.', ARRAY['https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-24']::text[], now()),
  ('healthcare-ai-activationTM@aiweek.boston', 'Healthcare AI Activation™', 'https://aiweek.boston/schedule/healthcare-ai-activationTM', 'https://luma.com/vgjah76g', TRUE, '2026-09-24T13:00:00-04:00'::timestamptz, '2026-09-24T17:00:00-04:00'::timestamptz, 'Microsoft New England Research and Development Center (NERD) building', '1 Memorial DrCambridge, MA 02142', 'Cambridge', 'Workshop', 'NuVert', '[{"name":"Dr. Ami Bhatt","bio":"Chief Medical Officer of WHOOP."},{"name":"Ambassador Prof. Muhammadou Kah","bio":"Vice President of the UN Human Rights Council and Co-Chair of the UN Commission on Science, Technology and Development."},{"name":"Bethany Hall-Long","bio":"75th Governor of Delaware."}]'::jsonb, 'Healthcare AI Activation™', 'NuVert’s Healthcare AI Activation™ is a one-day executive gathering—and Day 1 of a two-day event—for healthcare leaders navigating the shift from AI interest to responsible adoption, implementation, and scale. Hosted at the Microsoft New England Research and Development Center, the program brings together healthcare executives, clinical leaders, researchers, innovators, startups, and responsible AI practitioners to examine where healthcare AI stands today, what is preventing organizations from moving from pilot to impact, and what leaders need to do next.

The day moves through Intelligence → Expert Perspective → Interactive Labs → Relationship-Building, combining a curated startup showcase, NuVert Executive Intelligence, conversations on clinical AI and innovation inside healthcare systems, and hands-on labs focused on governance, organizational change, and human flourishing. Participants will leave with practical insights, stronger cross-sector relationships, and a clearer understanding of how to connect AI innovation with governance, people, trust, and execution.', ARRAY['https://aiweek.boston/schedule/healthcare-ai-activationTM']::text[], now()),
  ('boston-cloud-connect-summit@aiweek.boston', 'Boston Cloud Connect Summit', 'https://aiweek.boston/schedule/boston-cloud-connect-summit', 'https://www.eventbrite.com/e/boston-cloud-connect-summit-tickets-1995143902119?aff=oddtdtcreator', TRUE, '2026-09-24T13:30:00-04:00'::timestamptz, '2026-09-24T18:30:00-04:00'::timestamptz, 'WGBH Studio''s Yawkey Theater', '1 Guest Street, Boston, MA', 'Boston', 'Conference', 'Cloud Connect Summit', '[{"name":"Troy Lau","bio":"Director of Digital Technologies & Sciences Division and Head of AI at Draper Lab (NASA partner)."},{"name":"Dr. Erin Solovey","bio":"Associate Professor of Computer Science at WPI and former Harvard Radcliffe Institute Fellow; voice on AI and human interaction."},{"name":"Matt Farry","bio":"Chief Product Officer at Cyflare."},{"name":"Derek Boczenowski","bio":"Chief Compliance Architect at Compass IT Compliance."}]'::jsonb, 'Boston Cloud Connect Summit', 'Cloud Connect Summit is a half-day IT leadership event that brings together CIOs, CEOs, CFOs, CISOs, IT directors, system administrators, IT practitioners and security professionals for expert-led sessions on cybersecurity, AI, and the future of enterprise networks, followed by a networking reception with presenters.

Here''s what''s on tap:

* Hear how NASA partner Draper Lab is rolling out AI companywide from Troy Lau, Head of AI for Draper.

* Learn how cyber insurers are buckling down on approving claims, and what you need to file a successful claim. We''ve got a veteran from Compass IT Compliance to walk you through it.

* Will AI lead to “De-skilling?” Dr. Erin Solovey, WPI''s go-to voice on AI and human interaction, separates reality from noise.

* Get ahead of threats already aimed at your organization. Cyflare executive Matt Farry will walk through what''s changed in cyber protection, what hasn''t, and what to fix first.

* Free Parking right on site at the WGBH garage

* Networking cocktail reception with hot appetizers

Register at www.cloudconnectsummit.com and use code "AIweek" and we''ll waive the registration fee! Remember to click the "Apply" button in Eventbrite!', ARRAY['https://aiweek.boston/schedule/boston-cloud-connect-summit']::text[], now()),
  ('building-in-the-age-of-ai-a-founders-panel@aiweek.boston', 'Building in the Age of AI: A Founder''s Panel', 'https://aiweek.boston/schedule/building-in-the-age-of-ai-a-founders-panel', 'https://luma.com/q5hai03a', TRUE, '2026-09-24T16:00:00-04:00'::timestamptz, '2026-09-24T17:00:00-04:00'::timestamptz, 'Underscore VC Office', '125 High Street, 131 Oliver St 3rd floor, Boston, MA 02110', 'Boston', 'Panel', 'DECODE', '[{"name":"Rob Blaine","bio":"Co-Founder of TNT; has worked with hundreds of student founders at MIT and Harvard."},{"name":"Artem Lukoianov","bio":"Left research at Google DeepMind and Meta to co-found Autolab while finishing his PhD at MIT CSAIL."},{"name":"Brian Devaney","bio":"Partner at Underscore VC, backing early-stage founders bringing AI to legacy industries."}]'::jsonb, 'Building in the Age of AI: A Founder''s Panel', 'AI has made it easier than ever to build. Has it made it easier to actually found a company?

This panel brings together three people seeing that question from different sides. Rob Blaine, Co-Founder of TNT, has watched hundreds of student founders come through his community at MIT and Harvard. Artem Lukoianov left research at Google DeepMind and Meta to co-found Autolab while finishing his PhD at MIT CSAIL. Brian Devaney is a Partner at Underscore VC, where he backs early-stage founders bringing AI to legacy industries.

We''ll get into what a moat even means when everyone has the same tools, whether AI is closing or widening the gap between technical and non-technical builders, and the parts of building a company that don''t show up on LinkedIn.

Join us for a conversation on what it actually takes to build, instead of defaulting into, a company today. Hosted in partnership with Underscore VC.', ARRAY['https://aiweek.boston/schedule/building-in-the-age-of-ai-a-founders-panel']::text[], now()),
  ('under-the-hood-of-microsoft-scout-a-15-seat-working-session-on-corporate-ai-agen@aiweek.boston', 'Under the Hood of Microsoft Scout - A 15-Seat Working Session on corporate AI agents, Governance, and Agent Plugins 1.0', 'https://aiweek.boston/schedule/under-the-hood-of-microsoft-scout-a-15-seat-working-session-on-corporate-ai-agen', 'https://www.eventbrite.com/e/under-the-hood-of-microsoft-scout-tickets-1999380902100', TRUE, '2026-09-24T17:00:00-04:00'::timestamptz, '2026-09-24T18:00:00-04:00'::timestamptz, 'Wheelhouse Cowork Harborside', '33 Commercial St, Gloucester, MA 01930', 'Gloucester', 'Meetup', 'Boston Healthcare Cloud and AI Community', '[]'::jsonb, 'Under the Hood of Microsoft Scout - A 15-Seat Working Session on corporate AI agents, Governance, and Agent Plugins 1.0', 'Join the Boston Healthcare Cloud & AI Community for a special working session in Gloucester as we kick off Boston AI Week 2026.

This is intentionally different from our usual meetup format: a small group, one table, and a focused conversation around Microsoft Scout, OpenClaw, enterprise governance, and Agent Plugins 1.0.

About the Session

Microsoft Scout is Redmond''s first Autopilot agent, and the substrate underneath it is OpenClaw, the open-source runtime that went from side project to enterprise infrastructure in under a year. On September 24th, we''re pulling both apart with a small group at our Gloucester office.

This is not a webinar. Fifteen seats, one table, and a working conversation on three things: how Scout actually sits on the OpenClaw runtime, what enterprise governance looks like when every agent carries its own identity and audit trail, and where the open Agent Plugins 1.0 standard takes the ecosystem next.

Seats are $20, and here''s the honest math: every dollar goes toward dinner from Virgilio''s, right here in Gloucester. We''d rather feed fifteen people who show up than hold seats for thirty who might. You''re not buying a ticket, you''re claiming a chair at the table.

The room is small on purpose. Bring questions, not laptops. Dinner''s handled.

Event Details:

📅 Date: Thursday, September 24, 2026

📍 Venue: Wheelhouse Cowork Harborside

📌 Address: 33 Commercial St, Gloucester, MA 01930

Secure your Eventbrite ticket to reserve one of the 15 seats.

🎟️ Get Tickets: https://www.eventbrite.com/e/under-the-hood-of-microsoft-scout-tickets-1999380902100 If you care about healthcare, AI, cloud technology, or how emerging agent technologies are actually being implemented, we''d love to have you around the table.', ARRAY['https://aiweek.boston/schedule/under-the-hood-of-microsoft-scout-a-15-seat-working-session-on-corporate-ai-agen']::text[], now()),
  ('venture-lanes-oktoberfest-2026@aiweek.boston', 'Venture Lane''s Oktoberfest 2026', 'https://aiweek.boston/schedule/venture-lanes-oktoberfest-2026', 'https://markitai.com/e/v62tRIZBf', TRUE, '2026-09-24T17:00:00-04:00'::timestamptz, '2026-09-24T20:00:00-04:00'::timestamptz, 'Venture Lane', '55 Court St Floor 2, Boston, MA 02108', 'Boston', 'Meetup', 'Venture Lane', '[]'::jsonb, 'Venture Lane''s Oktoberfest 2026', 'For a special edition of Venture Lane''s monthly Blue Hour event, we''re gathering the incredible founders, mentors, and investors you know and love. This time, be sure to don your lederhosen and join us for festivities hosted in true German Oktoberfest style.', ARRAY['https://aiweek.boston/schedule/venture-lanes-oktoberfest-2026']::text[], now()),
  ('b2b-tech-oktoberfest@aiweek.boston', 'B2B Tech Oktoberfest', 'https://aiweek.boston/schedule/b2b-tech-oktoberfest', 'https://markitai.com/e/v62tRIZBf', TRUE, '2026-09-24T17:30:00-04:00'::timestamptz, '2026-09-24T19:30:00-04:00'::timestamptz, 'Venture Lane | Startup Hub', '55 Court Street, Floor 2, Boston, MA 02108', 'Boston', 'Meetup', 'Venture Lane', '[]'::jsonb, 'B2B Tech Oktoberfest', 'Calling all founders, mentors, and investors in the Boston startup community. Join us at Venture Lane for an evening of Oktoberfest festivities.

Come dressed in your best lederhosen or dirndl and enjoy German beer, traditional food, and great conversation with the people building Boston''s startup scene. Prost!', ARRAY['https://aiweek.boston/schedule/b2b-tech-oktoberfest']::text[], now()),
  ('nuvert-healthcare-ai-activationTM-private-executive-reception-dinner@aiweek.boston', 'NuVert Healthcare AI Activation™ Private Executive Reception & Dinner', 'https://aiweek.boston/schedule/nuvert-healthcare-ai-activationTM-private-executive-reception-dinner', 'https://luma.com/g74infhz', TRUE, '2026-09-24T17:30:00-04:00'::timestamptz, '2026-09-24T20:30:00-04:00'::timestamptz, NULL, NULL, NULL, 'Meetup', 'NuVert', '[]'::jsonb, 'NuVert Healthcare AI Activation™ Private Executive Reception & Dinner', 'The day concludes with an invite-only evening focused on relationship-building. With no formal programming, the reception creates space for healthcare executives, founders, investors, researchers, government leaders, and ecosystem partners to continue the conversations sparked throughout the day, exchange perspectives, and build meaningful connections in a more personal setting.

Invitees may include healthcare CEOs and CMOs, Chiefs of Staff, hospital executives, founders and investors, government leaders, and researchers. The emphasis is simple: no pitches, no panels—just thoughtful conversation and trusted relationship-building.', ARRAY['https://aiweek.boston/schedule/nuvert-healthcare-ai-activationTM-private-executive-reception-dinner']::text[], now()),
  ('vizit-fireside-questrom-2026@aiweek.boston', 'Seeing What Consumers See: AI, Visual Intelligence, and the Future of Consumer Behavior', 'https://aiweek.boston/schedule/vizit-fireside-questrom-2026', 'https://trusted.bu.edu/s/1759/2-bu/19/1col.aspx?sid=1759&gid=2&pgid=19663&content_id=20780', TRUE, '2026-09-24T18:00:00-04:00'::timestamptz, '2026-09-24T20:00:00-04:00'::timestamptz, 'Hariri Auditorium, BU Questrom School of Business', '595 Commonwealth Ave, Boston, MA 02215', 'Boston', 'Talk', 'BU Questrom Feld Center & Ravi K. Mehrotra Institute', '[{"name":"Jehan Hamedi","bio":"Founder and CEO of Vizit, a venture-backed visual-intelligence AI company, and a BU Questrom ''12 graduate with 15+ years in enterprise software. He has led AI integrations for dozens of billion-dollar companies (including Google, Mars, L''Oreal, and Disney), holds 24+ patents in AI and computer vision, and was named to the Boston Business Journal 40 Under 40."},{"name":"Marcel Rindisbacher","bio":"Interim Dean of the Boston University Questrom School of Business and Ravi K. Mehrotra Professor of Finance. A financial economist (PhD, Université de Montréal) whose research spans asset pricing, portfolio theory, and pension design, he also directs the Ravi K. Mehrotra Institute for Business, Markets & Society."}]'::jsonb, 'Seeing What Consumers See: AI, Visual Intelligence, and the Future of Consumer Behavior', 'Join us for a fireside chat featuring Jehan Hamedi (Questrom''12), Founder and CEO of Vizit, in conversation with Marcel Rindisbacher, Ravi K. Mehrotra Professor of Business and Interim Dean of the Questrom School of Business.

A pioneer in visual intelligence and applied AI, Jehan has built technology that helps organizations understand and predict how consumers respond to visual content, unlocking new insights into attention, perception, and behavior. Together, Jehan and Marcel will explore how AI is transforming the way businesses measure and influence decision-making in an increasingly image-driven, digital-first economy.

The conversation will also examine the broader implications of these advancements at the intersection of business, markets, and society, from the future of marketing and commerce to questions of consumer agency, data ethics, and the evolving nature of attention.

Co-hosted by the BU Questrom Feld Center and the Mehrotra Institute as part of Boston AI Week, the event will be followed by an invite-only reception bringing together leaders from industry, government, and academia for continued dialogue and connection.', ARRAY['https://aiweek.boston/schedule/vizit-fireside-questrom-2026']::text[], now()),
  ('the-human-edge-women-leading-in-the-age-of-ai@aiweek.boston', 'The Human Edge: Women Leading in the Age of AI', 'https://aiweek.boston/schedule/the-human-edge-women-leading-in-the-age-of-ai', 'https://luma.com/bax9tycg', TRUE, '2026-09-24T18:00:00-04:00'::timestamptz, '2026-09-24T21:00:00-04:00'::timestamptz, 'Mass Challenge', '10 Fan Pier Blvd, Third Floor, Boston, MA 02210', 'Boston', 'Meetup', 'Women Applying AI', '[]'::jsonb, 'The Human Edge: Women Leading in the Age of AI', 'One year ago, Women Applying AI launched in Boston with a simple conviction: women are half of humanity, and we have both the responsibility and the opportunity to shape how AI transforms our work, our lives, and our world.

We''re coming back together during Boston AI Week 2026 to celebrate how far this community has come… and look ahead to what''s next.

This event is part anniversary celebration, part conversation about the future, and a recognition of people who are already putting AI to work in meaningful ways.

We''ll share stories from WAAI members whose careers, confidence, and work have changed over the past year. You''ll get a first look at the AI Confidence Index, a new Women Applying AI initiative designed to explore how people are feeling, learning, and adapting as AI becomes part of everyday work.

And because the future of AI extends well beyond the screen, we''ll dig into what happens when intelligent technology enters the physical world, with a provocative conversation about humans working alongside physical AI, followed by a live demonstration of Stella, the robot dog.

Of course, this is an anniversary. So there will be plenty of time to connect with the WAAI community, meet new people, enjoy food and drinks, and raise a glass to an extraordinary first year together.

Whether you''ve been part of Women Applying AI from the beginning, joined us somewhere along the way, or are just discovering the community, we''d love to celebrate with you.

Thank you to our generous sponsors!

Celebration Sponsor: Stellix

Venue Sponsor: Mass Challenge', ARRAY['https://aiweek.boston/schedule/the-human-edge-women-leading-in-the-age-of-ai']::text[], now()),
  ('ai-transformation-in-enterprises@aiweek.boston', 'AI Transformation in Enterprises', 'https://aiweek.boston/schedule/ai-transformation-in-enterprises', 'https://www.meetup.com/magyar-tech-meetup/events/316349905/', TRUE, '2026-09-24T18:00:00-04:00'::timestamptz, '2026-09-24T19:30:00-04:00'::timestamptz, 'BasisTech is a community of entrepreneurs, founders, and investors who work on small teams but appreciate the benefits of a vibrant office culture. Proximity to other innovators creates opportunities for cross-disciplinary learning and unexpected collaboration.', '1070 Broadway, Somerville MA 02144-2078', 'Somerville', 'Meetup', 'Precognox', '[{"name":"Gabor Angyal","bio":"Senior Director of AI & Business Technology Engineering at DigitalOcean, where he leads enterprise AI adoption, agentic AI development, and the platforms and governance frameworks for safe, productive AI use at scale. Previously VP of Engineering and VP of Privacy Operations at LastPass, he scaled engineering organizations to 300+ people and co-led an enterprise AI governance initiative built on the ISO/IEC 42001 framework."}]'::jsonb, 'AI Transformation in Enterprises', 'The event is organized by the Boston Hungarian Tech Network. Whether you are a Hungarian expat, of Hungarian descent, or have close ties to the Hungarian innovation ecosystem, this group is your local hub in the Greater Boston area. Boston is a global powerhouse for biotech, AI, robotics, and software, and there is a vibrant community of Hungarian minds driving this progress.

Our mission is simple: to connect, inspire, and support Hungarian and Hungarian-American professionals working in technology, science, startups, and venture capital.', ARRAY['https://aiweek.boston/schedule/ai-transformation-in-enterprises']::text[], now()),
  ('pmi-project-leadership-summit-2026@aiweek.boston', 'Project Leadership Summit 2026', 'https://aiweek.boston/schedule/pmi-project-leadership-summit-2026', 'https://pmimassbay.zohobackstage.com/ProjectLeadershipSummit2026AloftSeaportDistrictBoston', TRUE, '2026-09-25T08:00:00-04:00'::timestamptz, '2026-09-25T17:00:00-04:00'::timestamptz, 'Aloft by Marriott Boston Seaport District', '401-403 D St, Boston, MA 02210', 'Boston', 'Conference', 'PMI Mass Bay Chapter', '[{"name":"Offiong Bassey","bio":null},{"name":"Hilary Blair","bio":null},{"name":"Brandon Conrad","bio":null},{"name":"Lisa DiTullio","bio":null},{"name":"Eric Foss","bio":null},{"name":"Garrett Frohman","bio":null},{"name":"Rob Frohman","bio":null},{"name":"Michael Harshbarger","bio":null},{"name":"Katrenia Yvette Reed Hughes","bio":null},{"name":"David Otey","bio":null},{"name":"Joe Perzel","bio":null}]'::jsonb, 'Project Leadership Summit 2026', 'The world of project leadership is changing fast. AI is reshaping how work gets planned, managed, and delivered. Decisions are moving faster. Teams are becoming more complex. Stakeholders expect more clarity, adaptability, and impact. Project Leadership Summit 2026 is designed for professionals who are ready to meet the moment. Join us for a full-day leadership experience in Boston''s Seaport District, where project professionals, innovators, and organizational leaders will come together to explore the future of project work and the skills needed to lead it.

Hosted by the PMI Mass Bay Chapter (Project Management Institute Mass Bay Chapter, Boston). Contact: Dan Yotive, PMI Mass Bay Chapter.

Sponsors and partners: Harpoon Brewery, IIL, Gourdin Coaching.

Tickets start at $327. Boston AI Week attendees save 20% with discount code BostonAIWeek2026PLS at registration.', ARRAY['https://aiweek.boston/schedule/pmi-project-leadership-summit-2026']::text[], now()),
  ('human-centric-ai-summit-2026@aiweek.boston', 'Human-Centric AI Summit: Shaping the Future of Equitable Healthcare', 'https://aiweek.boston/schedule/human-centric-ai-summit-2026', 'https://mahealthcouncil.org/event/AISummit', TRUE, '2026-09-25T09:00:00-04:00'::timestamptz, '2026-09-25T14:00:00-04:00'::timestamptz, 'MIT Media Lab', '75 Amherst St, Cambridge, MA 02142', 'Cambridge', 'Conference', 'Massachusetts Health Council', '[]'::jsonb, 'Human-Centric AI Summit: Shaping the Future of Equitable Healthcare', 'Artificial Intelligence is rapidly transforming healthcare, public health, human services, and research. While these technologies offer tremendous opportunities, between 60-80% of AI projects fail due to issues traced to people, leadership, change management and processes, not technology. This raises important questions about fairness, transparency, privacy, and access.

This summit is centered on balancing innovation with structured AI governance that is equitable and patient-centered. It will bring together diverse voices from across Massachusetts to explore how AI can be implemented equitably. Participants will leave with practical knowledge, new connections, and actionable ideas for navigating the future of AI in their organizations and communities.

Hosted by the Massachusetts Health Council. Speakers, moderators, and sponsors: to be announced.', ARRAY['https://aiweek.boston/schedule/human-centric-ai-summit-2026']::text[], now()),
  ('agentic-world-cup-boston-build-ai-agents-that-play-soccer@aiweek.boston', 'Agentic World Cup Boston: Build AI Agents That Play Soccer', 'https://aiweek.boston/schedule/agentic-world-cup-boston-build-ai-agents-that-play-soccer', 'https://startups.aws.com/events/agentic-world-cup-boston-build-ai-agents-that-play-soccer', TRUE, '2026-09-25T09:00:00-04:00'::timestamptz, '2026-09-25T13:00:00-04:00'::timestamptz, 'Amazon BOS17 office building.', '27 Melcher St, Boston, MA 02210', 'Boston', 'Workshop', 'AWS', '[]'::jsonb, 'Agentic World Cup Boston: Build AI Agents That Play Soccer', 'We propose a half-day Agentic Football Cup hackathon during Boston AI Week 2026 — a proven, globally-run AWS workshop (100+ events, rated 4.8/5) where participants build a squad of five autonomous AI agents using Amazon Bedrock AgentCore and the Strands Agents SDK, then compete in live 5v5 AI football matches on a real-time leaderboard. Participants write the strategy; their agents play the match. Five autonomous AI agents per team make decisions every two seconds — passing, shooting, pressing, and defending — with no human input once the whistle blows. This isn''t a demo you watch; it''s a working system you build and deploy in an afternoon.

Every 2 seconds, the game server emits a decision point and calls all 10 agents in parallel with the full game state. Each agent has 1 second to return one of eleven structured commands: MOVE_TO | PASS | SHOOT | DRIBBLE | PRESS_BALL | MARK | INTERCEPT | TACKLE | CLEAR | IDLE | (GK actions). Miss the deadline → your player IDLEs for that tick. The match doesn''t pause. This hard latency contract mirrors real production agentic workloads. The thing participants tune is almost never the code — it''s the prompt and the model choice: system prompt encodes team tactics, model selection balances reasoning depth vs. latency budget, and structured output schema bounds the action space.

Teams of 2–4 (form on-site or pre-register). No AI/ML experience needed — the workshop is designed for developers of all levels. Non-technical teammates welcome.

Every team that completes the workshop qualifies for the Agentic Football Cup global league. Group winners fly to Las Vegas to compete live on stage at AWS re:Invent. This Boston AI Week event is their qualifying round — a global competition with a trip to Vegas on the line.', ARRAY['https://aiweek.boston/schedule/agentic-world-cup-boston-build-ai-agents-that-play-soccer']::text[], now()),
  ('building-to-amplify-human-potential-in-an-ai-first-world@aiweek.boston', 'Building to Amplify Human Potential in an AI First World', 'https://aiweek.boston/schedule/building-to-amplify-human-potential-in-an-ai-first-world', 'https://luma.com/01oosuir', TRUE, '2026-09-25T09:00:00-04:00'::timestamptz, '2026-09-25T15:30:00-04:00'::timestamptz, 'Microsoft New England Research and Development Center (NERD) building', '1 Memorial DrCambridge, MA 02142', 'Cambridge', 'Conference', 'NuVert', '[{"name":"Ambassador Muhammadou Kah","bio":"Vice President of the UN Human Rights Council and Co-Chair of the UN Commission on Science, Technology and Development; delivers the keynote on activating socially responsible AI."}]'::jsonb, 'Building to Amplify Human Potential in an AI First World', 'Day 2 (September 25) follows the arc Leadership → Global Perspective → Local Relevance → Responsible AI in Practice → Commitments. It opens with brief remarks connecting the event to international AI initiatives and Boston AI Week, followed by a keynote from Ambassador Muhammadou Kah on Activating Socially Responsible AI in an Era of Uncertainty.

Two global leadership panels then explore human potential and trust, and AI governance plus capital, bringing international perspectives from Africa, India, Europe, and beyond.

After a leadership lunch and networking, the focus shifts locally with a “Why Boston Is?” panel examining the city’s unique strengths and gaps as a responsible AI ecosystem, then moves into partner presentations on responsible AI in practice. The day closes with a commitment session in which each executive identifies one organizational, one ecosystem, and one leadership commitment to guide post-event collaboration.', ARRAY['https://aiweek.boston/schedule/building-to-amplify-human-potential-in-an-ai-first-world']::text[], now()),
  ('clawbio-developing-your-own-genomic-agent-from-scratch@aiweek.boston', 'ClawBio, developing your own genomic agent from scratch', 'https://aiweek.boston/schedule/clawbio-developing-your-own-genomic-agent-from-scratch', 'https://luma.com/clawbio-broad-2026', TRUE, '2026-09-25T09:00:00-04:00'::timestamptz, '2026-09-25T16:00:00-04:00'::timestamptz, 'Broad Institute', '300B Binney St, Cambridge, MA 02142', 'Cambridge', 'Workshop', 'ClawBio', '[]'::jsonb, 'ClawBio, developing your own genomic agent from scratch', 'One day. Real genomic questions. Build agents that do useful scientific work, then show the room what they found.

AI agents can plan multi-step work, call tools, run analyses and recover from failure. Biology is where that gets hard: results must be reproducible, evidence must be traceable, and an agent must know when it cannot support a claim.

ClawBio is open-source infrastructure for that work. Its versioned skills make an agent''s methods inspectable, reproducible and open to challenge.

Everything runs through Slack: the ClawBio Slack community is where participants work before, during and after the event. Registered participants receive a short technical preflight through Slack and should complete it before arrival.

What you will build: Choose a published challenge brief or bring a biological question. Challenge directions include: End the diagnostic odyssey; Build a cancer target you would defend; Ask whose genome a method fails on; Bring your own question. Your team will build an agent that can do useful scientific work, expose its evidence and state what it cannot claim.

What you get: A full day focused on one real scientific problem; a team of four to five people formed around shared interests; practical support with ClawBio, agent workflows and reproducible bioinformatics; a chance to demo what you built; a community workspace that remains active after the event.

Who should come: Bioinformaticians and computational biologists; genomics researchers and clinical scientists; software engineers and research software engineers; machine learning practitioners interested in scientific agents; students, founders and builders with a serious biological question. No previous ClawBio or AI coding-agent experience is required. You should be comfortable reading or running code. Bring a laptop and charger. Teams will be formed on the day.

Programme: 09:00 Doors open and community introductions; 09:20 Welcome: genomics in an agentic world; 09:40 ClawBio primer and scientific challenge briefs; 10:10 Team formation and scope check; 10:30 Build sprint one; 12:00 Technical checkpoint and break; 12:30 Build sprint two; 14:30 Test, challenge and document; 15:15 Team demos and room voting; 16:00 Close and community follow-up.

Practical details: Friday 25 September 2026, 09:00 to 16:00 EDT. Broad Institute | 300B, 300 Binney St, Cambridge, MA 02142. Registration is required. Only public or synthetic data may be used during the hackathon. Organised by Manuel Corpas and Mohammad Tanhaemami.', ARRAY['https://aiweek.boston/schedule/clawbio-developing-your-own-genomic-agent-from-scratch']::text[], now()),
  ('ai-in-mechanical-engineering-and-manufacturing@aiweek.boston', 'AI in Mechanical Engineering and Manufacturing', 'https://aiweek.boston/schedule/ai-in-mechanical-engineering-and-manufacturing', 'https://luma.com/xvnekefl', TRUE, '2026-09-25T10:00:00-04:00'::timestamptz, '2026-09-25T16:00:00-04:00'::timestamptz, 'PTC', '121 Seaport Blvd, Boston, MA 02210, Floor 3', 'Boston', 'Conference', 'PTC for Startups', '[]'::jsonb, 'AI in Mechanical Engineering and Manufacturing', 'Let''s figure out how to best use AI in mechanical engineering and manufacturing! There a lot of promise and the field is moving fast. If you''re an engineering practitioner experimenting with AI, we invite you to come share your experiences and learnings and hear from your peers. We''ll all leave with new insights, approaches and strategies for how to use AI to solve our real work problems.

This is an unconference! It''s not about product pitches, it''s about sharing our opinions and experiences. Come ready with topics you''d like to discuss, we''ll start by collaboratively defining the agenda and discussion topics. Make sure to sign up for the Boston AI Week kickoff party afterwards next door!

Hosted by PTC for Startups, a program that provides eligible startups with free access to industry-leading product development and engineering software, helping founders bring innovative products to market faster and scale with confidence.', ARRAY['https://aiweek.boston/schedule/ai-in-mechanical-engineering-and-manufacturing']::text[], now()),
  ('custom-software-at-business-speed-from-operator-requirement-to-governed-prototyp@aiweek.boston', 'Custom Software at Business Speed: From Operator Requirement to Governed Prototype', 'https://aiweek.boston/schedule/custom-software-at-business-speed-from-operator-requirement-to-governed-prototyp', 'https://www.linkedin.com/events/7486846745281339393/', TRUE, '2026-09-25T12:00:00-04:00'::timestamptz, '2026-09-25T12:45:00-04:00'::timestamptz, NULL, NULL, NULL, 'Talk', 'Aortem', '[{"name":"Jeremy Andrews","bio":"Founder of Aortem."}]'::jsonb, 'Custom Software at Business Speed: From Operator Requirement to Governed Prototype', 'Marketing and program teams often know exactly what a workflow, customer experience, or internal tool needs to do, but translating that requirement into working software can take weeks of handoffs.

This 45-minute practitioner-led virtual session shows how AI-assisted delivery can turn bounded business requirements into testable prototypes and software customizations in hours or days, without treating engineering review, security, accessibility, data governance, or production readiness as optional.

Aortem will use two confidential examples at a high level: current work for a global financial-software company involving Salesforce requirements, showing how the requirement is clarified, bounded, and prepared for validation; and a multilingual customer-experience widget for a global beauty brand. Examples will be anonymized and limited to the requirements, delivery process, and lessons that can be shared publicly.

A live demonstration will take one operator requirement through an implementation-ready specification, working prototype, validation, and a governed production handoff.

Agenda:

- 5 minutes: Why the traditional request-and-backlog model is changing

- 10 minutes: Turning a business requirement into an implementation-ready specification

- 10 minutes: Two anonymized enterprise examples

- 10 minutes: Live requirement-to-working-prototype demonstration

- 5 minutes: Production, security, and governance boundaries

- 5 minutes: Questions

Attendees will leave with a practical method for identifying bounded use cases, writing a prototype-ready requirement, and distinguishing a validated prototype from production-ready software.', ARRAY['https://aiweek.boston/schedule/custom-software-at-business-speed-from-operator-requirement-to-governed-prototyp']::text[], now()),
  ('boat-rides-boston-harbor-captain-chris-2026-09-25@aiweek.boston', 'Boat Rides of Boston Harbor with Captain Chris', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-25', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-25', FALSE, '2026-09-25T12:00:00-04:00'::timestamptz, '2026-09-25T13:00:00-04:00'::timestamptz, 'Fan Pier', 'Fan Pier, Boston, MA', 'Boston', 'Meetup', 'Boston AI Week', '[]'::jsonb, 'Boat Rides of Boston Harbor with Captain Chris', 'Join Captain Chris for a boat ride on Boston Harbor, offered every day of Boston AI Week''s core week (September 24 – October 2). Very limited availability. RSVP to be considered, we''ll work with Captain Chris on approvals. Due to expected demand, not all RSVPs will be honored, but we''ll do our best.

Time: TBA. This is a request, not a confirmed spot — organizers will follow up if your RSVP is approved.', ARRAY['https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-25']::text[], now()),
  ('show-me-something-cool-with-ai@aiweek.boston', 'Show Me Something Cool With AI', 'https://aiweek.boston/schedule/show-me-something-cool-with-ai', 'https://luma.com/wq8dqahi', TRUE, '2026-09-25T13:00:00-04:00'::timestamptz, '2026-09-25T14:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Meetup', 'Learn to Scale', '[]'::jsonb, 'Show Me Something Cool With AI', 'If you are feeling a little overwhelmed by the constant flood of breathless AI news, join the club. It feels like every day there is a new tool we are all supposed to master by yesterday.

"Show Me Something Cool With AI" is our antidote to that overwhelming feeling.

This is a casual, monthly gathering where we ignore the tech hype and just look at what this stuff can actually do for us. You do not need to know how to code. You do not need to be a prompt engineer. You just need to be curious.

We created this space because the best way to get comfortable with new technology is to play with it in a room full of supportive people. Here is what we do at SMSCWAI:

~ The Sandbox (45 mins): We start with the fun stuff. We might generate ridiculous movie posters of our pets, make AI write a silly song, or sketch a picture on a napkin and watch a tool turn it into a working website. Playing is the fastest way to learn, and we keep the stakes incredibly low.

~ The Practical Pivot (15 mins): Once we are comfortable, we look at one real, everyday business problem. I will show you exactly how leaders are using AI to stop doing the boring work. We might look at how to clean up a messy spreadsheet in seconds or how to draft a quick policy so your team can use these tools safely.

~ Open Floor (the whole time): Bring your questions, share something weird you found, or just hang out.

Who is this for? Small business leaders, creative folks, HR professionals, and anyone who wants to peek behind the chatbox. If you want to understand how AI can help you save time and boost your creativity without feeling like you are sitting in a computer science lecture, you belong here.

Grab a coffee, bring your curiosity, and come see or share something cool.

Hosted by Learn to Scale, your AI transformation partner.', ARRAY['https://aiweek.boston/schedule/show-me-something-cool-with-ai']::text[], now()),
  ('the-ai-identity-shift-rebuilding-leadership-structure-and-capabilities-for-the-n@aiweek.boston', 'The AI Identity Shift - Rebuilding Leadership, Structure, and Capabilities for the New Economy', 'https://aiweek.boston/schedule/the-ai-identity-shift-rebuilding-leadership-structure-and-capabilities-for-the-n', 'https://aiweek.boston/schedule/the-ai-identity-shift-rebuilding-leadership-structure-and-capabilities-for-the-n', FALSE, '2026-09-25T14:00:00-04:00'::timestamptz, '2026-09-25T16:30:00-04:00'::timestamptz, 'Bevi Headquarters at the historic Schrafft''s building', '529 Main Street, Charlestown, MA', 'Boston', 'Panel', 'Bevi', '[{"name":"Debbie Millin","bio":"Panelist on organizational structure and The Elastic C-Suite."},{"name":"Dr. Patti Fletcher","bio":"AI strategist & author; panelist on leadership and The Identity Reset."},{"name":"Christine Parker","bio":"Moderator; panelist on skills and The Capability Lens."}]'::jsonb, 'The AI Identity Shift - Rebuilding Leadership, Structure, and Capabilities for the New Economy', 'AI is no longer just shifting the tools we use—it is fundamentally redefining what leadership requires and how organizations execute work. We will explore how expertise, fluid AI-integrated executive teams, and true human potential intersect in the new economy. After the discussion enjoy a tour of the Bevi offices in the historic Schrafft''s building. Parking is FREE and space is limited—reserve your spot today!

Panelists:

• Debbie Millin - The Elastic C-Suite ➡️ organizational structure

• Dr. Patti Fletcher - The Identity Reset ➡️ leadership

• Christine Parker (Moderator) - The Capability Lens ➡️ skills', ARRAY['https://aiweek.boston/schedule/the-ai-identity-shift-rebuilding-leadership-structure-and-capabilities-for-the-n']::text[], now()),
