  ('simulating-cinema-with-aiemerson@aiweek.boston', 'Simulating Cinema with AI@Emerson', 'https://aiweek.boston/schedule/simulating-cinema-with-aiemerson', 'https://aiweek.boston/schedule/simulating-cinema-with-aiemerson', FALSE, '2026-09-25T18:00:00-04:00'::timestamptz, '2026-09-25T21:00:00-04:00'::timestamptz, 'Emerson College', NULL, NULL, 'Workshop', 'Emerson College', '[]'::jsonb, 'Simulating Cinema with AI@Emerson', 'Will add details later', ARRAY['https://aiweek.boston/schedule/simulating-cinema-with-aiemerson']::text[], now()),
  ('devfest-boston-2026@aiweek.boston', 'DevFest Boston 2026', 'https://aiweek.boston/schedule/devfest-boston-2026', 'https://aiweek.boston/schedule/devfest-boston-2026', FALSE, '2026-09-26T09:00:00-04:00'::timestamptz, '2026-09-26T17:00:00-04:00'::timestamptz, 'Hult International Business School', '1 Education Street, Cambridge, MA 02141', 'Cambridge', 'Conference', 'Google Developer Group (GDG) Cloud Boston', '[]'::jsonb, 'DevFest Boston 2026', 'DevFest Boston 2026 is the flagship annual conference hosted by GDG Cloud Boston, bringing together developers, AI practitioners, cloud engineers, students, and technology leaders for a day of learning, innovation, and networking. Join us for expert talks, hands-on technical sessions, and community-driven discussions covering AI, Google Cloud, Gemini, Web, Android, Firebase, and modern software engineering. Whether you''re new to Google technologies or an experienced developer, DevFest Boston 2026 offers something for everyone.', ARRAY['https://aiweek.boston/schedule/devfest-boston-2026']::text[], now()),
  ('glasswing-ventures-enterprise-ready-ai-hackathon@aiweek.boston', 'Glasswing Ventures Enterprise-Ready AI Hackathon — Day 1 ($300K in Compute!)', 'https://aiweek.boston/schedule/glasswing-ventures-enterprise-ready-ai-hackathon', 'https://luma.com/gzpv85yq', TRUE, '2026-09-26T09:30:00-04:00'::timestamptz, '2026-09-26T17:30:00-04:00'::timestamptz, 'Glasswing Ventures', '275 Newbury Street, Boston, MA', 'Boston', 'Hackathon', 'Glasswing Ventures', '[]'::jsonb, 'Glasswing Ventures Enterprise-Ready AI Hackathon — Day 1 ($300K in Compute!)', 'A two-day, in-person AI hackathon for a highly selective group of technical builders, hosted by Glasswing Ventures. Teams build enterprise-ready AI products — judged on both technical execution and commercial viability — with compute and on-site engineering support provided throughout both build days. Grand prize: $300K in compute credits. Submissions must demonstrate measurable ROI and a credible path to enterprise deployment. Powered by AWS, Microsoft, and TensorWave. Applications are reviewed on a rolling basis, and all applicants will be contacted by email.

Test Flight is a two-day, in-person AI hackathon in Boston, hosted by Glasswing Ventures. One weekend and $300,000 in compute on the line for the team that wins. The theme is Enterprise-Ready AI, so you are not building a demo that impresses your friends, you are building something a real company would actually deploy. Judges want measurable ROI and a credible path to production. Clever technology alone does not clear the bar. Glasswing brings the compute, the credits, the on-site engineering, and mentors from leading AI infrastructure partners, so the only constraint is what you can ship before the clock runs out. Saturday you build. Sunday at 2:00 PM the code freezes, you demo live to the panel, and awards go to the teams that turned a hard enterprise problem into something that works.

Apply solo or bring a team (up to 4), and if you are flying solo or short a few people, we will match you with other builders who made the cut. One application per person, even if you are applying together. We review on a rolling basis, so the sooner you are in, the better.', ARRAY['https://aiweek.boston/schedule/glasswing-ventures-enterprise-ready-ai-hackathon']::text[], now()),
  ('architecting-with-ai-developer-roundtable@aiweek.boston', 'Architecting with AI: A Developer Roundtable on Software Engineering in the Agent Era', 'https://aiweek.boston/schedule/architecting-with-ai-developer-roundtable', 'https://aiweek.boston/schedule/architecting-with-ai-developer-roundtable', FALSE, '2026-09-26T10:00:00-04:00'::timestamptz, '2026-09-26T11:30:00-04:00'::timestamptz, NULL, NULL, NULL, 'Panel', 'Independent', '[{"name":"CJ Avilla","bio":null},{"name":"Chad Pytel","bio":null},{"name":"Kranthi Manchikanti","bio":null},{"name":"Andrea Dulko","bio":null},{"name":"Jesse Waites","bio":"Host of the roundtable."}]'::jsonb, 'Architecting with AI: A Developer Roundtable on Software Engineering in the Agent Era', 'As AI coding tools evolve from autocomplete helpers into autonomous multi-agent systems, the role of the software engineer is undergoing a massive shift. Join a working roundtable of practitioners to compare notes on architecture, workflows, evaluation, and what changes when agents do the writing. Hosted by Jesse Waites.', ARRAY['https://aiweek.boston/schedule/architecting-with-ai-developer-roundtable']::text[], now()),
  ('robot-block-party-2026@aiweek.boston', 'Robot Block Party', 'https://aiweek.boston/schedule/robot-block-party-2026', 'https://www.massrobotics.org/roboboston/', TRUE, '2026-09-26T11:00:00-04:00'::timestamptz, '2026-09-26T16:00:00-04:00'::timestamptz, 'MassRobotics (Large Tents on parking lot)', '85 Northern Ave, Boston, MA', 'Boston', 'Community', 'MassRobotics', '[]'::jsonb, 'Robot Block Party', 'RoboBoston is the largest celebration of robotics that showcases cutting-edge robotics and Physical AI technology from more than 50 companies, universities, and student teams, all united in Boston''s vibrant innovation hub in the Seaport. Open house style block party.', ARRAY['https://aiweek.boston/schedule/robot-block-party-2026']::text[], now()),
  ('boat-rides-boston-harbor-captain-chris-2026-09-26@aiweek.boston', 'Boat Rides of Boston Harbor with Captain Chris', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-26', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-26', FALSE, '2026-09-26T12:00:00-04:00'::timestamptz, '2026-09-26T13:00:00-04:00'::timestamptz, 'Fan Pier', 'Fan Pier, Boston, MA', 'Boston', 'Meetup', 'Boston AI Week', '[]'::jsonb, 'Boat Rides of Boston Harbor with Captain Chris', 'Join Captain Chris for a boat ride on Boston Harbor, offered every day of Boston AI Week''s core week (September 24 – October 2). Very limited availability. RSVP to be considered, we''ll work with Captain Chris on approvals. Due to expected demand, not all RSVPs will be honored, but we''ll do our best.

Time: TBA. This is a request, not a confirmed spot — organizers will follow up if your RSVP is approved.', ARRAY['https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-26']::text[], now()),
  ('the-underutilization-hypothesis-on-the-allocation-of-existing-artificial-intelli@aiweek.boston', 'The Underutilization Hypothesis: On the Allocation of Existing Artificial Intelligence, Human Comparative Advantage, and the Question of What Computation Is For', 'https://aiweek.boston/schedule/the-underutilization-hypothesis-on-the-allocation-of-existing-artificial-intelli', 'https://aiweek.boston/schedule/the-underutilization-hypothesis-on-the-allocation-of-existing-artificial-intelli', FALSE, '2026-09-26T14:00:00-04:00'::timestamptz, '2026-09-26T15:00:00-04:00'::timestamptz, 'To be determined', 'To be determined', NULL, 'Talk', 'Independent', '[{"name":"David Goldberg","bio":null}]'::jsonb, 'The Underutilization Hypothesis: On the Allocation of Existing Artificial Intelligence, Human Comparative Advantage, and the Question of What Computation Is For', 'Public debate about artificial intelligence runs along two tracks: whether deployment is outpacing our ability to govern it, and when systems will match general human capability. These look like opposing camps, but they share an assumption - that the decision variable is the quantity of machine intelligence. One asks for less, while the other asks how soon there will be more. This talk argues that the more consequential variable is allocation. A large fraction of the realizable value of today''s AI systems may go unrealized, not because the systems are insufficiently capable, but because capability flows toward applications with appropriable returns and low integration costs, and away from the diffuse, institutionally fragmented problems that make up much of scientific, administrative, and educational work. That pattern may be the predictable behavior of a functioning market applied to a technology with large positive externalities, meaning that capability improvements alone may not correct it. I''ll introduce a framework for reasoning about return per unit of compute, a model of where human conceptual work retains economic value without any appeal to human superiority, and what AI''s gold-medal Mathematical Olympiad performance does and doesn''t establish. Environmental constraints are treated as binding, not as an objection to wave off.', ARRAY['https://aiweek.boston/schedule/the-underutilization-hypothesis-on-the-allocation-of-existing-artificial-intelli']::text[], now()),
  ('code-counsels-human-in-the-loop-ping-pong-meetup@aiweek.boston', 'Code & Counsel''s Human in the Loop Ping Pong Meetup', 'https://aiweek.boston/schedule/code-counsels-human-in-the-loop-ping-pong-meetup', 'https://luma.com/nihzmk1n', TRUE, '2026-09-26T18:00:00-04:00'::timestamptz, '2026-09-26T20:00:00-04:00'::timestamptz, 'SPIN Boston (Seaport)', '30 MELCHER ST., BOSTON, MA 02210', 'Boston', 'Community', 'Code & Counsel', '[]'::jsonb, 'Code & Counsel''s Human in the Loop Ping Pong Meetup', 'Code + Counsel''s Human-in-the-Loop Ping Pong Meetup brings together legal and AI professionals for an informal evening of conversation, connection, and friendly competition at SPIN Boston. Join us on Saturday, September 26, from 6:00–8:00 p.m. for two hours of ping pong and networking, sponsored by Code & Counsel. Attendance is free, but advance registration is required and space is very limited.', ARRAY['https://aiweek.boston/schedule/code-counsels-human-in-the-loop-ping-pong-meetup']::text[], now()),
  ('glasswing-ventures-enterprise-ready-ai-hackathon-day-2@aiweek.boston', 'Glasswing Ventures Enterprise-Ready AI Hackathon — Day 2 ($300K in Compute!)', 'https://aiweek.boston/schedule/glasswing-ventures-enterprise-ready-ai-hackathon-day-2', 'https://luma.com/gzpv85yq', TRUE, '2026-09-27T09:30:00-04:00'::timestamptz, '2026-09-27T17:30:00-04:00'::timestamptz, 'Glasswing Ventures', '275 Newbury Street, Boston, MA', 'Boston', 'Hackathon', 'Glasswing Ventures', '[]'::jsonb, 'Glasswing Ventures Enterprise-Ready AI Hackathon — Day 2 ($300K in Compute!)', 'Day 2 is demo and awards day. A two-day, in-person AI hackathon for a highly selective group of technical builders, hosted by Glasswing Ventures. Teams build enterprise-ready AI products — judged on both technical execution and commercial viability — with compute and on-site engineering support provided throughout both build days. Grand prize: $300K in compute credits. Submissions must demonstrate measurable ROI and a credible path to enterprise deployment. Powered by AWS, Microsoft, and TensorWave. Applications are reviewed on a rolling basis, and all applicants will be contacted by email.

Location: Glasswing Ventures, 275 Newbury Street, Boston, MA. Test Flight is a two-day, in-person AI hackathon in Boston, hosted by Glasswing Ventures. One weekend and $300,000 in compute on the line for the team that wins. The theme is Enterprise-Ready AI, so you are not building a demo that impresses your friends, you are building something a real company would actually deploy. Judges want measurable ROI and a credible path to production. Clever technology alone does not clear the bar. Glasswing brings the compute, the credits, the on-site engineering, and mentors from leading AI infrastructure partners, so the only constraint is what you can ship before the clock runs out. Saturday you build. Sunday at 2:00 PM the code freezes, you demo live to the panel, and awards go to the teams that turned a hard enterprise problem into something that works.

Apply solo or bring a team (up to 4), and if you are flying solo or short a few people, we will match you with other builders who made the cut. One application per person, even if you are applying together. We review on a rolling basis, so the sooner you are in, the better.', ARRAY['https://aiweek.boston/schedule/glasswing-ventures-enterprise-ready-ai-hackathon-day-2']::text[], now()),
  ('recursive-learning-hackathon-2026@aiweek.boston', 'Recursive Learning Hackathon — Harvard Innovation Labs × Sundai', 'https://aiweek.boston/schedule/recursive-learning-hackathon-2026', 'https://www.sundai.club/events/boston/recursive-learning-hack-with-harvard-innovation-labs', TRUE, '2026-09-27T10:00:00-04:00'::timestamptz, '2026-09-27T21:00:00-04:00'::timestamptz, 'Harvard Innovation Labs', '125 Western Ave, Allston, MA', 'Boston', 'Hackathon', 'Harvard Innovation Labs and Sundai', '[]'::jsonb, 'Recursive Learning Hackathon — Harvard Innovation Labs × Sundai', 'What happens when AI systems can learn from their own work, improve their strategies, and get better over time? In this hack, hosted by Sundai in partnership with the Harvard Innovation Labs, we explore recursive learning: systems that use their own outputs, experience, feedback, or generated data to improve future performance. Researchers, hackers, and AI builders are welcome — come see how far we can push AI systems that learn how to learn.

Schedule

10:00 AM — Sundai intro for newcomers

10:10 AM — AI news

10:30 AM — Recursive learning intro

11:00 AM — Idea pitching and team formation

2:00 PM — Check-in #1 and lunch

4:00 PM — Optional 5k run/bike

8:00 PM — Final presentations

About Sundai: an MIT / Harvard AI hacker group that meets every Sunday to build a new AI app from scratch by the end of the day, with 110+ hacks back-to-back over the last two years.

New to Sundai? Register on the host''s page for Discord setup and newcomer onboarding details before the event.', ARRAY['https://aiweek.boston/schedule/recursive-learning-hackathon-2026']::text[], now()),
  ('code-counsels-legal-ai-community-hackathon-building-common-ground@aiweek.boston', 'Code & Counsel''s Legal AI Community Hackathon: Building Common Ground', 'https://aiweek.boston/schedule/code-counsels-legal-ai-community-hackathon-building-common-ground', 'https://luma.com/kt5j0ocm', TRUE, '2026-09-27T11:00:00-04:00'::timestamptz, '2026-09-27T14:00:00-04:00'::timestamptz, 'The Foundry', '101 Rogers St, Cambridge, MA 02142', 'Cambridge', 'Workshop', 'Code & Counsel', '[]'::jsonb, 'Code & Counsel''s Legal AI Community Hackathon: Building Common Ground', 'Registration: Free and open to the public; advance registration required

Eligibility: Ages 18+

Code & Counsel’s Legal AI Community Hackathon: Building Common Ground is a three-hour public-interest design sprint focused on how artificial intelligence, paired with legal knowledge and meaningful human review, can help address everyday legal and administrative challenges facing underserved communities.

Participants from legal, technology, product, design, public service, and community backgrounds are welcome. No coding experience is required. Attendees may register individually and be assigned to a team or register with others. Teams of four to five participants will develop a practical concept, workflow, prototype, or demonstration aimed at making legal information, processes, or services easier to understand and navigate.

Projects may explore issues such as housing stability, employment and income, consumer protection, public benefits, access to essential services, document organization, deadline awareness, and connections to qualified legal or community assistance. Each team will be asked to identify where AI can help, where legal knowledge is required, and where a lawyer, advocate, caseworker, or other human professional must remain involved.

*This is not a legal clinic, and participants should not bring confidential client information, active case files, or personally identifiable information. All projects should use fictional, synthetic, de-identified, public, or properly licensed materials.', ARRAY['https://aiweek.boston/schedule/code-counsels-legal-ai-community-hackathon-building-common-ground']::text[], now()),
  ('imagination-in-action-ai-retreat@aiweek.boston', 'Imagination in Action AI Retreat', 'https://aiweek.boston/schedule/imagination-in-action-ai-retreat', 'https://luma.com/3sgqtj5q', TRUE, '2026-09-27T11:00:00-04:00'::timestamptz, '2026-09-27T16:00:00-04:00'::timestamptz, 'At a beautiful home in a magical setting, Dedham MA', NULL, 'Dedham', 'Community', 'Imagination in Action', '[]'::jsonb, 'Imagination in Action AI Retreat', 'This distinctive retreat will be hosted at a remarkable home in Dedham MA. The purpose of this AI Retreat is to create an environment rich in intellectual stimulation, where esteemed professionals from science, engineering, and technology can connect. We envision the retreat as a forum for vibrant, thought-provoking discussions, and a window into the latest challenges and breakthroughs in our field.

Our guest roster is carefully curated to include leaders and passionate innovators in their domains. The day is designed to be a serene escape from the daily grind, providing an ideal backdrop for meaningful conversations about the major trends shaping our future. It''s a rare chance to engage with key figures driving these changes.

As a guest, your participation will immensely enrich the dialogue at our retreat, and your presence is a great honor. We look forward to the opportunity of welcoming you to what is sure to be a memorable and enlightening retreat.', ARRAY['https://aiweek.boston/schedule/imagination-in-action-ai-retreat']::text[], now()),
  ('boat-rides-boston-harbor-captain-chris-2026-09-27@aiweek.boston', 'Boat Rides of Boston Harbor with Captain Chris', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-27', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-27', FALSE, '2026-09-27T12:00:00-04:00'::timestamptz, '2026-09-27T13:00:00-04:00'::timestamptz, 'Fan Pier', 'Fan Pier, Boston, MA', 'Boston', 'Meetup', 'Boston AI Week', '[]'::jsonb, 'Boat Rides of Boston Harbor with Captain Chris', 'Join Captain Chris for a boat ride on Boston Harbor, offered every day of Boston AI Week''s core week (September 24 – October 2). Very limited availability. RSVP to be considered, we''ll work with Captain Chris on approvals. Due to expected demand, not all RSVPs will be honored, but we''ll do our best.

Time: TBA. This is a request, not a confirmed spot — organizers will follow up if your RSVP is approved.', ARRAY['https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-27']::text[], now()),
  ('behavior-adaptation-strategies-for-language-models-in-high-sensitivity-and-vulne@aiweek.boston', 'Behavior adaptation strategies for language models in high sensitivity and vulnerable-user contexts', 'https://aiweek.boston/schedule/behavior-adaptation-strategies-for-language-models-in-high-sensitivity-and-vulne', 'https://aiweek.boston/schedule/behavior-adaptation-strategies-for-language-models-in-high-sensitivity-and-vulne', FALSE, '2026-09-27T16:30:00-04:00'::timestamptz, '2026-09-27T18:00:00-04:00'::timestamptz, 'The Foundry', 'Cambridge, Roger''s st Cambridge ma 02141', 'Cambridge', 'Meetup', 'Maithri Metaverse/CanopyCare Academy', '[{"name":"Joyeeta Mitra Mukherjee","bio":null},{"name":"Padmaja Suren","bio":null}]'::jsonb, 'Behavior adaptation strategies for language models in high sensitivity and vulnerable-user contexts', 'This meetup is designed as a host-led, structured panel conversation rather than a sequence of presentations. The hosts will introduce each topic, pose questions and scenarios, and guide the panelists through different perspectives, trade-offs, and practical experiences. The goal is an open technical discussion where ideas can be compared, challenged, and developed through conversation.

As language models become more capable and are increasingly deployed in high-sensitivity and vulnerable-user contexts, we will focus on a central question: How do we adapt these systems to different users and situations without weakening the safeguards they depend on?

The hosts will guide the conversation through four discussion areas:

Boundary Safeguards: Where should behavioral and safety boundaries be drawn? How should teams enforce and monitor them when models operate in high-sensitivity and vulnerable-user contexts?

Experimental Rigor: What does responsible experimentation look like? The panel will discuss A/B testing, controlled experiments, and staged deployments as ways to evaluate adaptations while detecting unintended behaviors and risks.

Adaptation Playbooks: How should models be adapted for different users, workflows, and contexts while preserving essential safeguards? Panelists will compare approaches involving prompting, model adaptation, and application-level controls—and discuss where each approach works or breaks down.

Measuring Success: What should teams measure beyond accuracy? The conversation will examine safety, fairness, robustness, user outcomes, and unintended behavior, including how these measures influence production decisions.

Throughout the meetup, the hosts will use these themes as a structure for the conversation rather than a fixed agenda. Panelists will be encouraged to compare approaches, surface disagreements, share practical lessons, and explore the tensions between adaptability and safeguards.', ARRAY['https://aiweek.boston/schedule/behavior-adaptation-strategies-for-language-models-in-high-sensitivity-and-vulne']::text[], now()),
  ('bdmt-global-innovator-summit-2026@aiweek.boston', 'BDMT Global Innovator Summit — Day 1 (Mon)', 'https://aiweek.boston/schedule/bdmt-global-innovator-summit-2026', 'https://bdmtglobal.com/bdmt-global-innovator-summit-2026/', TRUE, '2026-09-28T08:00:00-04:00'::timestamptz, '2026-09-28T18:00:00-04:00'::timestamptz, 'Hynes Convention Center', '900 Boylston Street, Boston, MA', 'Boston', 'Conference', 'BDMT Global', '[]'::jsonb, 'BDMT Global Innovator Summit — Day 1 (Mon)', 'The BDMT Global Innovator Summit 2026 brings together cutting-edge innovators across industries with U.S. and global ecosystem leaders to identify collaboration opportunities and mutually drive growth in the U.S. and other new markets. Unlike massive trade shows where you can easily get lost in the noise, this summit prioritizes quality over quantity, offering a curated environment for meaningful connections and measurable outcomes. Many innovators have a core AI-driven solution, and virtually all are applying AI in some way.', ARRAY['https://aiweek.boston/schedule/bdmt-global-innovator-summit-2026']::text[], now()),
  ('conv2x-2026@aiweek.boston', 'ConV2X', 'https://aiweek.boston/schedule/conv2x-2026', 'https://aiweek.boston/schedule/conv2x-2026', FALSE, '2026-09-28T09:00:00-04:00'::timestamptz, '2026-09-28T17:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Conference', 'Community-hosted', '[]'::jsonb, 'ConV2X', 'ConV2X brings together the connected-vehicle and V2X community for technical sessions, demos, and networking. Full agenda, dates, and venue details TBA.', ARRAY['https://aiweek.boston/schedule/conv2x-2026']::text[], now()),
  ('gai-world-2026@aiweek.boston', 'GAI World 2026 — Day 1', 'https://aiweek.boston/schedule/gai-world-2026', 'https://www.gaiworld.com/buy-passes', TRUE, '2026-09-28T09:00:00-04:00'::timestamptz, '2026-09-28T17:00:00-04:00'::timestamptz, 'Hynes Convention Center', '900 Boylston St, Boston, MA', 'Boston', 'Conference', 'GAI Insights', '[]'::jsonb, 'GAI World 2026 — Day 1', 'GAI World 2026 — three days of enterprise generative AI content from GAI Insights at Hynes Convention Center.', ARRAY['https://aiweek.boston/schedule/gai-world-2026']::text[], now()),
  ('introducing-motivation-intelligence-signal-to-power-better-ai-hosted-by-the-scie@aiweek.boston', 'Introducing Motivation Intelligence Signal to Power Better AI, hosted by the science team at AgileBrain', 'https://aiweek.boston/schedule/introducing-motivation-intelligence-signal-to-power-better-ai-hosted-by-the-scie', 'https://agilebrain.com/events/bostonai-week-2026/', TRUE, '2026-09-28T09:00:00-04:00'::timestamptz, '2026-09-28T10:30:00-04:00'::timestamptz, 'Millennium Tower Boston, Club Lounge Theatre', '1 Franklin Street, Club Lounge, Boston, MA 02110', 'Boston', 'Talk', 'AgileBrain', '[{"name":"Dr. JD Pincus, Chief Innovation Officer, AgileBrain","bio":null},{"name":"Dr. Bill Nolen, Chief Scientist, AgileBrain","bio":null},{"name":"Jamie Thompson, Chief AI Officer, AgileBrain","bio":null}]'::jsonb, 'Introducing Motivation Intelligence Signal to Power Better AI, hosted by the science team at AgileBrain', '"The model can accurately predict human behavior based on scale, but it does not possess an internal, causal model of human intent … or motivation. It maps correlation, not the human ‘why’” Dario Amodei, Anthropic

Leading AI thinkers have consistently identified a critical gap: AI lacks a systematic and scalable understanding of human motivation. Google''s Demis Hassabis writes, "AI lacks a ''world model'' of human psychology. It knows what a human is likely to do next, but not why they feel motivated to do it." AgileBrain Motivation Intelligence fills that gap.

Join Dr. JD Pincus, Chief Innovation Officer, and Jamie Thompson, Chief AI Officer, to explore how AgileBrain Motivation Intelligence delivers the “why” behind human behavior and enables more powerful AI prediction. In this interactive session you''ll experience first-hand how neuroscience-based AgileBrain Exercises capture human motivational signal and how the AgileBrain Framework interprets those signals to provides that missing world model at scale to inform more genuine, personalized and powerful AI outputs.

Topics to be covered in the session include:

• The 12 emotional needs that motivate human behavior

• The limitation of AI models predicting at scale

• The challenge of capturing motivation signal using alternate modalities

• The power of images to capture motivation signal

• How motivation signal delivers more powerful AI prediction

• The emerging power of J-Space and AI memory

Participants will leave with:

• A better understanding of human motivation and behavior

• Their own personal AgileBrain results

• Insights into how human motivation signal can enhance their work

• A signed copy of JD’s book, The Emotionally Agile Brain: Mastering the 12 Emotional Needs that Drive Us. (in-person attendees only)

Event Details

Date: Monday, September 28, 2026

Time: 9:00 am - 10:15 am (Eastern Time)

Type: In-person and online

Location: Financial District, downtown Boston. The event address will be provided upon acceptance of your registration.

If you are unable to attend in-person or we reach maximum capacity (seating capacity: 30), we encourage you to join us via Zoom link, which will be provided upon acceptance of your registration.

The event will be recorded for future viewing and marketing purposes.

About AgileBrain

AgileBrain is a Boston-based firm focused on the understanding of human motivation. The AgileBrain Framework integrates 100+ psychological theories into one comprehensive and comprehensible model of human motivation. It is the subject of 18 peer-reviewed articles, covering the range of human experience from wellbeing to neurodiversity, employee engagement, leadership and consumer behavior. AgileBrain has been extensively validated in multiple, large-scale studies, showing significantly greater predictive power than traditional measurement approaches. AgileBrain solutions are in-use globally, supporting leadership development, student wellbeing, veterans in transition, at-risk youth and consumer marketers.

AI predicts what people do. AgileBrain knows the why.', ARRAY['https://aiweek.boston/schedule/introducing-motivation-intelligence-signal-to-power-better-ai-hosted-by-the-scie']::text[], now()),
  ('the-trust-layer-for-ai-operations@aiweek.boston', 'The Trust Layer for AI Operations', 'https://aiweek.boston/schedule/the-trust-layer-for-ai-operations', 'https://luma.com/1c2q2noy', TRUE, '2026-09-28T12:00:00-04:00'::timestamptz, '2026-09-28T14:00:00-04:00'::timestamptz, 'Alexander Technology Group', '260 Franklin St Ste 410, Boston, MA 02110', 'Boston', 'Panel', 'Ebryx, LLC', '[{"name":"Ahrar Naqvi, CEO of Ebryx","bio":null},{"name":"Harold Byun, CEO of BlueRock","bio":null},{"name":"Tanay Wakhare, CEO of Prompt Inversion","bio":null}]'::jsonb, 'The Trust Layer for AI Operations', 'Agentic AI can transform how organizations serve customers, operate, and grow but only when it is trusted with meaningful work. Attacks, unsafe autonomy, and unpredictable behavior can undermine that trust, slowing adoption and limiting AI to low-risk experiments.

This talk explores the trust layer for AI operations: the architectural and operational foundations required to move agentic AI from promising pilots to scalable, business-critical deployment. It will show how Zero Trust thinking and emerging AI-security and SecOps practices can make trust a competitive advantage for both AI builders and AI adopters.', ARRAY['https://aiweek.boston/schedule/the-trust-layer-for-ai-operations']::text[], now()),
  ('boat-rides-boston-harbor-captain-chris-2026-09-28@aiweek.boston', 'Boat Rides of Boston Harbor with Captain Chris', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-28', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-28', FALSE, '2026-09-28T12:00:00-04:00'::timestamptz, '2026-09-28T13:00:00-04:00'::timestamptz, 'Fan Pier', 'Fan Pier, Boston, MA', 'Boston', 'Meetup', 'Boston AI Week', '[]'::jsonb, 'Boat Rides of Boston Harbor with Captain Chris', 'Join Captain Chris for a boat ride on Boston Harbor, offered every day of Boston AI Week''s core week (September 24 – October 2). Very limited availability. RSVP to be considered, we''ll work with Captain Chris on approvals. Due to expected demand, not all RSVPs will be honored, but we''ll do our best.

Time: TBA. This is a request, not a confirmed spot — organizers will follow up if your RSVP is approved.', ARRAY['https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-28']::text[], now()),
  ('ai-governance-the-difference-between-a-pilot-and-a-successful-rollout@aiweek.boston', 'AI Governance: The Difference Between a Pilot and a Successful Rollout', 'https://aiweek.boston/schedule/ai-governance-the-difference-between-a-pilot-and-a-successful-rollout', 'https://aiweek.boston/schedule/ai-governance-the-difference-between-a-pilot-and-a-successful-rollout', FALSE, '2026-09-28T13:30:00-04:00'::timestamptz, '2026-09-28T14:30:00-04:00'::timestamptz, 'what ever venue is available at AI week', '39985 LAS PALMAS CT FREMONT, CA 94539', NULL, 'Talk', 'Secuvy, Inc.', '[{"name":"Mark Sutera, Mike Taylor - Secuvy","bio":null}]'::jsonb, 'AI Governance: The Difference Between a Pilot and a Successful Rollout', 'Most enterprise AI initiatives don''t fail in the lab — they fail in production, when nobody can say with confidence what data trained the model, who has access to it, or what happens when it gets something wrong.

A pilot only has to work once, in a controlled environment, in front of a friendly audience. A rollout has to work every time, at scale, under regulatory scrutiny, with real customer data flowing through it. Governance is what closes that gap: it''s the difference between a demo that impressed the board and a system the board is willing to bet the company on.

Without it, most AI programs stall at the same point — legal won''t sign off, security can''t trace the data lineage, and the pilot quietly gets shelved. With it, the questions that normally kill a rollout get answered before they''re ever asked: What data trained this? Who''s accountable if it''s wrong? Can we prove that to a regulator?', ARRAY['https://aiweek.boston/schedule/ai-governance-the-difference-between-a-pilot-and-a-successful-rollout']::text[], now()),
  ('ai-in-oncology-from-data-to-better-patient-outcomes@aiweek.boston', 'AI in Oncology: From Data to Better Patient Outcomes', 'https://aiweek.boston/schedule/ai-in-oncology-from-data-to-better-patient-outcomes', 'https://www.concertai.com/boston-ai-week-ai-in-oncology', TRUE, '2026-09-28T15:00:00-04:00'::timestamptz, '2026-09-28T17:00:00-04:00'::timestamptz, '225 Franklin Street | Oxford Properties Group | Boston, MA 02110', '225 Franklin Street, Boston, MA 02110', 'Boston', 'Panel', 'ConcertAI', '[]'::jsonb, 'AI in Oncology: From Data to Better Patient Outcomes', 'Join ConcertAI for an engaging panel discussion on the role of AI in advancing oncology. Explore how trusted data and AI-powered insights are helping researchers and clinicians accelerate innovation, improve decision-making, and drive better patient outcomes. Stay for networking with leaders from healthcare, life sciences, and the AI community.', ARRAY['https://aiweek.boston/schedule/ai-in-oncology-from-data-to-better-patient-outcomes']::text[], now()),
  ('show-tell-meet-the-real-small-business-owners-using-ai@aiweek.boston', 'Show & Tell: Meet the Real Small Business Owners Using AI', 'https://aiweek.boston/schedule/show-tell-meet-the-real-small-business-owners-using-ai', 'https://luma.com/launchby-px5r', TRUE, '2026-09-28T15:00:00-04:00'::timestamptz, '2026-09-28T17:30:00-04:00'::timestamptz, 'Boston Chamber of Commerce', '265 Franklin Street, Suite 1701, Boston, MA 02110', 'Boston', 'Panel', 'Launch by Lunch', '[{"name":"Juan Carlos (JC) Morales","bio":null},{"name":"Simone Bernstein","bio":null},{"name":"John Yuen Jr.","bio":null}]'::jsonb, 'Show & Tell: Meet the Real Small Business Owners Using AI', 'You''ve heard AI is going to change everything. What you probably haven''t seen is someone who runs a business like yours actually using it, on an ordinary Monday, to get through the to-do list.

That''s what this is.

We''re bringing together four Greater Boston small business owners, real people we''ve worked with, to tell the real non-technical story of how AI has changed their business. Hear from…

A Doggie Daycare owner who automated her vaccination workflow

→ Time saved: 8 hours/week

The CEO of a financial firm who builds decks and graphics in seconds using Claude Design

→ Time saved: 20 hours/week

The founder of a wellness community who now co-runs it with her AI Chief of Staff

→ Time saved: 12 hours/week

And the CEO of a small life sciences company who built an internal inventory system

→ Time saved: 20 hours/week

And they’re not just going to tell you about it. They’ll show you live.

We''ll put their actual automations up on the screen and show you how the work gets done.

Our hope is that these use cases inspire you to get started and dive into AI.

After the panel, join us for light bites and good conversation, and meet the people leading the AI transformation for small businesses. In our experience, that''s where the real change happens.

And because we know time and money are the two things small businesses never have enough of, we''ll share how you can access up to $15,000 a year in free AI training through the Massachusetts Commonwealth Corporation, so cost is one less thing standing between you and getting started.

Come see what''s possible for your business.

Hosted by Launch by Lunch in collaboration with the Greater Boston Chamber of Commerce and Bank of America.', ARRAY['https://aiweek.boston/schedule/show-tell-meet-the-real-small-business-owners-using-ai']::text[], now()),
  ('demos-drinks-where-ai-meets-human-behavior-research@aiweek.boston', 'Demos & Drinks: Where AI Meets Human Behavior Research', 'https://aiweek.boston/schedule/demos-drinks-where-ai-meets-human-behavior-research', 'https://aiweek.boston/schedule/demos-drinks-where-ai-meets-human-behavior-research', FALSE, '2026-09-28T16:00:00-04:00'::timestamptz, '2026-09-28T19:00:00-04:00'::timestamptz, 'iMotions - North American Headquarter', '141 Tremont St. 8th Floor Boston', 'Boston', 'Demo Night', 'iMotions', '[]'::jsonb, 'Demos & Drinks: Where AI Meets Human Behavior Research', 'What happens when artificial intelligence meets human behavior?

Join iMotions for an evening of live demos, drinks, and conversation during Boston AI Week, exploring how AI is changing the way we understand attention, emotion, engagement, and human response.

Get hands-on with the technology and see how iMotions uses AI across human behavior research, from facial expression analysis and webcam-based eye tracking to predictive AI, automated analysis, and more.

Our team will be on hand to demo the technology, answer questions, and talk about where AI can enhance behavioral research today, and where it might take us next.

Whether you work in AI, research, consumer insights, UX, academia, or are simply curious about how technology can help us better understand people, come by, grab a drink, and see it in action.

Expect live demos. Interesting conversations. Drinks. And, of course, plenty of AI.', ARRAY['https://aiweek.boston/schedule/demos-drinks-where-ai-meets-human-behavior-research']::text[], now()),
  ('maven-agi-happy-hour@aiweek.boston', 'Official Boston AI Week Happy Hour: Maven AGI | Boston AI Week | Networking Happy Hour', 'https://aiweek.boston/schedule/maven-agi-happy-hour', 'https://luma.com/5rfrkleg', TRUE, '2026-09-28T17:30:00-04:00'::timestamptz, '2026-09-28T20:30:00-04:00'::timestamptz, 'Venue location will be disclosed to confirmed guests.', 'Boston, MA', 'Boston', 'Meetup', 'Maven AGI', '[]'::jsonb, 'Official Boston AI Week Happy Hour: Maven AGI | Boston AI Week | Networking Happy Hour', 'Maven AGI will host an open invitation happy hour during Boston AI Week 2026, the region''s flagship AI festival running September 16 – October 28, with Core Festival Week from September 24 – October 2. In keeping with this year''s theme, "AI in Business and in Life," the event is a low-key, drop-in gathering for anyone attending the festival — founders, operators, researchers, students, and the simply curious — to grab a drink, unwind, and talk shop with the Maven AGI team and the broader Boston AI community. It''s invite-required to keep the room manageable and the guest list intentional, but the invite itself is easy to get: anyone attending Boston AI Week who wants to come is welcome to ask.

Limited to 100 attendees.', ARRAY['https://aiweek.boston/schedule/maven-agi-happy-hour']::text[], now()),
  ('when-ai-gets-physical-navigating-the-real-world-risks-and-rewards@aiweek.boston', 'When AI Gets Physical: Navigating the Real-World Risks and Rewards', 'https://aiweek.boston/schedule/when-ai-gets-physical-navigating-the-real-world-risks-and-rewards', 'https://gtlawinfo.com/s/2095e73c69955e1379f095d92e2319602894ef2c/h=ff01117daebe318b9712d4cb6746ac1337a007a1', TRUE, '2026-09-28T18:00:00-04:00'::timestamptz, '2026-09-28T21:00:00-04:00'::timestamptz, 'Matria at the InterContinental', '510 Atlantic Ave Boston, MA 02210', 'Boston', 'Panel', 'Greenberg Traurig, LLP', '[]'::jsonb, 'When AI Gets Physical: Navigating the Real-World Risks and Rewards', 'Greenberg Traurig is pleased to present the second annual An Evening with Greenberg Traurig. This year''s featured panel, "When AI Gets Physical: Navigating the Real-World Risks and Rewards," will examine the growing impact of AI in real-world environments and the legal, business, and operational considerations shaping its future.

Continue the conversation after the panel during a networking reception with fellow professionals and industry peers.', ARRAY['https://aiweek.boston/schedule/when-ai-gets-physical-navigating-the-real-world-risks-and-rewards']::text[], now()),
  ('boston-generative-ai-meetup-2026@aiweek.boston', 'Boston Generative AI Meetup at Boston AI Week 2026: AI in Business and in Life', 'https://aiweek.boston/schedule/boston-generative-ai-meetup-2026', 'https://www.meetup.com/boston-generative-ai-meetup/events/316068305/', TRUE, '2026-09-28T18:00:00-04:00'::timestamptz, '2026-09-28T21:00:00-04:00'::timestamptz, 'Laugh Boston (in the Westin Boston Seaport)', '425 Summer St, Boston, MA 02210', 'Boston', 'Meetup', 'Boston Generative AI Meetup', '[{"name":"Chip Hazard","bio":"Co-Founder & General Partner at Flybridge; an experienced venture investor in consequential technology companies."},{"name":"Murph Vandervelde","bio":"Chief of Staff at Blitzy, which is building an autonomous software development platform."},{"name":"John Huehn","bio":"Chief of Pega Launchpad, helping shape how the next generation of AI-powered software gets built and scaled."},{"name":"Shira Center","bio":"Vice President for Innovation and Strategic Initiatives at Boston Globe Media; former Boston Globe political editor leading enterprise AI adoption across the company."},{"name":"Tanya Sinha","bio":"Senior Product Manager at Starburst."},{"name":"Sam Tremlett","bio":"Director of Product Management at Pega; special tech talk and live demo of Launchpad.io."},{"name":"Drew Piekarski","bio":"Head of Platform Product Management at Pega; special tech talk and live demo of Launchpad.io."},{"name":"Jenn Azar","bio":"CEO of Stellix; introduces Stella, Stellix''s Boston Dynamics Spot robot, demonstrating physical AI and robotics in real-world industrial applications."}]'::jsonb, 'Boston Generative AI Meetup at Boston AI Week 2026: AI in Business and in Life', 'Join us for a special Boston AI Week edition of the Boston Generative AI Meetup exploring the festival''s 2026 theme: AI in Business and in Life.

Artificial intelligence is rapidly moving beyond experimentation and into everyday reality. It is changing how companies operate, how products are built, how people work, and how decisions are made. It is also reshaping how we learn, create, communicate, and live.

Where is AI creating measurable value today? What remains mostly hype? What happens as AI agents and increasingly capable systems become part of our businesses and our daily lives? And what should leaders, builders, investors, and individuals be thinking about now?

We''ll bring together founders, executives, investors, technologists, researchers, students, and business leaders for an evening examining AI from both sides of the equation: what it means for business and what it means for people.

Whether you are building AI, deploying it within an organization, investing in it, studying it, using it every day, or simply trying to understand what comes next, this event is an opportunity to learn, exchange ideas, and make meaningful connections with one of the world''s largest in-person AI communities during Boston AI Week.

Featured Panel: AI in Business and in Life — Hear from leading investors, founders, executives, technologists, and AI practitioners during a wide-ranging conversation about where AI is creating real value, how it is changing organizations and people''s lives, and what may come next.

Special Tech Talk & Live Demo: Sam Tremlett and Drew Piekarski, Pega — They''ll show how Launchpad.io helps teams move from an idea to an enterprise-ready AI application, using generative AI to design workflows, orchestrate work, connect agents and systems, and build the governance and reliability businesses need to put AI into production.

Special Presentation: Jenn Azar, CEO, Stellix: Meet Stella — Jenn Azar, CEO of Stellix, will introduce us to Stella, Stellix''s Boston Dynamics Spot robot, and demonstrate how physical AI and robotics are moving from experimentation into real-world industrial applications.

What to Expect: Welcome and Boston AI Community Update; Featured Panel Discussion; Audience Q&A; Networking Reception with catered food and beverages.

Admission is $22, which helps cover food, beverages, and event expenses. Space is limited.', ARRAY['https://aiweek.boston/schedule/boston-generative-ai-meetup-2026']::text[], now()),
  ('beyond-the-demo-the-human-side-of-ai@aiweek.boston', 'Beyond the Demo: The Human Side of AI', 'https://aiweek.boston/schedule/beyond-the-demo-the-human-side-of-ai', 'https://curevoz.com/', TRUE, '2026-09-28T18:30:00-04:00'::timestamptz, '2026-09-28T20:30:00-04:00'::timestamptz, 'Hult International Business School — Boston Campus, pending final institutional and room confirmation', '1 Education Street Cambridge, MA 02141', 'Boston', 'Panel', 'Heali by Curevoz', '[{"name":"Abishek Muralikrishna","bio":"Co-founder of Curevoz and Heali; founder perspective on turning a deeply personal family caregiving challenge into a multilingual, human-centered AI product."},{"name":"Gabriela Torres V.","bio":"Director of AI Innovation Ecosystem Development at Massachusetts Technology Collaborative; perspective on Human-AI design, responsible innovation, and building connections across Massachusetts startups, universities, investors, and industry."},{"name":"Kranthi Manchikanti","bio":"Founder of AI Runtime; practitioner perspective on moving AI beyond polished prototypes into reliable, real-world systems."},{"name":"Kara Peterson","bio":"Co-founder and CEO of Descrybe; founder perspective on responsible AI, access, trust, and building technology for high-stakes environments."},{"name":"Pat Pataranutaporn","bio":"Researcher at MIT Media Lab; research perspective on personalized AI, human flourishing, memory, and how intelligent systems may shape everyday life."}]'::jsonb, 'Beyond the Demo: The Human Side of AI', 'Artificial intelligence is advancing at an incredible pace, but behind every breakthrough is a deeply human story.

Beyond the Demo: The Human Side of AI brings together Boston AI founders, researchers, designers, and innovators to share the moments that inspired them to build, not just what they built.

Instead of product pitches or technical demos, this conversation explores the personal experiences, challenges, and questions that became companies, research labs, and new technologies.

Topics include:

• Building AI people actually trust

• Designing for real human needs

• Lessons from turning personal experiences into startups

• The responsibility of founders shaping the future of AI

Following the panel, attendees are invited to continue the conversation during an open networking session designed to connect students, researchers, founders, investors, clinicians, and members of Boston’s growing AI ecosystem.

Whether you’re building your first AI product, researching the next breakthrough, or simply curious about where AI is headed, this event is designed to spark conversations that continue long after the evening ends.', ARRAY['https://aiweek.boston/schedule/beyond-the-demo-the-human-side-of-ai']::text[], now()),
  ('women-in-ai-breakfast-gai-world-2026@aiweek.boston', 'Women in AI Breakfast at GAI World 2026', 'https://aiweek.boston/schedule/women-in-ai-breakfast-gai-world-2026', 'https://www.gaiworld.com/buy-passes', TRUE, '2026-09-29T07:30:00-04:00'::timestamptz, '2026-09-29T09:00:00-04:00'::timestamptz, 'Hynes Convention Center', '900 Boylston Street, Boston, MA 02115', 'Boston', 'Community', 'GAI Insights', '[{"name":"Sara Fraim","bio":"CEO of the Massachusetts Technology Leadership Council."},{"name":"Pam Boiros","bio":null},{"name":"Dr. Amanda Fetch","bio":"GAI Insights."},{"name":"Lucinda Linde","bio":null},{"name":"Anisha Bhasin","bio":null},{"name":"Hema Seshadri","bio":null},{"name":"Jodi Johnson","bio":null},{"name":"Christyl Lucille","bio":null},{"name":"Debbie Millin","bio":"UpperLevel Solutions."},{"name":"Beth Porter","bio":null},{"name":"Luda Kopeikina","bio":"Facilitator of the roundtables."}]'::jsonb, 'Women in AI Breakfast at GAI World 2026', 'Part of GAI World 2026 during Boston AI Week''s Core Festival Week, the Women in AI Breakfast celebrates the contributions and achievements of women in artificial intelligence and creates space to support and empower the women pushing the field forward.

The morning is built around facilitated roundtables, each led by a woman leader from the ecosystem, on topics including the people side of scaling AI adoption, proving and scaling ROI, GenAI for anomaly detection, AI contract terms, autonomous agents and security, leading talent in an evolving AI world, flexible organizational structures in the age of AI, and securing the AI we build.

Roundtable leaders include Sara Fraim (CEO, Massachusetts Technology Leadership Council), Pam Boiros, Dr. Amanda Fetch (GAI Insights), Lucinda Linde, Anisha Bhasin, Hema Seshadri, Jodi Johnson, Christyl Lucille, Debbie Millin (UpperLevel Solutions), and Beth Porter, with Luda Kopeikina facilitating and Jenny Boavista (GAI Insights) organizing.

Attendance is included with GAI World 2026 registration — secure a pass through the link below.', ARRAY['https://aiweek.boston/schedule/women-in-ai-breakfast-gai-world-2026']::text[], now()),
  ('bdmt-global-innovator-summit-2026-day-2@aiweek.boston', 'BDMT Global Innovator Summit — Day 2 (Tue)', 'https://aiweek.boston/schedule/bdmt-global-innovator-summit-2026-day-2', 'https://bdmtglobal.com/bdmt-global-innovator-summit-2026/', TRUE, '2026-09-29T08:00:00-04:00'::timestamptz, '2026-09-29T18:00:00-04:00'::timestamptz, 'Hynes Convention Center', '900 Boylston Street, Boston, MA', 'Boston', 'Conference', 'BDMT Global', '[]'::jsonb, 'BDMT Global Innovator Summit — Day 2 (Tue)', 'The BDMT Global Innovator Summit 2026 brings together cutting-edge innovators across industries with U.S. and global ecosystem leaders to identify collaboration opportunities and mutually drive growth in the U.S. and other new markets. Unlike massive trade shows where you can easily get lost in the noise, this summit prioritizes quality over quantity, offering a curated environment for meaningful connections and measurable outcomes. Many innovators have a core AI-driven solution, and virtually all are applying AI in some way.', ARRAY['https://aiweek.boston/schedule/bdmt-global-innovator-summit-2026-day-2']::text[], now()),
  ('ai-are-we-doing-this-right@aiweek.boston', 'AI: Are We Doing This Right?', 'https://aiweek.boston/schedule/ai-are-we-doing-this-right', 'https://business.nvcoc.com/events/details/breakfast-with-the-boss-ai-50046', TRUE, '2026-09-29T08:00:00-04:00'::timestamptz, '2026-09-29T09:30:00-04:00'::timestamptz, 'Devens Common Center', '31 Andrews Parkway Devens', NULL, 'Panel', 'Nashoba Valley Chamber of Commerce', '[{"name":"Ann Westerheim","bio":"President of Ekaru; AI & cybersecurity."},{"name":"Peter Berson","bio":"Marketing Consultant at Aveli by WSI; AI, marketing & business adoption."},{"name":"Tye Jordan","bio":"Cinch I.T.; AI implementation, workplace adoption & cybersecurity."}]'::jsonb, 'AI: Are We Doing This Right?', 'AI is everywhere—but what does it actually mean for your business?

Join us for a candid, practical conversation with three Nashoba Valley Chamber members and local leaders working in the AI space. We’ll cut through the hype and talk about how businesses are really using AI today—and what you should be thinking about next.

Our panel includes:

Ann Westerheim, President, Ekaru – AI & cybersecurity;

Peter Berson, Marketing Consultant, Aveli by WSI – AI, marketing & business adoption; and Tye Jordan, Cinch I.T. – AI implementation, workplace adoption & cybersecurity

We’ll explore where AI can save time and improve productivity, what employees should—and shouldn’t—be doing with AI, how to protect your business and data, and how AI is changing marketing and the way customers find you.

Whether you’re already using AI or still wondering what all the fuss is about, come with your questions and leave with practical ideas, real-world examples and a better understanding of what your business should be doing now.

Local experts. Real-world experience. Your AI questions answered.', ARRAY['https://aiweek.boston/schedule/ai-are-we-doing-this-right']::text[], now()),
  ('langsmith-roadshow-building-agents-with-agents-boston@aiweek.boston', 'LangSmith Roadshow: Building Agents with Agents - Boston', 'https://aiweek.boston/schedule/langsmith-roadshow-building-agents-with-agents-boston', 'https://events.langchain.com/LangSmithRoadshow/Boston/', TRUE, '2026-09-29T08:30:00-04:00'::timestamptz, '2026-09-29T13:00:00-04:00'::timestamptz, 'Convene One Boston Place', '201 Washington St, Boston, MA 02108', 'Boston', 'Workshop', 'LangChain', '[]'::jsonb, 'LangSmith Roadshow: Building Agents with Agents - Boston', 'We’re bringing together builders and technical leaders for a half-day focused on what it takes to build better agents in practice.

Join us for a hands-on look at how to build and improve agents, with agents.

The day will kick off with a keynote on the current state of agent development and the best practices we’re seeing from teams building in production.

We’ll then dive into two hands-on workshops:

Agent harnesses with Deep Agents: Explore the core concepts behind agent harnesses and learn how to build with Deep Agents.

Improving your agents with LangSmith Engine: Get hands-on with an agent for agent engineering that identifies where your agent is failing and helps make the fix for you.

We’ll wrap up with lunch and time to connect with fellow AI builders.

This event is designed for agent engineers, AI platform teams, and technical leaders building and operating agents in production.

Check out the full agenda below for a closer look at the sessions and content.', ARRAY['https://aiweek.boston/schedule/langsmith-roadshow-building-agents-with-agents-boston']::text[], now()),
  ('gai-world-2026-day-2@aiweek.boston', 'GAI World 2026 — Day 2', 'https://aiweek.boston/schedule/gai-world-2026-day-2', 'https://www.gaiworld.com/buy-passes', TRUE, '2026-09-29T09:00:00-04:00'::timestamptz, '2026-09-29T17:00:00-04:00'::timestamptz, 'Hynes Convention Center', NULL, NULL, 'Conference', 'GAI Insights', '[]'::jsonb, 'GAI World 2026 — Day 2', 'Details coming soon. Add this event to your calendar and check back.', ARRAY['https://aiweek.boston/schedule/gai-world-2026-day-2']::text[], now()),
  ('ai-for-the-rest-of-us-2026@aiweek.boston', 'AI for the Rest of Us: How Support Forge is Bringing Enterprise AI to Underserved SMBs', 'https://aiweek.boston/schedule/ai-for-the-rest-of-us-2026', 'https://support-forge.com/events/ai-week-boston', TRUE, '2026-09-29T09:00:00-04:00'::timestamptz, '2026-09-29T12:00:00-04:00'::timestamptz, NULL, NULL, 'Virtual', 'Meetup', 'Support Forge LLC', '[]'::jsonb, 'AI for the Rest of Us: How Support Forge is Bringing Enterprise AI to Underserved SMBs', 'Small and mid-market businesses (SMBs with $5M–$50M in revenue) represent the backbone of the American economy—yet they remain dramatically underserved when it comes to AI adoption. Enterprise companies have armies of consultants and dedicated AI teams; small startups can get by with off-the-shelf tools. But mid-market companies fall into a gap: too sophisticated for simple solutions, yet without the resources for enterprise-grade approaches.

Support Forge was built to close that gap. Founded by Perry Bailes in 2024, Support Forge brings enterprise-level AI strategy and implementation directly to SMB executives—without the enterprise price tag or timeline.

In this session, Perry will share how Support Forge is transforming the way mid-market companies approach AI: starting with the business problem, building measurable ROI, and deploying real solutions that work in production—not just proofs of concept.

Key takeaways:

- Why mid-market SMBs are uniquely underserved in the AI revolution

- How to implement AI with measurable ROI (not just hype)

- Real-world case studies from Support Forge clients

- How to get started with a free AI readiness assessment at support-forge.com', ARRAY['https://aiweek.boston/schedule/ai-for-the-rest-of-us-2026']::text[], now()),
  ('ai-meet-the-investors-breakfast@aiweek.boston', 'AI "Meet the Investors" Breakfast', 'https://aiweek.boston/schedule/ai-meet-the-investors-breakfast', 'https://luma.com/rflxqfk5', TRUE, '2026-09-29T09:00:00-04:00'::timestamptz, '2026-09-29T11:00:00-04:00'::timestamptz, 'Venture Lane', '55 Court St Floor 2, Boston, MA 02108', 'Boston', 'Meetup', 'Fidelity Private Shares, HSBC Innovation Banking, and Venture Lane', '[{"name":"Kristen Craft","bio":null},{"name":"Meeta Kapadia","bio":null}]'::jsonb, 'AI "Meet the Investors" Breakfast', 'Fidelity Private Shares, HSBC Innovation Banking, and Venture Lane are excited to gather Boston''s AI founder community. Please join us for coffee, breakfast, and networking. And we''re always looking to bring new people into the community, so feel free to share with a friend who''d like to get more plugged into the local startup and venture ecosystem!

Agenda

9-9:30 Arrivals & Networking

9:30-10 Pre-Seed & Seed Investor Panel

10-10:30 Series A & beyond Investor Panel

10:30-11 Networking & Departures

About HSBC Innovation Banking:

HSBC Innovation Banking brings HSBC’s expansive product suite and unmatched international capabilities to support startups and their VCs in the innovation ecosystem at every stage of their journey. Our mission is to provide founders and their teams with exceptional service, tailored banking and venture debt facilities, and value-add connections to our extensive global network of investors and corporate clients.

About Fidelity Private Shares:

Fidelity Private Shares is committed to supporting the startup & venture capital community. Fidelity helps founders prepare for their next round of funding with our cap table management and data room platform, events that give you access to capital, and premier support to generate, execute & store legal documents. No matter where you are in your journey - from inception to IPO - Fidelity has the expertise to support you.', ARRAY['https://aiweek.boston/schedule/ai-meet-the-investors-breakfast']::text[], now()),
  ('how-to-build-a-company-brain@aiweek.boston', 'How To Build a Company Brain', 'https://aiweek.boston/schedule/how-to-build-a-company-brain', 'https://aiweek.boston/schedule/how-to-build-a-company-brain', FALSE, '2026-09-29T11:00:00-04:00'::timestamptz, '2026-09-29T12:30:00-04:00'::timestamptz, 'TBD', NULL, NULL, 'Panel', 'Unosquare', '[{"name":"Jade Davila","bio":"Head of Design at Unosquare."},{"name":"Mark Brown","bio":"Chief Learning Officer at Unosquare."},{"name":"Eli Marshall","bio":"Lead Software Development Engineer at Unosquare."},{"name":"Matt McGuire","bio":"VP of Data & AI at Unosquare."}]'::jsonb, 'How To Build a Company Brain', 'Every company already has a brain. It is just spread across inboxes, CRM notes, shared drives, and the memory of whoever has been there the longest. The knowledge already exists. The work is connecting it.

Join Unosquare for a candid panel on designing a company brain: infrastructure that gathers an organization''s scattered knowledge and relationships into one place it can actually query, without depending on the one person who happens to remember. The idea looks different on every desk. A law firm surfaces a judge''s prior rulings in seconds instead of an afternoon. A recruiter notices when a hiring manager moves and the relationship travels with them. A private equity team pulls comparable deals to pressure-test the one in front of them. Underneath, it is the same system.

We will get into the design decisions that make or break it: separating raw source material from the refined knowledge built on top, treating relationships as records with a date, a source, and a confidence level, and governing how information earns its way to institutional truth. Promotion is a decision, not a default, and a company brain is only as trustworthy as the sources it can point back to. Along the way, we will be honest about where AI earns its place: turning search into synthesis, conversation into records, and volume into signal.

This is not a feature you switch on; it is infrastructure. Whether you are a founder deciding if the investment is worth making, an engineer weighing memory architectures, or a designer trying to make trust visible in an interface, come with questions. The best parts of this conversation will come from the room.

Format: Moderated panel with audience Q&A Hosted by: Unosquare Who should come: Founders, product and design leads, engineers, and anyone curious about what comes after the chatbot', ARRAY['https://aiweek.boston/schedule/how-to-build-a-company-brain']::text[], now()),
  ('how-legacy-industries-are-quietly-winning-with-ai@aiweek.boston', 'How Legacy Industries Are Quietly Winning with AI', 'https://aiweek.boston/schedule/how-legacy-industries-are-quietly-winning-with-ai', 'https://aiweek.boston/schedule/how-legacy-industries-are-quietly-winning-with-ai', FALSE, '2026-09-29T12:00:00-04:00'::timestamptz, '2026-09-29T13:30:00-04:00'::timestamptz, 'Venture Lane', '55 Court St Fl 2, Boston, MA 02108', 'Boston', 'Panel', 'Predien', '[]'::jsonb, 'How Legacy Industries Are Quietly Winning with AI', 'Most people picture AI living inside the tech companies. Meanwhile, warehouses, construction, transportation, and fulfillment operations run it every day. The work is physical, the teams are blue-collar, and AI is already part of how they operate.

Hear from executives and owners running established operations in industries few would associate with AI.

What we''ll get into:

- What AI actually did to their margins and competitiveness

- What they automated first and what surprised them about it

- What their teams on the floor think about it

- What they''d tell another operator who thinks AI isn''t for their business

- How does the the long-term payoff look like

Then connect with other operators and investors on what''s working where AI meets physical work. A room to compare notes with people running similar operations.

Leave with a clear picture of what AI looks like inside a physical operation and what to try first.

For operators of established businesses, investors, and anyone who thinks AI is only for tech companies.', ARRAY['https://aiweek.boston/schedule/how-legacy-industries-are-quietly-winning-with-ai']::text[], now()),
  ('boat-rides-boston-harbor-captain-chris-2026-09-29@aiweek.boston', 'Boat Rides of Boston Harbor with Captain Chris', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-29', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-29', FALSE, '2026-09-29T12:00:00-04:00'::timestamptz, '2026-09-29T13:00:00-04:00'::timestamptz, 'Fan Pier', 'Fan Pier, Boston, MA', 'Boston', 'Meetup', 'Boston AI Week', '[]'::jsonb, 'Boat Rides of Boston Harbor with Captain Chris', 'Join Captain Chris for a boat ride on Boston Harbor, offered every day of Boston AI Week''s core week (September 24 – October 2). Very limited availability. RSVP to be considered, we''ll work with Captain Chris on approvals. Due to expected demand, not all RSVPs will be honored, but we''ll do our best.

Time: TBA. This is a request, not a confirmed spot — organizers will follow up if your RSVP is approved.', ARRAY['https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-29']::text[], now()),
  ('build-your-first-ai-executive-assistant-in-base44-in-15-minutes-or-less@aiweek.boston', 'Build Your First AI Executive Assistant in Base44 in 15 Minutes or Less!', 'https://aiweek.boston/schedule/build-your-first-ai-executive-assistant-in-base44-in-15-minutes-or-less', 'https://us06web.zoom.us/meeting/register/PBPaURM8SDSBl5in5dU0AA', TRUE, '2026-09-29T12:00:00-04:00'::timestamptz, '2026-09-29T13:15:00-04:00'::timestamptz, 'Online via Zoom', 'To be announced, Boston, MA', 'Virtual', 'Workshop', 'Renewable Renegades', '[{"name":"D. Beth Griffith","bio":"Founder of Renewable Renegades and RenegAIDE Collective; co-founder and President of NEPAI, Northeast Professionals in Artificial Intelligence; Executive Director of Gigs Uplift Mass. She has trained more than 687 business owners and workers and mentored over 1,400 people, teaching AI to total beginners in plain language."}]'::jsonb, 'Build Your First AI Executive Assistant in Base44 in 15 Minutes or Less!', 'It is 9:47 PM on a Tuesday. You are still at the kitchen table answering the messages you meant to answer at 2 PM. Somewhere in that inbox is a customer who asked you for a quote three days ago. They already hired someone else.

You are not disorganized. You are not behind because you are lazy. You are one person doing the work of a five person team, and the admin is quietly eating every hour you meant to spend growing the business.

Here is what nobody tells small business owners about AI: you do not need a developer, a budget, or a computer science degree to fix this. You need one working session, and somebody who will stay on the screen with you until the thing actually runs.

That is this session.

WHAT WE BUILD, LIVE, TOGETHER

The build itself takes 15 minutes. We are giving you 75 minutes so that nobody gets left behind, nobody gets talked past, and nobody goes home with notes instead of a working tool.

We build inside Base44, a no code platform where you describe what you need in plain English and watch it get built. No coding. No demo you abandon next week. A real Digital Helper, running in your business, before you close your laptop.

Three passes:

PASS ONE. Your Base44 account, set up correctly. We walk in together, get you inside, and configure your workspace so it is ready to hold everything you build after today.

PASS TWO. Your AI Executive Assistant. The Digital Helper that handles client intake, sends the follow ups you keep forgetting, tracks your tasks, sets your reminders, and answers the same eleven questions your customers ask you every single week.

PASS THREE. Your AI phone helper. The one that picks up when you cannot, greets the caller, takes the message, captures the lead, and makes sure the seven calls you missed today never go missing again.

WHAT YOU LEAVE WITH

THE STRESS FREE BUILD GUIDE. In your hands the moment you sit down, not emailed to you a week later. Every click, every prompt, every screen, written in plain language so you can follow along without panic and rebuild the whole thing on your own next month. Print it. Mark it up. It is yours to keep.

A live Base44 account, configured and ready for everything you build next.

A working AI Executive Assistant, running in your business tonight.

An AI phone helper set up to catch what you miss.

The exact prompts we use on screen, so you are never staring at a blank box wondering what to type.

WHO THIS IS FOR

Small business owners, solopreneurs, contractors, consultants, shop and salon owners, nonprofit leaders, and gig workers who are doing it all themselves and are tired. Total beginners are the entire point of this room. If you have never built anything with AI in your life, you are exactly who we designed this for.

If you already build with AI, come anyway. The phone helper build alone is worth the seat.

DATE, TIME, AND FORMAT

Tuesday, September 29, 2026

12:00 PM to 1:15 PM Eastern

Hybrid: join us in person in Massachusetts, or online from wherever you are. The in person location is TBD and will be shared directly with registrants once confirmed.

Bring a laptop. Not a phone, not a tablet. You are building today, not watching.

Bring one real problem from your business. You will leave with it solved.', ARRAY['https://aiweek.boston/schedule/build-your-first-ai-executive-assistant-in-base44-in-15-minutes-or-less']::text[], now()),
  ('training-custom-ai-models-via-fine-tuning@aiweek.boston', 'Training Custom AI Models via Fine-Tuning', 'https://aiweek.boston/schedule/training-custom-ai-models-via-fine-tuning', 'https://aiweek.boston/schedule/training-custom-ai-models-via-fine-tuning', FALSE, '2026-09-29T13:00:00-04:00'::timestamptz, '2026-09-29T16:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Workshop', 'Community-hosted', '[{"name":"Jesse Waites","bio":null}]'::jsonb, 'Training Custom AI Models via Fine-Tuning', 'This talk is a practical introduction to creating a custom AI model through fine-tuning. Rather than training a model from scratch, I will show how you can start with an existing open-weight model and specialize it to behave in a specific, repeatable way. The focus will be on the complete workflow: choosing a base model, defining the behavior you want to change, creating synthetic training data, establishing evaluation benchmarks, and fine-tuning with techniques such as LoRA and QLoRA.

I will also cover the parts of the process that are easy to overlook, including quantization, controlling variables during evaluation, checking for catastrophic forgetting, and measuring whether the fine-tuned model actually improved instead of simply assuming that it did. The goal is to demystify fine-tuning and show, step by step, how an open model can be turned into a specialized model that can be evaluated, deployed, and used in a real application.', ARRAY['https://aiweek.boston/schedule/training-custom-ai-models-via-fine-tuning']::text[], now()),
  ('ma-workforce-ai-career-fair-2026@aiweek.boston', 'The AI in Massachusetts Workforce Development and Career Fair', 'https://aiweek.boston/schedule/ma-workforce-ai-career-fair-2026', 'https://meetu.ps/e/PJc0v/p69G2/i', TRUE, '2026-09-29T13:00:00-04:00'::timestamptz, '2026-09-29T17:00:00-04:00'::timestamptz, 'Metcalf Hall Grand Ballroom, George Sherman Union, Boston University', '775 Commonwealth Avenue, Boston, MA 02215', 'Boston', 'Career', 'Boston AI Week and Questrom School of Business at Boston University', '[]'::jsonb, 'The AI in Massachusetts Workforce Development and Career Fair', 'The AI in Massachusetts Workforce Development and Career Fair is the largest AI-focused hiring and workforce event in New England, and the anchor career program of Boston AI Week 2026. It brings together the Commonwealth''s AI employers — from Fortune 500s and national labs to growth-stage startups and robotics companies — with the people who will build, deploy, and govern AI across Massachusetts.

Co-hosted by Boston AI Week and the Questrom School of Business at Boston University, the fair takes over Metcalf Hall in BU''s George Sherman Union for an afternoon of recruiting, workforce programming, and community. Employers staff booths on the main floor; job seekers move between conversations, on-the-spot resume reviews, and short-form talks from hiring managers and workforce leaders.

Who it''s for:

• Job seekers and career changers moving into AI, ML, data, and applied research roles

• Students and recent graduates from every Massachusetts college and university

• Engineers, designers, PMs, GTM, operations, and policy professionals exploring AI-native teams

• Employers hiring across enterprise AI, robotics, biotech + AI, defense, climate, and public sector

• Workforce agencies, training providers, and community organizations building AI talent pipelines

What to expect on the floor:

• Employer booths from leading Massachusetts AI companies and research organizations

• Lightning talks from hiring managers on what they actually look for in AI-era candidates

• A workforce panel on how Massachusetts is retraining and upskilling for AI

• On-site conversations, portfolio reviews, and interview slots with participating employers

• A dedicated area for students and early-career attendees, hosted with Questrom

Date: Tuesday, September 29, 2026 · 1–5 PM ET

Venue: Metcalf Hall Grand Ballroom, George Sherman Union, Boston University — 775 Commonwealth Avenue, 2nd Floor, Boston, MA

Admission is free for job seekers and students with advance registration. Employers and workforce partners can request a booth or sponsorship through the Boston AI Week team.', ARRAY['https://aiweek.boston/schedule/ma-workforce-ai-career-fair-2026']::text[], now()),
  ('wentworth-ai-test-kitchen-2026@aiweek.boston', 'Can You Trust Your AI? The Wentworth AI Test Kitchen', 'https://aiweek.boston/schedule/wentworth-ai-test-kitchen-2026', 'https://docs.google.com/forms/d/e/1FAIpQLScDfyk_SxlBTnyAR0hV0cFAn-fgGFBD1KBTMqugRudJm034yw/viewform', TRUE, '2026-09-29T13:00:00-04:00'::timestamptz, '2026-09-29T16:00:00-04:00'::timestamptz, 'CEIS Foyer, Wentworth Institute of Technology', '550 Huntington Ave, Boston, MA 02115', 'Boston', 'Workshop', 'Wentworth School of Computing and Data Science (Wentworth Institute of Technology)', '[{"name":"Leon Deligiannidis","bio":"Wentworth faculty featured in the AI Test Kitchen."},{"name":"Yetunde Longe-Folajimi","bio":"Wentworth faculty featured in the AI Test Kitchen."},{"name":"Salem Othman","bio":"Wentworth faculty featured in the AI Test Kitchen."}]'::jsonb, 'Can You Trust Your AI? The Wentworth AI Test Kitchen', 'What evidence should you have before you trust an AI system? The Wentworth School of Computing and Data Science invites Boston AI Week attendees to find out in the AI Test Kitchen: a hands-on experience where you see real Wentworth-built AI systems in action, test them, inspect the evidence behind their behavior, and discuss how they can be improved.

Rotate in small groups through three live demonstration stations:

• Value Horizon — an LLM-powered framework for mapping product evolution; examine the inputs, outputs, and rationale behind an insight

• SkillGen — real-time adaptive programming practice with instructor-facing analytics; see how learning support and instructor oversight interact

• GABench — an interactive evaluation system for closed-loop agentic behavior; inspect an agent''s actions after the fact through telemetry and replay

The afternoon also features Quantum Futures at Wentworth, an accessible mini-tutorial on qubits, superposition, measurement, and noise, and where AI and quantum computing may intersect next — followed by the panel ''AI and the Next Computing Frontier,'' a School innovation showcase, and networking with faculty, students, alumni, and industry partners.

Featuring Wentworth faculty Leon Deligiannidis, Yetunde Longe-Folajimi, and Salem Othman, with research co-op and senior-project students. Who should attend: AI practitioners, founders, and researchers; employers and co-op partners; prospective students and families; Wentworth students, alumni, faculty, and staff; and the broader Massachusetts AI community.

Advance RSVP required; capacity is limited and a waitlist will be used.', ARRAY['https://aiweek.boston/schedule/wentworth-ai-test-kitchen-2026']::text[], now()),
  ('manufacturing-ai-siop-to-shop-floor@aiweek.boston', 'Manufacturing AI: SIOP to Shop Floor', 'https://aiweek.boston/schedule/manufacturing-ai-siop-to-shop-floor', 'https://aiweek.boston/schedule/manufacturing-ai-siop-to-shop-floor', FALSE, '2026-09-29T16:30:00-04:00'::timestamptz, '2026-09-29T18:15:00-04:00'::timestamptz, 'Findability Sciences Office at Workbar Burlington', '100 Summit Dr, Ste 917, Burlington, MA 01880', 'Burlington', 'Talk', 'Findability Sciences', '[{"name":"Sagar Mahurkar","bio":"Vice President at Findability Sciences; TEDx speaker, IEEE award-winning researcher, and holder of 5 US patents who has worked on more than 60 AI projects across Findability Sciences'' 250+ deployments."}]'::jsonb, 'Manufacturing AI: SIOP to Shop Floor', 'Excess inventory and stockouts frequently occur in the same quarter, on the same SKUs. The cause is rarely demand volatility. It is the distance between the commercial forecast and an achievable supply plan.

This hour addresses both halves of that gap. On the planning side, SIOP: statistical demand forecasting, new SKU and long-tail items without sales history, distributor and channel inventory visibility, and the conditions under which the monthly consensus cycle becomes a calculation rather than a negotiation. On the execution side, the Factory suite: quality prediction, anomaly detection, and maintenance planning on the plant floor, integrated with the plan rather than operated in isolation.

Underneath both sits the same architecture. ICUPP: Infrastructure, Collection, Unification, Processing, and Presentation of Data, a framework recognized by IDC, Gartner, and Google. Findability Sciences has run this in production with manufacturers like Daikin, Mitsubishi, and Bourns across distributor forecasting and new SKU launches. The operating principle throughout is that the system recommends, the planner or operator acts, and the manager reviews.

For supply chain and demand planning leaders, S&OP owners, plant and operations managers, and the finance partners who sit inside the cycle.

A talk by Sagar Mahurkar, Vice President at Findability Sciences, followed by networking, food, and beverages. Sagar is a TEDx speaker and IEEE award-winning researcher who holds 5 US patents and has worked on more than 60 AI projects himself, drawing on Findability Sciences'' 250+ deployments as a Fortune America''s Most Innovative Company. During the event you''ll also get to meet senior executives from Findability Sciences and mingle with AI practitioners.

Doors 4:00pm. Talk 4:30 to 5:30pm. Food, beverages, and networking until 6:15pm.', ARRAY['https://aiweek.boston/schedule/manufacturing-ai-siop-to-shop-floor']::text[], now()),
  ('national-security-defense-tech-demo-day-2026@aiweek.boston', 'QLab 2026 Demo Day', 'https://aiweek.boston/schedule/national-security-defense-tech-demo-day-2026', 'https://luma.com/tjv4766v', TRUE, '2026-09-29T16:30:00-04:00'::timestamptz, '2026-09-29T19:30:00-04:00'::timestamptz, 'Klarman Auditorium, Harvard Business School', '25 Harvard Way, Boston, MA 02163', 'Boston', 'Demo Night', 'QLab and HBS Foundry', '[]'::jsonb, 'QLab 2026 Demo Day', 'QLab 2026 Demo Day is the capstone of the QLab year, the afternoon the 2026 cohort presents what they have spent it building. QLab is a nonprofit defense technology accelerator founded by students from Harvard and MIT, where teams turn research into working technology, many of them building on the HBS Foundry platform.

The program opens with a surprise keynote and moves into team presentations.

The reason to come is the room. Alongside the cohort, you will find operators and technical leaders from industry, program and procurement leads from government, and investors active in dual-use and deep tech. The presentations show what each team built; the people in the room are who you want to meet.

Klarman Hall. Doors open at 4:00 PM. Space is limited.', ARRAY['https://aiweek.boston/schedule/national-security-defense-tech-demo-day-2026']::text[], now()),
  ('founders-and-funders-bos-vc-reverse-pitch@aiweek.boston', 'Founders & Funders: BOS VC Reverse Pitch', 'https://aiweek.boston/schedule/founders-and-funders-bos-vc-reverse-pitch', 'https://luma.com/fnfxbos0829', TRUE, '2026-09-29T17:00:00-04:00'::timestamptz, '2026-09-29T19:00:00-04:00'::timestamptz, 'Downtown Boston (venue shared upon approval)', '99 High St, Boston, MA 02110', 'Boston', 'Community', 'Founders & Funders', '[]'::jsonb, 'Founders & Funders: BOS VC Reverse Pitch', 'Boston VC Reverse Pitch, presented by Synergy.

You''ve pitched to investors countless times. Now the tables are turning. Hear directly from leading VCs as they break down their investment thesis, check size, the sectors they''re betting on, and what it really takes to get them to say yes — straight from the people writing the checks.

Founders & Funders puts the right founders and investors in the same room. This is their signature format: VC Reverse Pitch, where investors pitch their thesis to founders instead of the other way around.

The evening

5:00 PM — Networking

5:30 PM — VC Reverse Pitch session

6:10 PM — Founder and investor networking

7:00 PM — Event concludes

The hosts typically receive 300+ founder and investor applications per event, and only a fraction are approved. Attendance is free; approval is not guaranteed. The exact venue is shared upon approval.

Supported by Microsoft for Startups, Gnomi and Carta.', ARRAY['https://aiweek.boston/schedule/founders-and-funders-bos-vc-reverse-pitch']::text[], now()),
  ('jd-ai-building-whats-next-at-democracy-brewing@aiweek.boston', 'JD → AI: Building What''s Next at Democracy Brewing', 'https://aiweek.boston/schedule/jd-ai-building-whats-next-at-democracy-brewing', 'https://luma.com/j6uxbl9q', TRUE, '2026-09-29T17:30:00-04:00'::timestamptz, '2026-09-29T20:00:00-04:00'::timestamptz, 'Democracy Brewing', '35 Temple Place Boston, MA 02111', 'Boston', 'Workshop', 'Code & Counsel, Reframe.Lawyer', '[{"bio":null,"name":"Ben Chiriboga"},{"bio":"Founder of Code & Counsel and Head of Product at Irys Legal.","name":"Christian Brown"}]'::jsonb, 'JD → AI: Building What''s Next at Democracy Brewing', 'The future of legal careers extends far beyond traditional practice. JD → AI: Building What''s Next is a two-part experience for attorneys, law students, and legal professionals exploring opportunities in legal technology and AI.

The evening begins with a free Happy Hour & an open panel featuring legal professionals who have successfully transitioned into roles spanning legal knowledge engineering, product, implementation, and go-to-market strategy. Through candid, interactive conversations and a live demonstration, attendees will gain an inside look at how legal expertise is shaping the next generation of technology—and how to position themselves for these emerging careers.

Designed for legal professionals who have already begun exploring AI tools and are ready to move beyond introductory courses, the second half of the evening is an advanced, hands-on Builder Lab led by Code & Counsel. Rather than following a generic tutorial, attendees will begin developing a portfolio-quality project they can continue refining after the event—leaving with tangible work that demonstrates initiative, technical aptitude, and the ability to bridge legal expertise with AI-powered solutions. $75 fee (please contact meagan@codeandcounsel.ai for nonprofit and qualifying solo attorney free admission)

Hosted by Reframe.Lawyer and Code & Counsel, JD → AI: Building What''s Next combines career insight with real-world skill building, creating a space for legal professionals to connect, learn, and begin building what''s next.', ARRAY['https://aiweek.boston/schedule/jd-ai-building-whats-next-at-democracy-brewing']::text[], now()),
  ('whiskey-wine-whiteboards-september-29@aiweek.boston', 'Whiskey, Wine & Whiteboards - September 29', 'https://aiweek.boston/schedule/whiskey-wine-whiteboards-september-29', 'https://luma.com/9pd7iwj7', TRUE, '2026-09-29T17:30:00-04:00'::timestamptz, '2026-09-29T19:30:00-04:00'::timestamptz, 'Venture Lane', '55 Court St Floor 2, Boston, MA 02108', 'Boston', 'Meetup', 'Venture Lane', '[{"bio":null,"name":"Igor Belagorudsky"}]'::jsonb, 'Whiskey, Wine & Whiteboards - September 29', 'We''ve got whiskey, we''ve got wine, we''ve got CTOs to answer all your technical and nontechnical questions. And occasionally, we use a whiteboard.

This is a very unusual event structure - no fireside nonsense, no one having a preplanned conversation and then faking some Q&A. This is pure problem solving.

You''ve got startup questions, we have all the answers. Come have a drink so you''re not embarrassed to ask them and we''ll solve them on the spot or tell you where to go.', ARRAY['https://aiweek.boston/schedule/whiskey-wine-whiteboards-september-29']::text[], now()),
  ('maven-agi-vip-networking-meetup@aiweek.boston', 'Maven AGI | Boston AI Week | VIP Dinner', 'https://aiweek.boston/schedule/maven-agi-vip-networking-meetup', 'https://luma.com/852b0ufm', TRUE, '2026-09-29T17:30:00-04:00'::timestamptz, '2026-09-29T20:30:00-04:00'::timestamptz, 'Location will be disclosed to confirmed guests.', 'Boston, MA', 'Boston', 'Meetup', 'Maven AGI', '[]'::jsonb, 'Maven AGI | Boston AI Week | VIP Dinner', 'Maven AGI will host an INVITE ONLY executive-level networking, dinner, and happy hour mixer during Boston AI Week 2026, the region''s flagship AI festival running September 16 – October 28, with Core Festival Week from September 24 – October 2. Anchored in this year''s theme, "AI in Business and in Life," the event brings together CX, support, and technology executives from enterprise organizations for an evening of high-value conversation, relationship-building, and firsthand exposure to how leading companies are deploying AI agents in production today.

Boston AI Week drew 125+ events, 15,000+ attendees, and 249 participating companies in 2025, with the 2026 program aiming to double that footprint. Maven AGI is a Premier sponsor of the festival, placing this mixer inside one of the most concentrated windows of enterprise AI attention in the country. The event is designed to convert that visibility into direct, unhurried access to the people who decide how AI gets adopted inside their organizations.', ARRAY['https://aiweek.boston/schedule/maven-agi-vip-networking-meetup']::text[], now()),
  ('ai-in-action-questrom-2026@aiweek.boston', 'AI in Action: Real Use Cases Driving Business Impact', 'https://aiweek.boston/schedule/ai-in-action-questrom-2026', 'https://trusted.bu.edu/s/1759/2-bu/19/1col.aspx?sid=1759&gid=2&pgid=19672&content_id=20786', TRUE, '2026-09-29T18:00:00-04:00'::timestamptz, '2026-09-29T20:00:00-04:00'::timestamptz, 'Questrom School of Business', '595 Commonwealth Avenue, 4th Floor, Boston, MA 02215', 'Boston', 'Panel', 'BU Questrom Women in Business Alumni Council, BU Chobanian & Avedisian School of Medicine, GMS, and BU CCDS', '[]'::jsonb, 'AI in Action: Real Use Cases Driving Business Impact', 'Join us for a dynamic panel discussion exploring how artificial intelligence is driving measurable impact across industries including finance, healthcare, consulting, and STEM. Featuring senior leaders at the forefront of AI adoption, this conversation will move beyond theory to examine real-world applications and outcomes.

Panelists will share where AI has delivered the greatest value within their organizations, reflect on what surprised them throughout the implementation process, and candidly discuss initiatives that fell short and the lessons learned along the way.

This cross-industry dialogue will offer practical insights, honest reflections, and actionable takeaways for anyone interested in how AI is shaping the future of work and decision-making today.

Co-hosted by Questrom Women in Business Alumni Council, BU Chobanian & Avedisian School of Medicine, Graduate Medical Sciences, and BU Center for Computing & Data Sciences.

An invite-only networking reception to follow the panel discussion.', ARRAY['https://aiweek.boston/schedule/ai-in-action-questrom-2026']::text[], now()),
  ('ai-in-sales-selling-hasnt-changed-the-tools-have@aiweek.boston', 'AI in Sales: Selling Hasn''t Changed, the Tools Have', 'https://aiweek.boston/schedule/ai-in-sales-selling-hasnt-changed-the-tools-have', 'https://aiweek.boston/schedule/ai-in-sales-selling-hasnt-changed-the-tools-have', FALSE, '2026-09-29T18:00:00-04:00'::timestamptz, '2026-09-29T20:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Panel', 'Bantor', '[]'::jsonb, 'AI in Sales: Selling Hasn''t Changed, the Tools Have', 'Sales has changed a lot in a short time. There''s more noise than ever and AI is making more of it. Any rep can send a hundred personalized emails before lunch now. Buyers stopped reading them a while ago.

Hear from sales experts on what they automate, what they don''t, and how they still cut through.

What we''re asking them:

- What they automated and regretted

- What they''ll never hand to AI

- Whether they can tell when a rep''s outreach was written by a machine

- What the job looks like now

Then network with other sales leaders on what''s actually working in outreach right now. This is a room to compare notes with people running the same plays.

Leave with a clear sense of how to reach your target customers, and what to stop doing.

For founders, sales leaders, and field marketers.', ARRAY['https://aiweek.boston/schedule/ai-in-sales-selling-hasnt-changed-the-tools-have']::text[], now()),
  ('thriving-in-the-age-of-ai-the-intersection-of-business-higher-education-and-tech@aiweek.boston', 'Thriving in the age of AI: The intersection of business, higher education and technological disruption.', 'https://aiweek.boston/schedule/thriving-in-the-age-of-ai-the-intersection-of-business-higher-education-and-tech', 'https://my.hult.edu/s/eventregistration?eid=701TO00000q1Ok2', TRUE, '2026-09-29T18:00:00-04:00'::timestamptz, '2026-09-29T20:00:00-04:00'::timestamptz, 'Hult International Business School', '1 Education St, Cambridge MA 02141', 'Cambridge', 'Conference', 'Hult International Business School', '[]'::jsonb, 'Thriving in the age of AI: The intersection of business, higher education and technological disruption.', 'Did you miss our amazing, energizing, fully sold-out event last year??? No problem, we are doing it again!

Join us at Hult International Business School for an inspiring evening on Generative AI and its impact on business, education, and leadership.

Program Highlights:

- Kickoff Keynotes (6:00 PM)

Opening remarks from Hult Deans and AI experts, setting the stage with a visionary look at how Generative AI is redefining businesses and the skills needed for tomorrow''s leaders.

- Lightning Talks (6:25 PM)

A series of fast-paced 5-minute talks focused on the impact of Generative AI on business education.

- Hult Student Demos (7:00 PM)

Spotlight on standout projects where Hult undergraduate and postgraduate students use AI tools to address real business challenges, showcasing creativity, problem-solving, and applied innovation.

- Power Panel Discussion (7:20 PM)

A high-energy conversation with faculty, entrepreneurs, corporate executives, and student leaders, sharing insights on how AI is reshaping the workplace and education.

Location: Hult International Business School, 1 Education St, Cambridge, MA 02141

Date & Time: September 29th, 6 to 8 PM

Don''t miss this opportunity to explore how AI is shaping the future. Secure your spot today!', ARRAY['https://aiweek.boston/schedule/thriving-in-the-age-of-ai-the-intersection-of-business-higher-education-and-tech']::text[], now()),
  ('event-hosts-friends@aiweek.boston', 'Event Hosts & Friends', 'https://aiweek.boston/schedule/event-hosts-friends', 'https://luma.com/ngp02f2t', TRUE, '2026-09-29T18:00:00-04:00'::timestamptz, '2026-09-29T22:00:00-04:00'::timestamptz, '(venue revealed upon registration approval)', '(address revealed upon registration approval)', NULL, 'Meetup', 'Dune IRL', '[]'::jsonb, 'Event Hosts & Friends', 'Event Hosts & Friends is a casual get-together for event hosts to swap stories, trade ideas, and enjoy some good vibes together. If you spend your time bringing people into rooms, managing the flow, solving last-minute surprises, or creating memorable nights, this is a great chance to unwind with others who get it.

We’ll be meeting in Boston for a fun, easy gathering of conversation and connection. Come by to share a recent win, a lesson learned, a hilarious hosting moment, or simply hang out and meet fellow hosts and friends. Expect a relaxed, upbeat atmosphere with plenty of room for good conversation and new familiar faces.

Grab a drink, hang out, and enjoy the views.

Dune IRL connects events with sponsors. Sign up for the waitlist at duneirl.com.', ARRAY['https://aiweek.boston/schedule/event-hosts-friends']::text[], now()),
  ('starburst-ai-meetup-building-an-agent-for-your-data-the-good-the-bad-the-ugly@aiweek.boston', 'Starburst AI Meetup: Building an agent for your data - the good, the bad, the ugly', 'https://aiweek.boston/schedule/starburst-ai-meetup-building-an-agent-for-your-data-the-good-the-bad-the-ugly', 'https://www.meetup.com/trino-americas/events/316378241/?utm_medium=referral&utm_campaign=boston-ai-week&utm_source=link&utm_version=v2', TRUE, '2026-09-29T18:00:00-04:00'::timestamptz, '2026-09-29T21:00:00-04:00'::timestamptz, 'Starburst HQ', '101 Federal Street, Boston, MA 02210', 'Boston', 'Community', 'Starburst', '[{"name":"Alex Albu","bio":"Sr. Staff Engineer at Starburst; talk on shipping an AI agent on top of a distributed SQL query engine."}]'::jsonb, 'Starburst AI Meetup: Building an agent for your data - the good, the bad, the ugly', 'Come join Starburst at their office in Boston for an AI-centered meetup. We will have food, drinks, and a fun night of talking about building AI Agents! Our speaker for the meetup will be Alex Albu, Sr. Staff Engineer at Starburst.

Here is what he will talk about:

Everyone''s building AI agents that query databases. Most of them work fine on a toy dataset in a demo. Fewer survive contact with real enterprise data – distributed across dozens of sources, governed by access controls, queried by users who have no idea what the schema looks like. Even fewer have to do that using a wide variety of models.

This talk is about what we actually learned shipping an AI agent on top of a distributed SQL query engine at Starburst. We''ll cover the specific ways things broke and how we fixed them. You''ll leave with an honest picture of what production AI agent work looks like, and a handful of specific techniques that made a real difference.

Agenda for the meetup: 6:00 PM - Network

6:30 PM - Alex Albu''s session

7:00 PM - *Potential additional speaker

7:30 PM - Networking, games, and drinks', ARRAY['https://aiweek.boston/schedule/starburst-ai-meetup-building-an-agent-for-your-data-the-good-the-bad-the-ugly']::text[], now()),
  ('executive-dinner-the-future-of-ai@aiweek.boston', 'Executive Dinner - The Future of AI', 'https://aiweek.boston/schedule/executive-dinner-the-future-of-ai', 'https://mbexec.com/executive-dinner-exploring-whats-next-in-tech-ai/', TRUE, '2026-09-29T18:30:00-04:00'::timestamptz, '2026-09-29T21:30:00-04:00'::timestamptz, 'Davios', '75 Arlington St, Boston, MA 02116', 'Boston', 'Talk', 'Wells Fargo', '[]'::jsonb, 'Executive Dinner - The Future of AI', 'Join us for an exclusive, Jeffersonian-style dinner designed for leading executives in the technology sector. This intimate gathering will create a space for meaningful conversation, allowing industry leaders to engage in insightful discussions on the future of technology and AI. With a guided format that fosters cohesive and thoughtful dialogue, each attendee will have the opportunity to share their perspectives, explore emerging trends, and build valuable connections with fellow executives', ARRAY['https://aiweek.boston/schedule/executive-dinner-the-future-of-ai']::text[], now()),
  ('growing-revenue-enterprise-gtm-ai-infrastructure-2026@aiweek.boston', 'Growing Revenue with an Enterprise Go-to-Market AI Infrastructure', 'https://aiweek.boston/schedule/growing-revenue-enterprise-gtm-ai-infrastructure-2026', 'https://go.marketgrowthconsulting.com/boston-ai-week-registration', TRUE, '2026-09-30T07:30:00-04:00'::timestamptz, '2026-09-30T10:30:00-04:00'::timestamptz, 'Rocket Software Office', '77 Fourth Avenue, Waltham, MA 02451', 'Waltham', 'Panel', 'Market Growth Consulting', '[{"name":"Emma Harney","bio":"Director of Digital Experience & AI Strategy at Rocket Software."},{"name":"Pam Boiros","bio":"Co-Founder & CMO of Women Applying AI."},{"name":"Sumi Singh","bio":"Chief AI Officer at Market Growth Consulting."}]'::jsonb, 'Growing Revenue with an Enterprise Go-to-Market AI Infrastructure', 'For marketing and sales leaders: turn AI from a line item to a revenue engine.

Moving from experiment to production comes down to two things: your people (adoption and change management) and your technology (infrastructure and data). Get them right, and AI compounds into faster, more efficient revenue. Get them wrong, and it stalls out after the pilot. We''ll dig into both, and what it takes to solve them.

Your people: adoption and change management

The technology changes faster than teams can keep up. The learning curve is steep for technical and non-technical staff alike, documentation lags behind, and existing workflows were built for humans, not AI.

What you''ll take away: A practical way to get your team using AI every day, so the new skills and habits stick instead of fading after the kickoff.

Your technology: infrastructure and data

Tool sprawl, siloed data that isn''t AI-ready, procurement, security and compliance reviews, and cost uncertainty all slow teams down.

What you''ll take away: How to build a go-to-market AI infrastructure that scales, how to get your data AI-ready, and how to navigate the IT, CISO and engineering conversations.

Join us for breakfast, a candid practitioner conversation, and a facilitated roundtable to move your own initiatives forward.

Hosted by Market Growth Consulting at the Rocket Software office in Waltham, MA.', ARRAY['https://aiweek.boston/schedule/growing-revenue-enterprise-gtm-ai-infrastructure-2026']::text[], now()),
  ('bdmt-global-innovator-summit-2026-day-3@aiweek.boston', 'BDMT Global Innovator Summit — Day 3 (Wed)', 'https://aiweek.boston/schedule/bdmt-global-innovator-summit-2026-day-3', 'https://bdmtglobal.com/bdmt-global-innovator-summit-2026/', TRUE, '2026-09-30T08:00:00-04:00'::timestamptz, '2026-09-30T18:00:00-04:00'::timestamptz, 'Hynes Convention Center', '900 Boylston Street, Boston, MA', 'Boston', 'Conference', 'BDMT Global', '[]'::jsonb, 'BDMT Global Innovator Summit — Day 3 (Wed)', 'The BDMT Global Innovator Summit 2026 brings together cutting-edge innovators across industries with U.S. and global ecosystem leaders to identify collaboration opportunities and mutually drive growth in the U.S. and other new markets. Unlike massive trade shows where you can easily get lost in the noise, this summit prioritizes quality over quantity, offering a curated environment for meaningful connections and measurable outcomes. Many innovators have a core AI-driven solution, and virtually all are applying AI in some way.', ARRAY['https://aiweek.boston/schedule/bdmt-global-innovator-summit-2026-day-3']::text[], now()),
  ('gai-world-2026-day-3@aiweek.boston', 'GAI World 2026 — Day 3', 'https://aiweek.boston/schedule/gai-world-2026-day-3', 'https://www.gaiworld.com/buy-passes', TRUE, '2026-09-30T09:00:00-04:00'::timestamptz, '2026-09-30T17:00:00-04:00'::timestamptz, 'Hynes Convention Center', NULL, NULL, 'Conference', 'GAI Insights', '[]'::jsonb, 'GAI World 2026 — Day 3', 'Details coming soon. Add this event to your calendar and check back.', ARRAY['https://aiweek.boston/schedule/gai-world-2026-day-3']::text[], now()),
  ('ai-blueprint-for-massachusetts@aiweek.boston', 'AI Blueprint for Massachusetts', 'https://aiweek.boston/schedule/ai-blueprint-for-massachusetts', 'https://aiweek.boston/schedule/ai-blueprint-for-massachusetts', FALSE, '2026-09-30T09:00:00-04:00'::timestamptz, '2026-09-30T12:00:00-04:00'::timestamptz, NULL, NULL, 'Boston', NULL, NULL, '[]'::jsonb, 'AI Blueprint for Massachusetts', 'A working session uniting government, industry, and academia on the Commonwealth''s path to AI leadership. The AI Blueprint brings policymakers, founders, researchers, and operators into the same room to align on how Massachusetts builds, adopts, and governs AI responsibly — and turns its density of talent and capital into durable economic and workforce advantage.

What to expect

- Cross-sector working sessions

- A focus on responsible adoption and workforce readiness

- Practical alignment between policy, industry, and academia

Who it''s for

- Government and civic leaders

- Industry and enterprise

- Universities and research

Details

- Part of Boston AI Week 2026 (Sept 24 – Oct 2)

- Date, venue, and agenda — announced closer to the festival.', ARRAY['https://aiweek.boston/schedule/ai-blueprint-for-massachusetts']::text[], now()),
  ('mit-futurefest-2026-day-1@aiweek.boston', 'MIT Future Fest — Day 1: Futures in Motion', 'https://aiweek.boston/schedule/mit-futurefest-2026-day-1', 'https://mitfuturefest.org/festival-passes', TRUE, '2026-09-30T10:00:00-04:00'::timestamptz, '2026-09-30T21:00:00-04:00'::timestamptz, 'MIT Campus', '77 Massachusetts Avenue, Cambridge, MA 02139', 'Cambridge', 'Community', 'MIT Future Fest (MIT Museum, MIT Technology Review & MIT Morningside Academy for Design)', '[]'::jsonb, 'MIT Future Fest — Day 1: Futures in Motion', 'Part of MIT Future Fest, the inaugural five-day festival where MIT opens its doors to the world — more than 50 events across campus spanning immersive exhibitions, open laboratories, public talks, and unexpected performances, presented by the MIT Museum, MIT Technology Review, and the MIT Morningside Academy for Design. One festival pass covers all five days. Session times vary; the full program launches August 17 at mitfuturefest.org/program.

Future Fest opens with a keynote gathering of MIT visionaries and international headliners setting the tone for five days of building the future together. As evening falls, the MIT Museum launches its new season with Sensing Oceans, an immersive exhibition on how tools, bodies, and media make the unseen ocean visible.', ARRAY['https://aiweek.boston/schedule/mit-futurefest-2026-day-1']::text[], now()),
  ('executive-inquiry-lab-collective-sensemaking-in-the-age-of-ai@aiweek.boston', 'Executive Inquiry Lab: Collective Sensemaking in the Age of AI', 'https://aiweek.boston/schedule/executive-inquiry-lab-collective-sensemaking-in-the-age-of-ai', 'https://docs.google.com/forms/d/1Hj9c--nBtv9eqDyxfj3DEO87MkvKrjxeL2gS5HY3rDw/viewform', TRUE, '2026-09-30T11:30:00-04:00'::timestamptz, '2026-09-30T13:00:00-04:00'::timestamptz, 'MIT Sloan School of Management, Building E62-233', '100 Main Street, Cambridge, MA 02142', 'Cambridge', 'Talk', 'MIT Sloan CIO Symposium', '[]'::jsonb, 'Executive Inquiry Lab: Collective Sensemaking in the Age of AI', 'How can executives make better decisions in an age of abundant intelligence?

Join us for the first public experiment in a new model of executive learning that combines human conversation, AI-assisted synthesis, editorial judgment, and continuous sensemaking.

Rather than listening to presentations, you''ll participate in a facilitated executive inquiry exploring human judgment in an age of abundant intelligence using the MIT Sloan CIO Symposium Inquiry Framework. Along the way, you''ll experience how structured dialogue and AI can help groups surface new perspectives, identify patterns, and deepen collective understanding of complex leadership challenges.

The session concludes with a live AI synthesis of the discussion, followed by audience reflection on what the AI captured, what it missed, and what insights emerge when human and machine perspectives are considered together.

Because this is an interactive working session, participation is limited to 40 executives and thought leaders. Attendance is by request so that we can create a diverse and highly engaging discussion.', ARRAY['https://aiweek.boston/schedule/executive-inquiry-lab-collective-sensemaking-in-the-age-of-ai']::text[], now()),
  ('your-first-digital-employee-building-an-ai-agent-that-actually-does-the-work@aiweek.boston', 'Your First Digital Employee: Building an AI Agent That Actually Does the Work', 'https://aiweek.boston/schedule/your-first-digital-employee-building-an-ai-agent-that-actually-does-the-work', 'https://www.airocket.pro/boston-ai-week', TRUE, '2026-09-30T12:00:00-04:00'::timestamptz, '2026-09-30T13:00:00-04:00'::timestamptz, NULL, NULL, 'Boston', 'Workshop', 'AI Rocket', '[{"name":"Tim Regan","bio":"Founder of AI Rocket in Waltham, Massachusetts, where he builds digital employees — autonomous AI agents that run real operational work for small and mid-size businesses. He has no coding background and ships a new production system most weeks."}]'::jsonb, 'Your First Digital Employee: Building an AI Agent That Actually Does the Work', 'Most small businesses have tried a chatbot and been underwhelmed. This session is about the next thing: autonomous agents that complete real work end to end — processing an order, qualifying a lead, chasing a follow-up, writing the report — without a human in the loop for every step.

We''ll build one live. Starting from a real operations workflow, we''ll map the decision points, wire the agent, and show what it looks like in production, including the parts that break and how you guard against them. No code. Attendees leave with the workflow map and the guardrail checklist we use on client builds.', ARRAY['https://aiweek.boston/schedule/your-first-digital-employee-building-an-ai-agent-that-actually-does-the-work']::text[], now()),
  ('ai-software-vs-physical-ai-potential-and-reality@aiweek.boston', 'AI Software vs. Physical AI: Potential and Reality', 'https://aiweek.boston/schedule/ai-software-vs-physical-ai-potential-and-reality', 'https://aiweek.boston/schedule/ai-software-vs-physical-ai-potential-and-reality', FALSE, '2026-09-30T12:00:00-04:00'::timestamptz, '2026-09-30T15:00:00-04:00'::timestamptz, 'Glasswing Ventures', '275 Newbury St, FL 2, Boston, MA 02116', 'Boston', 'Panel', 'Glasswing Ventures', '[]'::jsonb, 'AI Software vs. Physical AI: Potential and Reality', 'Join Glasswing Ventures and HSBC Innovation Banking for a conversation exploring the evolving landscape of physical AI. We’ll explore how physical AI is revolutionizing the way people and businesses interact with technology, and where the biggest market opportunities are and will be in the future.

The program will feature an opening panel followed by brief founder fireside conversations, highlighting companies approaching Physical AI from different perspectives. Attendees will also have the opportunity to connect with founders, operators, investors, and leaders across Boston’s AI ecosystem over a light lunch.

Additional speakers and event details coming soon!', ARRAY['https://aiweek.boston/schedule/ai-software-vs-physical-ai-potential-and-reality']::text[], now()),
  ('boat-rides-boston-harbor-captain-chris-2026-09-30@aiweek.boston', 'Boat Rides of Boston Harbor with Captain Chris', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-30', 'https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-30', FALSE, '2026-09-30T12:00:00-04:00'::timestamptz, '2026-09-30T13:00:00-04:00'::timestamptz, 'Fan Pier', 'Fan Pier, Boston, MA', 'Boston', 'Meetup', 'Boston AI Week', '[]'::jsonb, 'Boat Rides of Boston Harbor with Captain Chris', 'Join Captain Chris for a boat ride on Boston Harbor, offered every day of Boston AI Week''s core week (September 24 – October 2). Very limited availability. RSVP to be considered, we''ll work with Captain Chris on approvals. Due to expected demand, not all RSVPs will be honored, but we''ll do our best.

Time: TBA. This is a request, not a confirmed spot — organizers will follow up if your RSVP is approved.', ARRAY['https://aiweek.boston/schedule/boat-rides-boston-harbor-captain-chris-2026-09-30']::text[], now()),
  ('mvp-workshop-for-entrepreneurs@aiweek.boston', 'MVP Workshop for Entrepreneurs', 'https://aiweek.boston/schedule/mvp-workshop-for-entrepreneurs', 'https://conjure.work/#workshop', TRUE, '2026-09-30T13:00:00-04:00'::timestamptz, '2026-09-30T16:00:00-04:00'::timestamptz, 'Boston Public Library', '700 Boylston Street, Boston, MA 02116', 'Boston', 'Workshop', 'Conjure AI', '[{"name":"Sid Probstein","bio":"Founder of Conjure."}]'::jsonb, 'MVP Workshop for Entrepreneurs', 'Six entrepreneurs each get five minutes to pitch the MVP they wish existed. The room votes. Then the Conjure factory starts building the winning MVP live, on screen, while you watch how it works. The winner leaves with a working product being built for them, free, source included.

Wednesday, September 30, 1 to 4 PM, Boston Public Library, Copley Square. Free.

Register at conjure.work.', ARRAY['https://aiweek.boston/schedule/mvp-workshop-for-entrepreneurs']::text[], now()),
  ('who-ai-cant-see-two-tedx-voices-on-what-ai-gets-wrong-leaves-out-and-why-it-matt@aiweek.boston', 'Who AI Can''t See: Two TEDx Voices on What AI Gets Wrong, Leaves Out, and Why It Matters', 'https://aiweek.boston/schedule/who-ai-cant-see-two-tedx-voices-on-what-ai-gets-wrong-leaves-out-and-why-it-matt', 'https://luma.com/bchscf1g', TRUE, '2026-09-30T13:00:00-04:00'::timestamptz, '2026-09-30T14:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Talk', 'LiveWire Collaborative', '[{"name":"Angela Pitter","bio":"Founder and CEO of LiveWire Collaborative; spent 25 years in global technology leadership before founding the firm in 2012, has trained more than 5,000 leaders on responsible AI use, and delivered the TEDxRoxbury talk AI and Digital Erasure."},{"name":"Shana Feggins","bio":"Executive Strategist and Co-Founder of catalyst noir; advises leaders on workforce strategy and organizational effectiveness in Big Four consulting, and delivered the TEDxRoxbury talk Rewriting AI''s Future for All."}]'::jsonb, 'Who AI Can''t See: Two TEDx Voices on What AI Gets Wrong, Leaves Out, and Why It Matters', 'What if the biggest risk of AI isn''t what it gets wrong about you, but whether it sees you at all?

A qualified candidate never makes the shortlist.

A neighborhood disappears from the recommendations.

A small business loses customers it never knew were looking.

A community organization never reaches the funder searching for exactly what it does.

No rejection. No notification. No obvious moment when something went wrong.

You simply weren''t in the answer.

A year apart on the TEDxRoxbury stage, Shana Feggins and Angela Pitter came at this from opposite ends.

Shana Feggins, in Rewriting AI''s Future for All, looked at the people behind the machine: who builds AI, whose perspectives shape its choices, and what happens when human blind spots make their way into systems increasingly used for hiring, lending, healthcare, and other consequential decisions. Her warning: AI has no morals. Humans do.

Angela Pitter looked beneath it, at the information AI has to work with. Her talk, AI and Digital Erasure: The New Redlining We''re Not Talking About, asks what happens when the people, businesses, and whole communities AI should know about are missing, poorly represented, or difficult for these systems to find and verify.

They ended up asking the same question:

Who does AI see, who does it leave out, and what happens when you''re missing from the answer?

Sometimes AI has information about you and gets the story wrong. Sometimes the evidence it needs to see you clearly isn''t there. As AI increasingly shapes what gets discovered, recommended, and funded, that difference matters.

For Boston AI Week, Shana and Angela bring these two ideas together for the first time.

This isn''t a replay of two talks. It''s a live conversation, followed by open Q&A.

Join us on Zoom to be in the room: ask your question, share what you''re seeing, or just listen in.

Prefer to watch? We''ll stream live on LinkedIn and bring questions from the comments into the conversation.

Bring the example that makes you wonder: Does AI actually see the world I know?

Wednesday, September 30, 2026 · 1:00 PM ET · Online · Free and open to all', ARRAY['https://aiweek.boston/schedule/who-ai-cant-see-two-tedx-voices-on-what-ai-gets-wrong-leaves-out-and-why-it-matt']::text[], now()),
  ('mvp-workshop-for-founders@aiweek.boston', 'MVP Workshop for Founders', 'https://aiweek.boston/schedule/mvp-workshop-for-founders', 'https://aiweek.boston/schedule/mvp-workshop-for-founders', FALSE, '2026-09-30T13:00:00-04:00'::timestamptz, '2026-09-30T16:00:00-04:00'::timestamptz, 'TBA', 'TBA', NULL, 'Workshop', 'Team Conjure AI', '[{"name":"Sid Probstein","bio":null}]'::jsonb, 'MVP Workshop for Founders', 'Location TBA, near Copley Square', ARRAY['https://aiweek.boston/schedule/mvp-workshop-for-founders']::text[], now()),
  ('lab-to-launch-rooftop-edition@aiweek.boston', 'Lab to Launch: Rooftop Edition', 'https://aiweek.boston/schedule/lab-to-launch-rooftop-edition', 'https://aiweek.boston/schedule/lab-to-launch-rooftop-edition', FALSE, '2026-09-30T16:00:00-04:00'::timestamptz, '2026-09-30T19:00:00-04:00'::timestamptz, 'Felipe''s Taqueria (roof deck)', '21 Brattle Street, Harvard Square, Cambridge, MA 02138', 'Cambridge', 'Meetup', 'HBS Foundry, Goodwin, and Silicon Valley Bank', '[]'::jsonb, 'Lab to Launch: Rooftop Edition', 'Boston builds some of the hardest technology in the world, then keeps its founders in separate buildings. For one evening, we''re fixing that.

Join HBS Foundry, Goodwin LLC, and Silicon Valley Bank on the rooftop deck at Felipe''s in Harvard Square for a night with founders from the MIT, Harvard, and Foundry ecosystems — plus the investors, organizers, and bankers who help them get off the ground.

Capacity is limited to 103 guests.', ARRAY['https://aiweek.boston/schedule/lab-to-launch-rooftop-edition']::text[], now()),
  ('an-evening-with-bostons-ai-data-leaders@aiweek.boston', 'An Evening with Boston''s AI & Data Leaders', 'https://aiweek.boston/schedule/an-evening-with-bostons-ai-data-leaders', 'https://www.starburst.io/info/an-evening-with-bostons-ai-data-leaders/?utm_medium=event&utm_source=field&utm_campaign=NORAM-FY27-Q3-EV-Boston-AI-Week-Exec-Event&utm_content=BAW-invite', TRUE, '2026-09-30T16:30:00-04:00'::timestamptz, '2026-09-30T19:30:00-04:00'::timestamptz, 'Seaport District, Venue to be provided with registration.', 'Seaport District, Boston', 'Boston', 'Panel', 'Starburst Data', '[]'::jsonb, 'An Evening with Boston''s AI & Data Leaders', 'Hosted by Starburst — a candid, high-level conversation with the CDOs and data leaders shaping enterprise AI strategy right now.

Join Starburst and local Boston AI & Data Leaders during Boston AI Week for an executive reception featuring an Enterprise Executive Panel.

About the Panel

Enterprise leaders are navigating one of the most consequential shifts in how organizations run — deciding where to invest, what to prioritize, and how to move forward with confidence. This panel brings together local CDOs and data leaders for an open, high-level conversation on how they’re approaching that shift in their own organizations.

We’ll hear directly from leaders shaping AI strategy in real time — where they’re focused, what’s proving harder than expected, and how they’re thinking about what comes next.', ARRAY['https://aiweek.boston/schedule/an-evening-with-bostons-ai-data-leaders']::text[], now()),
  ('ai-go-to-market-from-first-customers-to-repeatable-growth@aiweek.boston', 'AI Go-to-Market: From First Customers to Repeatable Growth', 'https://aiweek.boston/schedule/ai-go-to-market-from-first-customers-to-repeatable-growth', 'https://luma.com/eikrfzd2', TRUE, '2026-09-30T17:00:00-04:00'::timestamptz, '2026-09-30T19:00:00-04:00'::timestamptz, 'Venture Lane | Startup Hub', '55 Court St Floor 2, Boston, MA 02108', 'Boston', 'Panel', 'Venture Lane', '[]'::jsonb, 'AI Go-to-Market: From First Customers to Repeatable Growth', 'This panel is for early-stage B2B founders who have real customer traction but are still relying on manual processes, founder-led sales, and instinct to grow. We''ll discuss what to automate first, what should remain human longer than you think, and how to build a repeatable GTM engine without losing the customer insight that got you here.

Join founders and GTM leaders for an honest conversation on what''s actually working for startups today. Hosted by FounderWay and Venture Lane as part of Boston AI Week.', ARRAY['https://aiweek.boston/schedule/ai-go-to-market-from-first-customers-to-repeatable-growth']::text[], now()),
  ('special-olympics-massachusetts-polar-plunge@aiweek.boston', 'Special Olympics Massachusetts Polar Plunge', 'https://aiweek.boston/schedule/special-olympics-massachusetts-polar-plunge', 'https://fundraise.specialolympicsma.org/index.cfm?fuseaction=register.start&eventID=1030', TRUE, '2026-09-30T17:30:00-04:00'::timestamptz, '2026-09-30T19:30:00-04:00'::timestamptz, 'Cicso Brewers in the Seaport', '85 Northern Avenue, Boston, MA', 'Boston', 'Community', 'Special Olymipcs Massachusetts', '[]'::jsonb, 'Special Olympics Massachusetts Polar Plunge', 'Join Special Olympics Massachusetts and Cisco Brewing for our Polar Plunge in the Seaport! Help support the growth an innovation of new program options for athletes in Boston and throughout Massachusetts. Form a team, get C-Suite colleagues to join the Executive Challenge and have a great night! For more information and to register visit SpecialOlympicsMA.org/BostonPolarPlunge', ARRAY['https://aiweek.boston/schedule/special-olympics-massachusetts-polar-plunge']::text[], now()),
  ('the-silence-tax-in-the-ai-era@aiweek.boston', 'The Silence Tax™ in the AI Era', 'https://aiweek.boston/schedule/the-silence-tax-in-the-ai-era', 'https://aiweek.boston/schedule/the-silence-tax-in-the-ai-era', FALSE, '2026-09-30T18:00:00-04:00'::timestamptz, '2026-09-30T20:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Panel', 'Community-hosted', '[]'::jsonb, 'The Silence Tax™ in the AI Era', 'A candid panel on the "silence tax" organizations pay when teams stay quiet about how AI is actually being used, what is working, and what is breaking. Featuring leaders sharing what changed when their orgs started talking openly. Venue confirmation TBA.', ARRAY['https://aiweek.boston/schedule/the-silence-tax-in-the-ai-era']::text[], now()),
  ('pitch-lift-bostons-100000-elevator-pitch-competition@aiweek.boston', 'Pitch Lift: Boston''s $100,000 Elevator Pitch Competition', 'https://aiweek.boston/schedule/pitch-lift-bostons-100000-elevator-pitch-competition', 'https://www.thepitchlift.com', TRUE, '2026-09-30T18:00:00-04:00'::timestamptz, '2026-09-30T21:00:00-04:00'::timestamptz, 'Venue TBD', NULL, NULL, 'Competition', 'Pitch Lift', '[]'::jsonb, 'Pitch Lift: Boston''s $100,000 Elevator Pitch Competition', 'Founders step into an actual elevator with 30 seconds to deliver their pitch — for the chance to walk away with $100,000 in cash. Judges score each pitch on quality, opportunity, and marketability, and the night wraps with high-energy networking. Hosted by Pitch Lift founder Rob Hughes ("Tech Jesus") with co-host Sophia Zhang. Founders who want to compete can apply to pitch at thepitchlift.com.', ARRAY['https://aiweek.boston/schedule/pitch-lift-bostons-100000-elevator-pitch-competition']::text[], now()),
  ('multi-agent-symphony-conductor@aiweek.boston', 'The Multi-Agent Symphony: Operating Parallel Coding Agents with Conductor', 'https://aiweek.boston/schedule/multi-agent-symphony-conductor', 'https://aiweek.boston/schedule/multi-agent-symphony-conductor', FALSE, '2026-09-30T18:00:00-04:00'::timestamptz, '2026-09-30T20:00:00-04:00'::timestamptz, NULL, NULL, NULL, 'Meetup', 'Community-hosted', '[{"name":"Jesse Waites","bio":"Practitioner-focused talk on operating parallel coding agents with Conductor."}]'::jsonb, 'The Multi-Agent Symphony: Operating Parallel Coding Agents with Conductor', 'AI coding agents are quickly moving beyond the one-developer, one-agent model. Tools like Conductor, a Y Combinator-backed company building infrastructure for managing teams of coding agents, make it possible to run multiple agents simultaneously across isolated workspaces, assign them independent tasks, monitor their progress, and review and merge their work back into a real codebase.

In this practitioner-focused talk from Jesse Waites, we’ll explore what software development looks like when you begin managing a fleet of AI coding agents rather than working with them one at a time. Using Conductor as our primary example, we’ll cover parallel development with Claude Code, Codex, Cursor, and other agents, along with workspace isolation, Git worktrees, task decomposition, testing, code review, merge strategies, and the new coordination problems that emerge when several agents are writing code at once. We’ll also look beyond Conductor at other approaches to multi-agent development, focusing on the practical patterns that make parallel AI development manageable in real software projects.

We will also be giving out a limited amount of Conductor swag at the event!', ARRAY['https://aiweek.boston/schedule/multi-agent-symphony-conductor']::text[], now()),
  ('pydata-boston-ai-talks@aiweek.boston', 'PyData Boston AI talks', 'https://aiweek.boston/schedule/pydata-boston-ai-talks', 'https://www.meetup.com/pydata-boston-cambridge/events/316514602', TRUE, '2026-09-30T18:30:00-04:00'::timestamptz, '2026-09-30T21:30:00-04:00'::timestamptz, 'Kendall Square in Kendall - see the meetup link for details: https://www.meetup.com/pydata-boston-cambridge/events/316514602', NULL, 'Boston', 'Talk', 'PyData Boston', '[{"name":"Krithika Murugesan","bio":"Talk: Building Agentic AI Systems, introducing the fundamentals of Agentic AI and building autonomous AI systems with LangGraph, LangSmith, and CrewAI."},{"name":"Sebastian Wallkötter","bio":"Talk: The physics behind (self-)hosting LLMs, covering compute, bandwidth, and vRAM dynamics and building a cost model for local LLM deployment."},{"name":"Ananya Sharma","bio":"Talk: Detecting and Mitigating Bias in Automated Mortgage Lending, exploring how automated mortgage models reproduce disparities and how to detect and mitigate algorithmic bias."}]'::jsonb, 'PyData Boston AI talks', 'Join the Boston PyData community as we talk about topics related to AI with an emphasis on open source technology!

We''ll start with an intro to building agents in multiple frameworks, move on to considerations around hosting LLMs and wrap up with a dive into responsible AI. Join us!

Do not arrive before 6:30pm!

Schedule: 6:30–7:00 — Networking (doors open)

7:00–7:10 — Introduction

7:10–7:35 — Krithika Murugesan - Building Agentic AI Systems

7:35-8:00 - Sebastian Wallkötter - The physics behind (self-)hosting LLMs

8:00–8:30 - Break

8:30-8:55 — Ananya Sharma - Detecting and Mitigating Bias in Automated Mortgage Lending

9:30 — End

Krithika Murugesan

Title: Building Agentic AI Systems

Description: In this session, I will introduce the fundamentals of Agentic AI and demonstrate how to build intelligent, autonomous AI systems using modern frameworks such as LangGraph, LangSmith, and CrewAI. Participants will learn how AI agents reason, collaborate, use tools, maintain state, and execute complex workflows through practical examples and architecture patterns.

Sebastian Wallkötter

Title: The physics behind (self-)hosting LLMs

Description: Why do output tokens cost more than input tokens? Why are batch API calls 50% cheaper than normal API calls? Where does the $/M token price come from in the first place? I want to answer this while building a cost model for a local LLM deployment. We''ll cover compute, bandwidth, and vRAM dynamics and the effects of K/V cache, context window, quantization, GQA (grouped-query attention), and multi-request batching. Think of this as a (high-level) behind-the-scenes of a per-token LLM API.

Ananya Sharma

Title: Detecting and Mitigating Bias in Automated Mortgage Lending

Description: How can an AI system discriminate without ever seeing protected attributes? This talk explores how automated mortgage models can reproduce historical lending disparities through proxy variables and biased data. It presents practical approaches for detecting and mitigating algorithmic bias using statistical fairness testing, explainability, model governance, and continuous monitoring', ARRAY['https://aiweek.boston/schedule/pydata-boston-ai-talks']::text[], now()),
  ('women-in-ai-dinner-series-kickoff@aiweek.boston', 'Women D(in)e AI: A Dinner Series Kickoff', 'https://aiweek.boston/schedule/women-in-ai-dinner-series-kickoff', 'https://partiful.com/e/YiEz2KqpiUpIdSZvvE06?c=NkHilUaZ', TRUE, '2026-09-30T19:00:00-04:00'::timestamptz, '2026-09-30T21:00:00-04:00'::timestamptz, 'TBD - Downtown Boston', 'TBD - Downtown Boston', 'Boston', 'Meetup', 'Women D(in)e AI', '[]'::jsonb, 'Women D(in)e AI: A Dinner Series Kickoff', 'We''re gathering an intimate group of women building, investing in, and leading with AI for a seated dinner: real conversation, no name-tag networking, no pitch decks.

Kicking off during Boston AI Week, this is the first of what we hope becomes a regular series — small, considered gatherings for women who want depth over volume.

Space is limited. Request to join via the Partiful link. Come ready to form deep connections with like-minded women!', ARRAY['https://aiweek.boston/schedule/women-in-ai-dinner-series-kickoff']::text[], now()),
  ('pioneers-of-ai-live-2026@aiweek.boston', 'Pioneers of AI Live! with Dr. Rana el Kaliouby and WHOOP Chief Product Officer Ed Baker', 'https://aiweek.boston/schedule/pioneers-of-ai-live-2026', 'https://www.mos.org/events/pioneers-ai-live', TRUE, '2026-09-30T19:00:00-04:00'::timestamptz, '2026-09-30T21:00:00-04:00'::timestamptz, 'Museum of Science, Boston — Blue Wing', '1 Science Park, Boston, MA 02114', 'Boston', 'Community', 'Museum of Science, Boston, with the Harvard Business School Association of Boston and AI Blueprint for MA', '[]'::jsonb, 'Pioneers of AI Live! with Dr. Rana el Kaliouby and WHOOP Chief Product Officer Ed Baker', 'Join AI scientist, investor, and host of the Pioneers of AI podcast Dr. Rana el Kaliouby for a special live taping at the Museum of Science, Boston, featuring WHOOP Chief Product Officer Ed Baker.

Be part of the live audience for an engaging program on how AI unlocks our personal health data – and prompts new dialogue on how to use that data. Explore the concept of a "healthspan," and dive into the innovations driving wearable technology.

This special taping is part of Boston AI Week and presented in partnership with the Harvard Business School Association of Boston and AI Blueprint for MA.

Free with pre-registration. Adults 18+.', ARRAY['https://aiweek.boston/schedule/pioneers-of-ai-live-2026']::text[], now()),
  ('tedxboston-longevity-2026@aiweek.boston', 'TEDxBoston: Longevity', 'https://aiweek.boston/schedule/tedxboston-longevity-2026', 'https://aiweek.boston/schedule/tedxboston-longevity-2026', FALSE, '2026-10-01T00:00:00-04:00'::timestamptz, '2026-10-02T00:00:00-04:00'::timestamptz, 'TBD (to be announced)', NULL, NULL, 'Conference', 'TEDxBoston', '[]'::jsonb, 'TEDxBoston: Longevity', 'TEDxBoston presents Longevity — an evening of TEDx-style talks exploring how artificial intelligence is reshaping human healthspan, performance, and the science of living longer.

Hosts: TEDxBoston, John Werner, Boston AI Week, and WHOOP.

