  ('dataiq-peer-exchange-boston-2026@aiweek.boston', 'DataIQ Peer Exchange — Boston', 'https://aiweek.boston/schedule/dataiq-peer-exchange-boston-2026', 'https://www.dataiq.global/2026-boston-peer-exchange/#form', TRUE, '2026-10-01T08:30:00-04:00'::timestamptz, '2026-10-01T17:00:00-04:00'::timestamptz, 'The Quin House', 'The Quin House, Boston, MA', 'Boston', 'Conference', 'DataIQ', '[]'::jsonb, 'DataIQ Peer Exchange — Boston', 'DataIQ Peer Exchange brings together ~40 senior enterprise data and AI leaders for a confidential, application-only discussion on how leading organizations are turning AI investment into measurable business outcomes.

